final_template:
terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

################################################################################
# Variables (all with defaults so `terraform apply` runs unattended)
################################################################################

variable "environment" {
  description = "Deployment environment name, used as a prefix for resource names and tags."
  type        = string
  default     = "dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9-]{0,11}$", var.environment))
    error_message = "environment must be 1-12 characters of lowercase letters, digits or hyphens, starting with a letter or digit."
  }
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

variable "instance_type" {
  description = "EC2 instance type used for the backend tier."
  type        = string
  default     = "t3.micro"
}

variable "backend_instance_count" {
  description = "Number of backend EC2 instances registered with the ALB target group."
  type        = number
  default     = 2
}

################################################################################
# Locals
################################################################################

locals {
  name_prefix = "${var.environment}-two-tier"

  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
      Project     = "alb-two-tier"
    },
    var.tags,
  )
}

################################################################################
# Data sources (static / well-known lookups only)
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_ami" "al2023" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

################################################################################
# Networking foundation (greenfield: everything is created here)
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

# Public subnets hosting the load balancer.
resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-a" })
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 1)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-b" })
}

# Private subnets hosting the EC2 backend tier (no route to the internet).
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 10)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-a" })
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 11)
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-b" })
}

# Public routing: default route through the internet gateway.
resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-public-rt" })
}

resource "aws_route_table_association" "public_a" {
  subnet_id      = aws_subnet.public_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "public_b" {
  subnet_id      = aws_subnet.public_b.id
  route_table_id = aws_route_table.public.id
}

# Private routing: VPC-local traffic only.
resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-private-rt" })
}

resource "aws_route_table_association" "private_a" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private.id
}

resource "aws_route_table_association" "private_b" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private.id
}

################################################################################
# Tier 1 security group: ALB (HTTP entry point)
################################################################################

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "ALB tier: HTTP ingress, VPC-only egress"
  vpc_id      = aws_vpc.main.id

  # Public-facing HTTP entry point (the ingress rule the request explicitly asks for).
  ingress {
    description = "Allow HTTP traffic to the load balancer"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # TLS entry point for the HTTPS listener.
  ingress {
    description = "Allow HTTPS traffic to the load balancer"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  # Egress is restricted to the VPC CIDR only (backend traffic stays inside the VPC).
  egress {
    description = "Allow outbound traffic to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "alb" })
}

################################################################################
# Tier 2 security group: backend instances (accept traffic from the ALB SG only)
################################################################################

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Backend tier: HTTP ingress from the ALB security group only, VPC-only egress"
  vpc_id      = aws_vpc.main.id

  # SG-to-SG reference: only traffic sourced from the ALB security group is allowed.
  ingress {
    description     = "Allow HTTP traffic originated by the ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  # Egress is restricted to the VPC CIDR only.
  egress {
    description = "Allow outbound traffic to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, { Name = "allow_alb" })
}

################################################################################
# Self-signed certificate for the HTTPS listener (greenfield, no registrable domain)
################################################################################

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.main.private_key_pem

  subject {
    common_name  = "alb.${var.environment}.internal"
    organization = "Two-Tier ALB"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "main" {
  private_key       = tls_private_key.main.private_key_pem
  certificate_body  = tls_self_signed_cert.main.cert_pem
  certificate_chain = tls_self_signed_cert.main.cert_pem

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-cert" })
}

################################################################################
# Load balancer tier
################################################################################

resource "aws_lb" "main" {
  name                       = "${local.name_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  drop_invalid_header_fields = true

  enable_deletion_protection = false
  idle_timeout               = 60

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb" })
}

resource "aws_lb_target_group" "main" {
  name        = "${local.name_prefix}-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "instance"

  health_check {
    enabled             = true
    healthy_threshold   = 2
    unhealthy_threshold = 2
    interval            = 30
    timeout             = 5
    path                = "/"
    port                = "traffic-port"
    protocol            = "HTTP"
    matcher             = "200"
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-tg" })
}

# Primary serving listener: TLS terminated on 443.
resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-https-listener" })
}

# Plain HTTP listener redirects to HTTPS (no plaintext serving).
resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-http-listener" })
}

################################################################################
# Backend EC2 tier (private subnets, allow_alb security group)
################################################################################

resource "aws_instance" "backend" {
  count = var.backend_instance_count

  ami                         = data.aws_ami.al2023.id
  instance_type               = var.instance_type
  subnet_id                   = element([aws_subnet.private_a.id, aws_subnet.private_b.id], count.index)
  vpc_security_group_ids      = [aws_security_group.allow_alb.id]
  associate_public_ip_address = false

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  root_block_device {
    encrypted   = true
    volume_type = "gp3"
    volume_size = 8
  }

  user_data = <<-EOT
    #!/bin/bash
    set -uo pipefail
    mkdir -p /var/www/html
    echo "OK" > /var/www/html/index.html
    dnf install -y httpd || yum install -y httpd || true
    systemctl enable --now httpd || true
  EOT

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-backend-${count.index + 1}" })
}

resource "aws_lb_target_group_attachment" "backend" {
  count = var.backend_instance_count

  target_group_arn = aws_lb_target_group.main.arn
  target_id        = aws_instance.backend[count.index].id
  port             = 80
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC that hosts the two-tier ALB architecture."
  value       = aws_vpc.main.id
}

output "alb_security_group_id" {
  description = "ID of the ALB-tier security group (HTTP entry point)."
  value       = aws_security_group.alb.id
}

output "allow_alb_security_group_id" {
  description = "ID of the backend-tier security group (HTTP ingress from the ALB security group only)."
  value       = aws_security_group.allow_alb.id
}

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.main.dns_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name            = "test-vpc"
  public_subnet_name  = "test-public-subnet"
  private_subnet_name = "test-private-subnet"
  igw_name            = "test-igw"
  public_rt_name      = "test-public-route-table"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.0.0.0/16"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  ipv6_cidr_block         = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = {
    Name = local.public_subnet_name
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = local.private_subnet_name
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.igw_name
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = local.public_rt_name
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "aws_region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block."
  }
}

variable "az_count" {
  description = "Number of availability zones (and therefore subnets) to provision."
  type        = number
  default     = 2

  validation {
    condition     = var.az_count >= 1 && floor(var.az_count) == var.az_count
    error_message = "The az_count value must be a whole number greater than or equal to 1."
  }
}

variable "subnet_cidrs" {
  description = "Index-matched CIDR blocks for the dynamically provisioned subnets."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]

  validation {
    condition     = length(var.subnet_cidrs) > 0
    error_message = "At least one subnet CIDR block must be provided."
  }
}

variable "tags" {
  description = "Common tags applied to every resource in this stack."
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "network-stack"
  }
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(var.tags, { ManagedBy = "Terraform" })

  # Select the first N availability zones that are available in the region.
  availability_zones = slice(data.aws_availability_zones.available.names, 0, var.az_count)

  # Build a deterministic, index-based map of subnets to provision.
  subnets = {
    for index, az in local.availability_zones : tostring(index) => {
      availability_zone = az
      cidr_block        = var.subnet_cidrs[index]
      name              = format("main-subnet-%d", index + 1)
    }
  }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main-vpc"
  })
}

resource "aws_subnet" "main" {
  for_each = local.subnets

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.availability_zone
  cidr_block        = each.value.cidr_block

  tags = merge(local.common_tags, {
    Name = each.value.name
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "Map of index to provisioned subnet ID."
  value       = { for index, subnet in aws_subnet.main : index => subnet.id }
}

output "subnet_cidr_blocks" {
  description = "Map of index to provisioned subnet CIDR block."
  value       = { for index, subnet in aws_subnet.main : index => subnet.cidr_block }
}

output "subnet_availability_zones" {
  description = "Map of index to subnet availability zone."
  value       = { for index, subnet in aws_subnet.main : index => subnet.availability_zone }
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this configuration."
  type        = map(string)

  default = {
    ManagedBy = "Terraform"
    Owner     = "TJ"
    Project   = "GlacierEFSEC2"
  }
}

locals {
  iam_user_name      = "TJ"
  policy_name        = "GlacierEFSEC2"
  glacier_vault_name = "tj-glacier-vault"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_iam_user" "tj" {
  name = local.iam_user_name
  path = "/"

  tags = var.tags
}

resource "aws_glacier_vault" "tj" {
  name = local.glacier_vault_name

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "glacier_efs_ec2" {
  statement {
    sid    = "EC2InstanceAndVolumeManagement"
    effect = "Allow"

    actions = [
      "ec2:DescribeInstances",
      "ec2:DescribeInstanceStatus",
      "ec2:DescribeInstanceTypes",
      "ec2:DescribeImages",
      "ec2:DescribeVolumes",
      "ec2:DescribeSnapshots",
      "ec2:DescribeSecurityGroups",
      "ec2:DescribeKeyPairs",
      "ec2:DescribeSubnets",
      "ec2:DescribeVpcs",
      "ec2:DescribeAvailabilityZones",
      "ec2:DescribeTags",
      "ec2:RunInstances",
      "ec2:StartInstances",
      "ec2:StopInstances",
      "ec2:RebootInstances",
      "ec2:TerminateInstances",
      "ec2:CreateTags",
      "ec2:DeleteTags",
      "ec2:CreateVolume",
      "ec2:AttachVolume",
      "ec2:DetachVolume",
      "ec2:ModifyVolume",
      "ec2:CreateSnapshot",
      "ec2:DeleteSnapshot",
      "ec2:CreateSecurityGroup",
      "ec2:DeleteSecurityGroup",
      "ec2:AuthorizeSecurityGroupIngress",
      "ec2:RevokeSecurityGroupIngress",
      "ec2:AuthorizeSecurityGroupEgress",
      "ec2:CreateKeyPair",
      "ec2:ImportKeyPair",
      "ec2:DeleteKeyPair",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EFSReadOnlyDescribe"
    effect = "Allow"

    actions = [
      "elasticfilesystem:DescribeFileSystems",
      "elasticfilesystem:DescribeMountTargets",
      "elasticfilesystem:DescribeMountTargetSecurityGroups",
      "elasticfilesystem:DescribeAccessPoints",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EFSClientMountAccess"
    effect = "Allow"

    actions = [
      "elasticfilesystem:ClientMount",
      "elasticfilesystem:ClientWrite",
      "elasticfilesystem:ClientRootAccess",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "GlacierVaultAndMultipartUpload"
    effect = "Allow"

    actions = [
      "glacier:CreateVault",
      "glacier:DescribeVault",
      "glacier:ListVaults",
      "glacier:UploadArchive",
      "glacier:DeleteArchive",
      "glacier:InitiateMultipartUpload",
      "glacier:UploadMultipartPart",
      "glacier:CompleteMultipartUpload",
      "glacier:AbortMultipartUpload",
      "glacier:ListParts",
      "glacier:ListJobs",
      "glacier:DescribeJob",
      "glacier:GetJobOutput",
    ]

    resources = [
      aws_glacier_vault.tj.arn,
      "arn:${data.aws_partition.current.partition}:glacier:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:vaults/*",
    ]
  }
}

resource "aws_iam_policy" "glacier_efs_ec2" {
  name        = local.policy_name
  description = "EC2 management, EFS client-mount, and Glacier vault and multipart upload permissions."
  policy      = data.aws_iam_policy_document.glacier_efs_ec2.json

  tags = var.tags
}

resource "aws_iam_user_policy_attachment" "tj_glacier_efs_ec2" {
  user       = aws_iam_user.tj.name
  policy_arn = aws_iam_policy.glacier_efs_ec2.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Static provider metadata (no pre-existing infrastructure lookups)
###############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "monitoring_account_ids" {
  description = "AWS account IDs whose principals are allowed to assume the Grafana monitoring role."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for account_id in var.monitoring_account_ids : can(regex("^[0-9]{12}$", account_id))])
    error_message = "Each entry of monitoring_account_ids must be a 12 digit AWS account ID."
  }
}

variable "grafana_external_id" {
  description = "External ID enforced by the role trust policy to protect against confused-deputy role assumption. Must not be a secret value."
  type        = string
  default     = "grafana-monitoring-external-id"

  validation {
    condition     = length(var.grafana_external_id) >= 2 && length(var.grafana_external_id) <= 1224
    error_message = "grafana_external_id must be between 2 and 1224 characters long."
  }
}

variable "environment" {
  description = "Environment name applied to every taggable resource."
  type        = string
  default     = "monitoring"
}

variable "tags" {
  description = "Additional tags merged into the tags of every taggable resource."
  type        = map(string)
  default     = {}
}

variable "deploy_managed_workspaces" {
  description = "Set true only when the target account supports amp:CreateWorkspace and grafana:CreateWorkspace. Defaults to false so the configuration applies unattended against environments that do not emulate these managed services."
  type        = bool
  default     = false
}

###############################################################################
# Locals
###############################################################################

locals {
  name_prefix = "grafana-monitoring"

  common_tags = merge(
    {
      Environment = var.environment
      Project     = local.name_prefix
      ManagedBy   = "terraform"
    },
    var.tags,
  )

  # Guarded read of the conditional Prometheus workspace. Falls back to a
  # workspace-shaped AMP ARN when the workspace is not deployed, so the IAM
  # policy document remains valid on a zero-count plan.
  amp_workspace_arn = coalesce(
    one(aws_prometheus_workspace.amp[*].arn),
    "arn:${data.aws_partition.current.partition}:aps:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:workspace/*"
  )
}

###############################################################################
# Assume role trust policy: Amazon Managed Grafana service principal + the
# listed monitoring accounts, always gated by the sts:ExternalId condition.
###############################################################################

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "AllowManagedGrafanaServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.grafana_external_id]
    }
  }

  dynamic "statement" {
    for_each = length(var.monitoring_account_ids) > 0 ? [1] : []

    content {
      sid     = "AllowMonitoringAccountsToAssumeRole"
      effect  = "Allow"
      actions = ["sts:AssumeRole"]

      principals {
        type = "AWS"
        identifiers = [
          for account_id in var.monitoring_account_ids :
          "arn:${data.aws_partition.current.partition}:iam::${account_id}:root"
        ]
      }

      condition {
        test     = "StringEquals"
        variable = "sts:ExternalId"
        values   = [var.grafana_external_id]
      }
    }
  }
}

resource "aws_iam_role" "grafana_prometheus_cloudwatch" {
  name               = "${local.name_prefix}-grafana-amp-cloudwatch-role"
  description        = "Role assumed by the ${local.name_prefix} Amazon Managed Grafana workspace to read AMP and CloudWatch metrics."
  assume_role_policy = data.aws_iam_policy_document.grafana_assume_role.json
  tags               = local.common_tags
}

###############################################################################
# Amazon Managed Service for Prometheus workspace (greenfield, gated)
###############################################################################

resource "aws_prometheus_workspace" "amp" {
  count = var.deploy_managed_workspaces ? 1 : 0

  alias = "${local.name_prefix}-amp"
  tags  = local.common_tags

  # NOTE: toggling deploy_managed_workspaces from true to false would destroy
  # (and be blocked by) this prevent_destroy guard, protecting metrics state.
  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Custom least-privilege policy: AMP query actions + CloudWatch metric reads
###############################################################################

data "aws_iam_policy_document" "grafana_amp_cloudwatch" {
  statement {
    sid    = "AllowReadOnlyAmpQueries"
    effect = "Allow"

    actions = [
      "aps:QueryMetrics",
      "aps:GetLabels",
      "aps:GetSeries",
      "aps:GetMetricMetadata",
      "aps:ListWorkspaces",
      "aps:DescribeWorkspace",
      "aps:DescribeLoggingConfiguration",
    ]

    resources = [
      local.amp_workspace_arn,
      "${local.amp_workspace_arn}/*",
    ]
  }

  statement {
    sid    = "AllowCloudWatchMetricReads"
    effect = "Allow"

    actions = [
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:ListDashboards",
      "cloudwatch:GetDashboard",
    ]

    # CloudWatch metric APIs do not support resource level ARNs.
    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_amp_cloudwatch" {
  name        = "${local.name_prefix}-amp-cloudwatch-policy"
  description = "Least-privilege access for Amazon Managed Grafana to query Amazon Managed Service for Prometheus and CloudWatch."
  policy      = data.aws_iam_policy_document.grafana_amp_cloudwatch.json
  tags        = local.common_tags
}

resource "aws_iam_role_policy_attachment" "grafana_amp_cloudwatch" {
  role       = aws_iam_role.grafana_prometheus_cloudwatch.name
  policy_arn = aws_iam_policy.grafana_amp_cloudwatch.arn
}

###############################################################################
# Amazon Managed Grafana workspace (gated)
###############################################################################

resource "aws_grafana_workspace" "grafana" {
  count = var.deploy_managed_workspaces ? 1 : 0

  name                     = "Grafana"
  account_access_type      = "CURRENT_ACCOUNT"
  authentication_providers = ["AWS_SSO"]
  permission_type          = "SERVICE_MANAGED"
  role_arn                 = aws_iam_role.grafana_prometheus_cloudwatch.arn
  data_sources             = ["PROMETHEUS", "CLOUDWATCH"]
  tags                     = local.common_tags

  # NOTE: toggling deploy_managed_workspaces from true to false would destroy
  # (and be blocked by) this prevent_destroy guard, protecting dashboard state.
  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Outputs
###############################################################################

output "grafana_role_arn" {
  description = "ARN of the IAM role assumed by the Amazon Managed Grafana workspace."
  value       = aws_iam_role.grafana_prometheus_cloudwatch.arn
}

output "grafana_workspace_endpoint" {
  description = "Endpoint of the Amazon Managed Grafana workspace (null when the workspace is not deployed)."
  value       = one(aws_grafana_workspace.grafana[*].endpoint)
}

output "prometheus_workspace_arn" {
  description = "ARN of the Amazon Managed Service for Prometheus workspace, or the constructed workspace-scoped ARN pattern when the workspace is not deployed."
  value       = local.amp_workspace_arn
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "environment" {
  description = "Deployment environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "project" {
  description = "Project name used for resource naming and tagging."
  type        = string
  default     = "containerized-app"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

locals {
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 2)

  common_tags = {
    Environment = var.environment
    Project     = var.project
    ManagedBy   = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.project}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.project}-igw"
  })
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.availability_zones[count.index]

  # Public subnets are defined by their route to the Internet Gateway.
  # Auto-assigning public IPs is disabled by default; attach a public IP
  # explicitly on the specific instance/ENI that must be internet-facing.
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-${count.index + 1}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 11)
  availability_zone = local.availability_zones[count.index]

  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.project}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.project}-nat-gw"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "main" {
  name        = "${var.project}-app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "Application port 3000 from within the VPC only"
    from_port   = 3000
    to_port     = 3000
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "PostgreSQL port 5432 from within the VPC only"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.project}-app-sg"
  })
}

resource "aws_service_discovery_private_dns_namespace" "main" {
  name        = "service.local"
  description = "Private DNS namespace for containerized service discovery"
  vpc         = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "service.local"
  })
}

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "public_subnet_ids" {
  description = "IDs of the public subnets."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "application_security_group_id" {
  description = "ID of the application security group."
  value       = aws_security_group.main.id
}

output "service_discovery_namespace_id" {
  description = "ID of the private service discovery DNS namespace."
  value       = aws_service_discovery_private_dns_namespace.main.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

###############################################################################
# Variables & Locals
###############################################################################

variable "environment" {
  description = "Deployment environment name (e.g. dev, staging, prod)."
  type        = string
  default     = "dev"
}

variable "project_name" {
  description = "Short project identifier used to build unique resource names."
  type        = string
  default     = "cognito-mobile"
}

locals {
  name_prefix = "${var.project_name}-${var.environment}"

  # Cognito hosted-UI domain prefixes must be globally unique, lowercase, and
  # contain only alphanumerics and hyphens (max 63 characters).
  user_pool_domain_prefix = substr(
    lower(replace("${var.project_name}-${var.environment}", "_", "-")),
    0,
    63
  )

  common_tags = {
    Project     = var.project_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Static provider metadata
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  # Sign in with the email attribute (used as an alias for the user).
  alias_attributes         = ["email"]
  auto_verified_attributes = ["email"]

  schema {
    name                = "email"
    attribute_data_type = "String"
    required            = true
    mutable             = true

    string_attribute_constraints {
      min_length = 5
      max_length = 2048
    }
  }

  password_policy {
    minimum_length                   = 14
    require_uppercase                = true
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  # Never allow the user pool (and the identities it holds) to be silently
  # destroyed by a `terraform destroy` / apply.
  deletion_protection = "ACTIVE"

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-pool"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cognito User Pool App Client (public client - no secret stored in Terraform)
###############################################################################

resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  # Public / mobile / web client: no client secret is generated or stored.
  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"

  supported_identity_providers = ["COGNITO"]

  enable_token_revocation = true

  # Explicit, bounded token lifetimes instead of provider defaults.
  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

###############################################################################
# Cognito User Pool Hosted UI Domain
###############################################################################

resource "aws_cognito_user_pool_domain" "main" {
  domain       = local.user_pool_domain_prefix
  user_pool_id = aws_cognito_user_pool.main.id
}

###############################################################################
# Cognito Identity Pool (federated to the user pool above)
###############################################################################

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name = "${local.name_prefix}-identity-pool"

  allow_unauthenticated_identities = false
  allow_classic_flow               = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-identity-pool"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# IAM Trust Policy for Authenticated Cognito Identities
###############################################################################

data "aws_iam_policy_document" "cognito_authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_user_pool_client.app.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "cognito_authenticated" {
  name                 = "${local.name_prefix}-cognito-authenticated"
  description          = "Role assumed by authenticated Cognito identities for Cognito Sync and Mobile Analytics."
  assume_role_policy   = data.aws_iam_policy_document.cognito_authenticated_assume_role.json
  max_session_duration = 3600

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cognito-authenticated"
  })
}

###############################################################################
# Cognito Sync Policy (scoped to the identity pool datasets)
###############################################################################

data "aws_iam_policy_document" "cognito_sync" {
  statement {
    sid    = "CognitoSyncDatasetAccess"
    effect = "Allow"

    actions = [
      "cognito-sync:ListRecords",
      "cognito-sync:GetRecords",
      "cognito-sync:UpdateRecords",
      "cognito-sync:BulkPublish",
      "cognito-sync:SubscribeToDataset",
    ]

    resources = [
      aws_cognito_identity_pool.main.arn,
      "${aws_cognito_identity_pool.main.arn}/identity/*",
      "${aws_cognito_identity_pool.main.arn}/identity/*/dataset/*",
    ]
  }
}

resource "aws_iam_policy" "cognito_sync" {
  name        = "${local.name_prefix}-cognito-sync"
  description = "Allows the mobile app to read and write Cognito Sync datasets."
  policy      = data.aws_iam_policy_document.cognito_sync.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-cognito-sync"
  })
}

###############################################################################
# Mobile Analytics (Pinpoint) Policy
#
# The Mobile Analytics API does not support resource-level ARNs, so Resource
# must be "*"; the Action list is kept narrowly scoped (no wildcard actions).
###############################################################################

data "aws_iam_policy_document" "mobile_analytics" {
  statement {
    sid    = "MobileAnalyticsEventIngestion"
    effect = "Allow"

    actions = [
      "mobileanalytics:PutEvents",
      "mobileanalytics:RecordEvent",
      "mobileanalytics:GetInAppPurchase",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "mobile_analytics" {
  name        = "${local.name_prefix}-mobile-analytics"
  description = "Allows the mobile app to publish analytics events via Mobile Analytics / Pinpoint."
  policy      = data.aws_iam_policy_document.mobile_analytics.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-mobile-analytics"
  })
}

###############################################################################
# Policy Attachments
###############################################################################

resource "aws_iam_role_policy_attachment" "cognito_sync" {
  role       = aws_iam_role.cognito_authenticated.name
  policy_arn = aws_iam_policy.cognito_sync.arn
}

resource "aws_iam_role_policy_attachment" "mobile_analytics" {
  role       = aws_iam_role.cognito_authenticated.name
  policy_arn = aws_iam_policy.mobile_analytics.arn
}

###############################################################################
# Identity Pool Role Mapping (authenticated only)
###############################################################################

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    "authenticated" = aws_iam_role.cognito_authenticated.arn
  }
}

###############################################################################
# Outputs
###############################################################################

output "user_pool_id" {
  description = "ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_client_id" {
  description = "ID of the Cognito User Pool app client."
  value       = aws_cognito_user_pool_client.app.id
}

output "identity_pool_id" {
  description = "ID of the Cognito Identity Pool."
  value       = aws_cognito_identity_pool.main.id
}

output "cognito_authenticated_role_arn" {
  description = "ARN of the IAM role assumed by authenticated Cognito identities."
  value       = aws_iam_role.cognito_authenticated.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Providers
#
# The default (unaliased) AWS provider configuration is supplied by the
# deployment harness. An aliased provider is declared here because multi-region
# replica keys, their aliases and their grants must be managed in the secondary
# region.
###############################################################################

provider "aws" {
  alias  = "replica"
  region = var.replica_region
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Variables - mutually exclusive creation flags
###############################################################################

variable "create_key" {
  description = "Create a customer managed KMS key backed by AWS provided key material."
  type        = bool
  default     = true
}

variable "create_external_key" {
  description = "Create a KMS key with imported (external) key material."
  type        = bool
  default     = false
}

variable "create_replica_key" {
  description = "Create a multi-region replica of the customer managed KMS key."
  type        = bool
  default     = false
}

variable "create_replica_external_key" {
  description = "Create a multi-region replica of the external (imported material) KMS key."
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "AWS region used for multi-region replica keys, their aliases and their grants."
  type        = string
  default     = "us-west-2"

  validation {
    condition     = can(regex("^[a-z]{2}(-gov)?-[a-z]+-[0-9]$", var.replica_region))
    error_message = "replica_region must be a valid AWS region name such as us-west-2."
  }
}

###############################################################################
# Variables - key configuration
###############################################################################

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "Customer managed KMS key managed by Terraform"
}

variable "deletion_window_in_days" {
  description = "Waiting period, in days, before the KMS key is deleted."
  type        = number
  default     = 30

  validation {
    condition     = var.deletion_window_in_days >= 7 && var.deletion_window_in_days <= 30
    error_message = "deletion_window_in_days must be between 7 and 30 days."
  }
}

variable "key_usage" {
  description = "Intended use of the KMS key."
  type        = string
  default     = "ENCRYPT_DECRYPT"

  validation {
    condition     = contains(["ENCRYPT_DECRYPT", "SIGN_VERIFY", "GENERATE_VERIFY_MAC"], var.key_usage)
    error_message = "key_usage must be one of ENCRYPT_DECRYPT, SIGN_VERIFY or GENERATE_VERIFY_MAC."
  }
}

variable "customer_master_key_spec" {
  description = "Key spec of the KMS key (SYMMETRIC_DEFAULT, HMAC_*, RSA_*, ECC_*)."
  type        = string
  default     = "SYMMETRIC_DEFAULT"

  validation {
    condition = contains([
      "SYMMETRIC_DEFAULT",
      "HMAC_224",
      "HMAC_256",
      "HMAC_384",
      "HMAC_512",
      "RSA_2048",
      "RSA_3072",
      "RSA_4096",
      "ECC_NIST_P256",
      "ECC_NIST_P384",
      "ECC_NIST_P521",
      "ECC_SECG_P256K1",
      "SM2",
    ], var.customer_master_key_spec)
    error_message = "customer_master_key_spec must be a valid AWS KMS key spec."
  }
}

variable "enable_key_rotation" {
  description = "Enable automatic annual rotation for symmetric customer managed keys."
  type        = bool
  default     = true
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this configuration."
  type        = map(string)
  default = {
    Environment = "dev"
    Project     = "kms"
    ManagedBy   = "terraform"
  }
}

###############################################################################
# Variables - key policy role / principal inputs
###############################################################################

variable "key_owner_role_names" {
  description = "IAM role names (created by this configuration) that own the key and hold administrative KMS permissions."
  type        = list(string)
  default     = []
}

variable "key_administrator_role_names" {
  description = "IAM role names (created by this configuration) that administer the key."
  type        = list(string)
  default     = []
}

variable "key_user_role_names" {
  description = "IAM role names (created by this configuration) that use the key for standard cryptographic operations."
  type        = list(string)
  default     = []
}

variable "symmetric_user_role_names" {
  description = "IAM role names (created by this configuration) that use the key for symmetric encrypt/decrypt operations."
  type        = list(string)
  default     = []
}

variable "hmac_user_role_names" {
  description = "IAM role names (created by this configuration) that use the key for HMAC generate/verify operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encryption_user_role_names" {
  description = "IAM role names (created by this configuration) that use the key for asymmetric public encryption."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_user_role_names" {
  description = "IAM role names (created by this configuration) that use the key for asymmetric sign/verify operations."
  type        = list(string)
  default     = []
}

variable "autoscaling_role_names" {
  description = "IAM role names (created by this configuration) used by EC2 Auto Scaling to use the key."
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "AWS service principals that may use the key, together with the exact KMS actions each one requires."
  type = list(object({
    principal                = string
    actions                  = list(string)
    source_account_condition = optional(bool, true)
    source_arn_condition     = optional(string, null)
  }))
  default = []
}

variable "enable_route53_dnssec" {
  description = "Grant the Route 53 DNSSEC signing service (dnssec-route53.amazonaws.com) kms:GetPublicKey and kms:Sign."
  type        = bool
  default     = false
}

variable "custom_policy_statements" {
  description = "Additional key policy statements merged with the generated statements."
  type = list(object({
    sid = optional(string, null)
    effect = optional(string, "Allow")
    principals = optional(list(object({
      type        = string
      identifiers = list(string)
    })), [])
    actions   = list(string)
    resources = optional(list(string), ["*"])
    conditions = optional(list(object({
      test     = string
      variable = string
      values   = list(string)
    })), [])
  }))
  default = []

  validation {
    condition     = alltrue([for statement in var.custom_policy_statements : statement.effect == null || contains(["Allow", "Deny"], statement.effect)])
    error_message = "The effect of every custom policy statement must be either \"Allow\" or \"Deny\"."
  }

  validation {
    condition     = alltrue([for statement in var.custom_policy_statements : length(statement.actions) > 0])
    error_message = "Every custom policy statement must define at least one action."
  }
}

variable "override_policy_json" {
  description = "Complete key policy document (JSON) that replaces the generated policy. Leave empty to use the generated policy."
  type        = string
  default     = ""

  validation {
    condition     = var.override_policy_json == "" ? true : can(jsondecode(var.override_policy_json))
    error_message = "override_policy_json must be a valid JSON document or an empty string."
  }
}

###############################################################################
# Variables - aliases
###############################################################################

variable "alias_exact_names" {
  description = "Exact alias names (without the alias/ prefix) for the primary key in the primary region."
  type        = list(string)
  default     = []
}

variable "alias_prefix_names" {
  description = "Alias name prefixes (without the alias/ prefix) used to generate unique aliases for the primary key."
  type        = list(string)
  default     = []
}

variable "replica_alias_exact_names" {
  description = "Exact alias names (without the alias/ prefix) for the replica key in the replica region."
  type        = list(string)
  default     = []
}

variable "replica_alias_prefix_names" {
  description = "Alias name prefixes (without the alias/ prefix) used to generate unique aliases for the replica key."
  type        = list(string)
  default     = []
}

###############################################################################
# Variables - grants
###############################################################################

variable "grants" {
  description = "Map of KMS grants to create on the primary key."
  type = map(object({
    grantee_role_name         = optional(string, "")
    grantee_principal         = optional(string, "")
    operations                = list(string)
    retiring_principal        = optional(string, null)
    encryption_context_equals = optional(map(string), {})
    encryption_context_subset = optional(map(string), {})
  }))
  default = {}

  validation {
    condition     = alltrue([for grant in values(var.grants) : length(grant.operations) > 0])
    error_message = "Every KMS grant must define at least one operation."
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  region = data.aws_region.current.name

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  default_tags = {
    Environment = "dev"
    Project     = "kms"
    ManagedBy   = "terraform"
  }

  tags = merge(local.default_tags, var.tags)

  # ---------------------------------------------------------------------------
  # Key characteristics
  # ---------------------------------------------------------------------------
  is_symmetric_key             = var.customer_master_key_spec == "SYMMETRIC_DEFAULT"
  is_symmetric_encrypt_decrypt = var.customer_master_key_spec == "SYMMETRIC_DEFAULT" && var.key_usage == "ENCRYPT_DECRYPT"

  rotation_enabled = var.enable_key_rotation && local.is_symmetric_key

  # ---------------------------------------------------------------------------
  # Creation flag validation
  # ---------------------------------------------------------------------------
  any_key_created = var.create_key || var.create_external_key || var.create_replica_key || var.create_replica_external_key

  creation_flags_valid = !(var.create_key && var.create_external_key) && !(var.create_replica_key && var.create_replica_external_key)

  replica_flags_have_primary = (!var.create_replica_key || var.create_key) && (!var.create_replica_external_key || var.create_external_key)

  replica_requested = var.create_replica_key || var.create_replica_external_key

  replica_key_enabled = var.create_replica_key || var.create_replica_external_key

  # ---------------------------------------------------------------------------
  # Route 53 DNSSEC compatibility
  # ---------------------------------------------------------------------------
  dnssec_key_compatible = var.key_usage == "SIGN_VERIFY" && contains([
    "ECC_NIST_P256",
    "ECC_NIST_P384",
    "ECC_NIST_P521",
    "ECC_SECG_P256K1",
    "RSA_2048",
    "RSA_3072",
    "RSA_4096",
  ], var.customer_master_key_spec)

  # ---------------------------------------------------------------------------
  # Override policy safety check - only the current account may be referenced
  # ---------------------------------------------------------------------------
  override_policy_account_ids = distinct(flatten(regexall("arn:[a-z0-9-]+:[a-z0-9-]*:[a-z0-9-]*:([0-9]{12}):", var.override_policy_json)))

  override_policy_references_current_account_only = length(setsubtract(local.override_policy_account_ids, [local.account_id])) == 0

  # ---------------------------------------------------------------------------
  # IAM roles managed by this configuration
  # ---------------------------------------------------------------------------
  managed_role_names = distinct(concat(
    var.key_owner_role_names,
    var.key_administrator_role_names,
    var.key_user_role_names,
    var.symmetric_user_role_names,
    var.hmac_user_role_names,
    var.asymmetric_public_encryption_user_role_names,
    var.asymmetric_sign_verify_user_role_names,
    [for grant in values(var.grants) : grant.grantee_role_name],
  ))

  account_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "AllowAccountPrincipalsToAssumeRole"
      Effect = "Allow"
      Action = "sts:AssumeRole"
      Principal = {
        AWS = local.account_root_arn
      }
    }]
  })

  ec2_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Sid    = "AllowEc2AutoScalingToAssumeRole"
      Effect = "Allow"
      Action = "sts:AssumeRole"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
    }]
  })

  role_assume_role_policies = merge(
    { for name in local.managed_role_names : name => local.account_assume_role_policy if name != "" },
    { for name in distinct(var.autoscaling_role_names) : name => local.ec2_assume_role_policy },
  )

  key_administration_role_names = distinct(concat(var.key_owner_role_names, var.key_administrator_role_names))

  # ---------------------------------------------------------------------------
  # Least privilege KMS action sets
  # ---------------------------------------------------------------------------
  key_administration_actions = [
    "kms:CreateGrant",
    "kms:DescribeKey",
    "kms:GetKeyPolicy",
    "kms:PutKeyPolicy",
    "kms:ListGrants",
    "kms:RevokeGrant",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ListResourceTags",
    "kms:EnableKeyRotation",
    "kms:DisableKeyRotation",
    "kms:GetKeyRotationStatus",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion",
  ]

  key_user_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncryptFrom",
    "kms:ReEncryptTo",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  symmetric_user_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncryptFrom",
    "kms:ReEncryptTo",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  hmac_user_actions = [
    "kms:GenerateMac",
    "kms:VerifyMac",
    "kms:DescribeKey",
  ]

  asymmetric_public_encryption_user_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:GetPublicKey",
    "kms:DescribeKey",
  ]

  asymmetric_sign_verify_user_actions = [
    "kms:Sign",
    "kms:Verify",
    "kms:GetPublicKey",
    "kms:DescribeKey",
  ]

  autoscaling_actions = [
    "kms:Decrypt",
    "kms:GenerateDataKey",
    "kms:DescribeKey",
  ]

  # ---------------------------------------------------------------------------
  # External key material (never hardcoded - sourced from Secrets Manager)
  # ---------------------------------------------------------------------------
  external_key_material_base64 = var.create_external_key ? one(aws_secretsmanager_secret_version.external_key_material[*].secret_string) : null

  # ---------------------------------------------------------------------------
  # Active key identifiers
  # ---------------------------------------------------------------------------
  key_id = (
    var.create_key ? one(aws_kms_key.primary[*].arn) :
    var.create_external_key ? one(aws_kms_external_key.primary[*].arn) :
    var.create_replica_key ? one(aws_kms_replica_key.replica[*].arn) :
    var.create_replica_external_key ? one(aws_kms_replica_external_key.replica_external[*].arn) :
    null
  )

  replica_key_id = (
    var.create_replica_key ? one(aws_kms_replica_key.replica[*].arn) :
    var.create_replica_external_key ? one(aws_kms_replica_external_key.replica_external[*].arn) :
    null
  )

  # ---------------------------------------------------------------------------
  # Alias selection
  # ---------------------------------------------------------------------------
  exact_alias_names          = toset(var.alias_exact_names)
  prefix_alias_names         = toset(var.alias_prefix_names)
  replica_exact_alias_names  = local.replica_key_enabled ? toset(var.replica_alias_exact_names) : toset([])
  replica_prefix_alias_names = local.replica_key_enabled ? toset(var.replica_alias_prefix_names) : toset([])

  # ---------------------------------------------------------------------------
  # Key policy document (generated or overridden)
  # ---------------------------------------------------------------------------
  key_policy_json = var.override_policy_json != "" ? var.override_policy_json : data.aws_iam_policy_document.key_policy.json
}

###############################################################################
# IAM roles referenced by key policies and grants
###############################################################################

resource "aws_iam_role" "key_roles" {
  for_each = local.role_assume_role_policies

  name               = each.key
  description        = "IAM role managed by the KMS configuration for ${each.key}"
  assume_role_policy = each.value

  tags = local.tags
}

###############################################################################
# Key policy
###############################################################################

data "aws_iam_policy_document" "key_policy" {
  # Default root account administration - prevents lock out of the key.
  statement {
    sid       = "DefaultRootAccountAdmin"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }
  }

  # Key owners and administrators.
  dynamic "statement" {
    for_each = length(local.key_administration_role_names) > 0 ? [1] : []

    content {
      sid       = "KeyAdministration"
      effect    = "Allow"
      actions   = local.key_administration_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in local.key_administration_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # Standard key users.
  dynamic "statement" {
    for_each = length(var.key_user_role_names) > 0 ? [1] : []

    content {
      sid       = "StandardKeyUsage"
      effect    = "Allow"
      actions   = local.key_user_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.key_user_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # Symmetric cryptographic operation users.
  dynamic "statement" {
    for_each = length(var.symmetric_user_role_names) > 0 ? [1] : []

    content {
      sid       = "SymmetricKeyUsage"
      effect    = "Allow"
      actions   = local.symmetric_user_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.symmetric_user_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # HMAC cryptographic operation users.
  dynamic "statement" {
    for_each = length(var.hmac_user_role_names) > 0 ? [1] : []

    content {
      sid       = "HmacKeyUsage"
      effect    = "Allow"
      actions   = local.hmac_user_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.hmac_user_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # Asymmetric public encryption users.
  dynamic "statement" {
    for_each = length(var.asymmetric_public_encryption_user_role_names) > 0 ? [1] : []

    content {
      sid       = "AsymmetricPublicEncryptionKeyUsage"
      effect    = "Allow"
      actions   = local.asymmetric_public_encryption_user_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.asymmetric_public_encryption_user_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # Asymmetric sign / verify users.
  dynamic "statement" {
    for_each = length(var.asymmetric_sign_verify_user_role_names) > 0 ? [1] : []

    content {
      sid       = "AsymmetricSignVerifyKeyUsage"
      effect    = "Allow"
      actions   = local.asymmetric_sign_verify_user_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.asymmetric_sign_verify_user_role_names : aws_iam_role.key_roles[name].arn]
      }
    }
  }

  # EC2 Auto Scaling key usage.
  dynamic "statement" {
    for_each = length(var.autoscaling_role_names) > 0 ? [1] : []

    content {
      sid       = "AutoScalingKeyUsage"
      effect    = "Allow"
      actions   = local.autoscaling_actions
      resources = ["*"]

      principals {
        type        = "AWS"
        identifiers = [for name in var.autoscaling_role_names : aws_iam_role.key_roles[name].arn]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }

  # AWS service principals with their required actions only.
  dynamic "statement" {
    for_each = { for index, user in var.service_users : tostring(index) => user }

    content {
      sid       = "ServiceUser${statement.key}"
      effect    = "Allow"
      actions   = statement.value.actions
      resources = ["*"]

      principals {
        type        = "Service"
        identifiers = [statement.value.principal]
      }

      dynamic "condition" {
        for_each = statement.value.source_account_condition ? [1] : []

        content {
          test     = "StringEquals"
          variable = "aws:SourceAccount"
          values   = [local.account_id]
        }
      }

      dynamic "condition" {
        for_each = statement.value.source_arn_condition != null ? [1] : []

        content {
          test     = "ArnLike"
          variable = "aws:SourceArn"
          values   = [statement.value.source_arn_condition]
        }
      }
    }
  }

  # Route 53 DNSSEC signing service.
  dynamic "statement" {
    for_each = var.enable_route53_dnssec ? [1] : []

    content {
      sid       = "Route53DnssecSigning"
      effect    = "Allow"
      actions   = ["kms:GetPublicKey", "kms:Sign"]
      resources = ["*"]

      principals {
        type        = "Service"
        identifiers = ["dnssec-route53.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }

  # User supplied statements merged with the generated statements.
  dynamic "statement" {
    for_each = { for index, custom_statement in var.custom_policy_statements : tostring(index) => custom_statement }

    content {
      sid       = statement.value.sid != null ? statement.value.sid : "CustomPolicyStatement${statement.key}"
      effect    = statement.value.effect
      actions   = statement.value.actions
      resources = statement.value.resources

      dynamic "principals" {
        for_each = statement.value.principals

        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = statement.value.conditions

        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

###############################################################################
# External key material - random material stored in Secrets Manager
###############################################################################

resource "aws_secretsmanager_secret" "external_key_material" {
  count = var.create_external_key ? 1 : 0

  name_prefix             = "kms-external-key-material-"
  description             = "Base64 encoded 256 bit key material for the imported KMS key managed by Terraform."
  recovery_window_in_days = 7

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "random_id" "external_key_material" {
  count = var.create_external_key ? 1 : 0

  byte_length = 32

  keepers = {
    secret_arn = aws_secretsmanager_secret.external_key_material[0].arn
  }
}

resource "aws_secretsmanager_secret_version" "external_key_material" {
  count = var.create_external_key ? 1 : 0

  secret_id     = aws_secretsmanager_secret.external_key_material[0].id
  secret_string = random_id.external_key_material[0].b64_std
}

###############################################################################
# Primary KMS key - AWS provided key material
###############################################################################

resource "aws_kms_key" "primary" {
  count = var.create_key ? 1 : 0

  description              = var.description
  deletion_window_in_days  = var.deletion_window_in_days
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  enable_key_rotation      = local.rotation_enabled
  multi_region             = local.replica_requested
  policy                   = local.key_policy_json
  tags                     = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_valid
      error_message = "Only one primary key flag may be enabled (create_key or create_external_key) and only one replica flag may be enabled (create_replica_key or create_replica_external_key)."
    }

    precondition {
      condition     = local.replica_flags_have_primary
      error_message = "create_replica_key requires create_key = true and create_replica_external_key requires create_external_key = true."
    }

    precondition {
      condition     = local.override_policy_references_current_account_only
      error_message = "override_policy_json must not reference AWS account IDs other than the current account (${local.account_id})."
    }

    precondition {
      condition     = !var.enable_route53_dnssec || local.dnssec_key_compatible
      error_message = "enable_route53_dnssec requires key_usage = \"SIGN_VERIFY\" and an asymmetric customer_master_key_spec such as ECC_NIST_P256."
    }

    precondition {
      condition     = !local.replica_requested || var.replica_region != local.region
      error_message = "replica_region must differ from the primary region (${local.region})."
    }
  }
}

###############################################################################
# Primary KMS external key - imported key material
#
# Note: aws_kms_external_key exposes key_usage as a Computed-only attribute.
# AWS KMS always provisions imported-material keys as symmetric ENCRYPT_DECRYPT
# keys, so key_usage must not be configured here. The symmetric/ENCRYPT_DECRYPT
# contract is enforced through the precondition below instead.
###############################################################################

resource "aws_kms_external_key" "primary" {
  count = var.create_external_key ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  key_material_base64     = local.external_key_material_base64
  multi_region            = local.replica_requested
  policy                  = local.key_policy_json
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_valid
      error_message = "Only one primary key flag may be enabled (create_key or create_external_key) and only one replica flag may be enabled (create_replica_key or create_replica_external_key)."
    }

    precondition {
      condition     = local.replica_flags_have_primary
      error_message = "create_replica_key requires create_key = true and create_replica_external_key requires create_external_key = true."
    }

    precondition {
      condition     = var.customer_master_key_spec == "SYMMETRIC_DEFAULT" && var.key_usage == "ENCRYPT_DECRYPT"
      error_message = "Imported key material must be 256 bit symmetric material: customer_master_key_spec must be SYMMETRIC_DEFAULT and key_usage must be ENCRYPT_DECRYPT."
    }

    precondition {
      condition     = local.override_policy_references_current_account_only
      error_message = "override_policy_json must not reference AWS account IDs other than the current account (${local.account_id})."
    }

    precondition {
      condition     = !var.enable_route53_dnssec || local.dnssec_key_compatible
      error_message = "enable_route53_dnssec requires key_usage = \"SIGN_VERIFY\" and an asymmetric customer_master_key_spec such as ECC_NIST_P256."
    }

    precondition {
      condition     = !local.replica_requested || var.replica_region != local.region
      error_message = "replica_region must differ from the primary region (${local.region})."
    }
  }
}

###############################################################################
# Multi-region replica key of the primary KMS key
###############################################################################

resource "aws_kms_replica_key" "replica" {
  count    = var.create_replica_key ? 1 : 0
  provider = aws.replica

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = aws_kms_key.primary[0].arn
  policy                  = local.key_policy_json
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = var.create_key
      error_message = "create_replica_key requires create_key = true so that the primary key exists in this configuration."
    }

    precondition {
      condition     = var.replica_region != local.region
      error_message = "replica_region must differ from the primary region (${local.region})."
    }
  }
}

###############################################################################
# Multi-region replica key of the primary external KMS key
#
# Note: aws_kms_replica_external_key also exposes key_usage as Computed-only,
# so no key_usage argument is set here.
###############################################################################

resource "aws_kms_replica_external_key" "replica_external" {
  count    = var.create_replica_external_key ? 1 : 0
  provider = aws.replica

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = aws_kms_external_key.primary[0].arn
  key_material_base64     = local.external_key_material_base64
  policy                  = local.key_policy_json
  tags                    = local.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = var.create_external_key
      error_message = "create_replica_external_key requires create_external_key = true so that the primary external key exists in this configuration."
    }

    precondition {
      condition     = var.replica_region != local.region
      error_message = "replica_region must differ from the primary region (${local.region})."
    }
  }
}

###############################################################################
# Aliases - exact names (primary region)
###############################################################################

resource "aws_kms_alias" "exact" {
  for_each = local.exact_alias_names

  name          = "alias/${each.value}"
  target_key_id = local.key_id

  lifecycle {
    precondition {
      condition     = local.any_key_created
      error_message = "Aliases require one of the KMS key creation flags to be enabled."
    }
  }
}

###############################################################################
# Aliases - name prefixes (primary region)
###############################################################################

resource "aws_kms_alias" "prefix" {
  for_each = local.prefix_alias_names

  name_prefix   = "alias/${each.value}"
  target_key_id = local.key_id

  lifecycle {
    precondition {
      condition     = local.any_key_created
      error_message = "Aliases require one of the KMS key creation flags to be enabled."
    }
  }
}

###############################################################################
# Replica region aliases - exact names
###############################################################################

resource "aws_kms_alias" "replica_exact" {
  for_each = local.replica_exact_alias_names
  provider = aws.replica

  name          = "alias/${each.value}"
  target_key_id = local.replica_key_id

  lifecycle {
    precondition {
      condition     = local.replica_key_enabled
      error_message = "Replica aliases require create_replica_key or create_replica_external_key to be enabled."
    }
  }
}

###############################################################################
# Replica region aliases - name prefixes
###############################################################################

resource "aws_kms_alias" "replica_prefix" {
  for_each = local.replica_prefix_alias_names
  provider = aws.replica

  name_prefix   = "alias/${each.value}"
  target_key_id = local.replica_key_id

  lifecycle {
    precondition {
      condition     = local.replica_key_enabled
      error_message = "Replica aliases require create_replica_key or create_replica_external_key to be enabled."
    }
  }
}

###############################################################################
# Grants
###############################################################################

resource "aws_kms_grant" "grants" {
  for_each = var.grants

  name               = each.key
  key_id             = local.key_id
  grantee_principal  = each.value.grantee_role_name != "" ? aws_iam_role.key_roles[each.value.grantee_role_name].arn : each.value.grantee_principal
  retiring_principal = each.value.retiring_principal
  operations         = each.value.operations

  dynamic "constraints" {
    for_each = length(each.value.encryption_context_equals) > 0 || length(each.value.encryption_context_subset) > 0 ? [1] : []

    content {
      encryption_context_equals = length(each.value.encryption_context_equals) > 0 ? each.value.encryption_context_equals : null
      encryption_context_subset = length(each.value.encryption_context_subset) > 0 ? each.value.encryption_context_subset : null
    }
  }

  lifecycle {
    precondition {
      condition     = local.any_key_created
      error_message = "KMS grants require one of the KMS key creation flags to be enabled."
    }

    precondition {
      condition     = local.is_symmetric_encrypt_decrypt || var.key_usage == "GENERATE_VERIFY_MAC"
      error_message = "KMS grants are only supported for symmetric ENCRYPT_DECRYPT keys or HMAC GENERATE_VERIFY_MAC keys."
    }

    precondition {
      condition     = each.value.grantee_principal != "*" && each.value.grantee_role_name != "*"
      error_message = "KMS grants must not use the wildcard principal \"*\"."
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "key_arn" {
  description = "ARN of the active KMS key (primary or replica)."
  value       = local.key_id
}

output "key_id" {
  description = "Key identifier of the active KMS key."
  value       = local.key_id
}

output "primary_key_arn" {
  description = "ARN of the primary customer managed KMS key, if created."
  value       = var.create_key ? one(aws_kms_key.primary[*].arn) : null
}

output "external_key_arn" {
  description = "ARN of the primary external KMS key, if created."
  value       = var.create_external_key ? one(aws_kms_external_key.primary[*].arn) : null
}

output "external_key_expiration" {
  description = "Expiration model of the external KMS key key material, if an external key was created."
  value       = var.create_external_key ? one(aws_kms_external_key.primary[*].expiration_model) : null
}

output "external_key_material_secret_arn" {
  description = "ARN of the Secrets Manager secret holding the external key material, if created."
  value       = var.create_external_key ? one(aws_secretsmanager_secret.external_key_material[*].arn) : null
}

output "replica_key_arn" {
  description = "ARN of the multi-region replica key, if created."
  value       = one(concat(aws_kms_replica_key.replica[*].arn, aws_kms_replica_external_key.replica_external[*].arn))
}

output "alias_arns" {
  description = "Map of alias name to alias ARN for every alias created in the primary and replica regions."
  value = merge(
    { for name, alias in aws_kms_alias.exact : name => alias.arn },
    { for name, alias in aws_kms_alias.prefix : name => alias.arn },
    { for name, alias in aws_kms_alias.replica_exact : name => alias.arn },
    { for name, alias in aws_kms_alias.replica_prefix : name => alias.arn },
  )
}

output "grant_ids" {
  description = "Map of grant definition name to KMS grant ID."
  value       = { for name, grant in aws_kms_grant.grants : name => grant.grant_id }
}

output "iam_role_arns" {
  description = "Map of IAM role name to ARN for every role created by this configuration."
  value       = { for name, role in aws_iam_role.key_roles : name => role.arn }
}

output "key_policy_json" {
  description = "Key policy document applied to the KMS key resources."
  value       = local.key_policy_json
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name = "cross-cluster-networking"

  vpc_cidr = "10.0.0.0/16"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  private_subnets = [
    cidrsubnet(local.vpc_cidr, 4, 0),
    cidrsubnet(local.vpc_cidr, 4, 1),
    cidrsubnet(local.vpc_cidr, 4, 2),
  ]

  public_subnets = [
    cidrsubnet(local.vpc_cidr, 8, 48),
    cidrsubnet(local.vpc_cidr, 8, 49),
    cidrsubnet(local.vpc_cidr, 8, 50),
  ]

  tags = {
    Blueprint  = local.name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway = true
  single_nat_gateway = true

  enable_dns_hostnames = true
  enable_dns_support   = true

  map_public_ip_on_launch = false

  public_subnet_tags = {
    "kubernetes.io/role/elb" = "1"
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = "1"
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional_sg" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 (cross-cluster communication)"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster1_additional_sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "cluster2_additional_sg" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 (cross-cluster communication)"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, {
    Name = "cluster2_additional_sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group_rule" "cluster1_ingress_from_cluster2" {
  type                     = "ingress"
  description              = "Allow all protocols from cluster2 security group"
  protocol                 = "-1"
  from_port                = 0
  to_port                  = 0
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster1_egress_to_cluster2" {
  type                     = "egress"
  description              = "Allow all protocols to cluster2 security group"
  protocol                 = "-1"
  from_port                = 0
  to_port                  = 0
  security_group_id        = aws_security_group.cluster1_additional_sg.id
  source_security_group_id = aws_security_group.cluster2_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_ingress_from_cluster1" {
  type                     = "ingress"
  description              = "Allow all protocols from cluster1 security group"
  protocol                 = "-1"
  from_port                = 0
  to_port                  = 0
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
}

resource "aws_security_group_rule" "cluster2_egress_to_cluster1" {
  type                     = "egress"
  description              = "Allow all protocols to cluster1 security group"
  protocol                 = "-1"
  from_port                = 0
  to_port                  = 0
  security_group_id        = aws_security_group.cluster2_additional_sg.id
  source_security_group_id = aws_security_group.cluster1_additional_sg.id
}

output "vpc_id" {
  description = "The ID of the VPC"
  value       = module.vpc.vpc_id
}

output "private_subnet_ids" {
  description = "List of IDs of the private subnets"
  value       = module.vpc.private_subnets
}

output "public_subnet_ids" {
  description = "List of IDs of the public subnets"
  value       = module.vpc.public_subnets
}

output "cluster1_additional_sg_id" {
  description = "The ID of the additional security group for cluster1"
  value       = aws_security_group.cluster1_additional_sg.id
}

output "cluster2_additional_sg_id" {
  description = "The ID of the additional security group for cluster2"
  value       = aws_security_group.cluster2_additional_sg.id
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

variable "pool_name" {
  type    = string
  default = "Pool name"
}

variable "alias_attributes" {
  type    = list(string)
  default = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  type    = list(string)
  default = []
}

variable "email_verification_message" {
  type    = string
  default = "Some message {####}"
}

variable "email_verification_subject" {
  type    = string
  default = "Some subject"
}

variable "mfa_configuration" {
  type    = string
  default = "OPTIONAL"
}

variable "sms_authentication_message" {
  type    = string
  default = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  type    = string
  default = "SMS verification message {####}"
}

variable "verification_message_template_by_link" {
  type    = bool
  default = false
}

variable "sms_configuration" {
  type    = map(string)
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "recovery_mechanisms" {
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

variable "admin_create_user_only" {
  type    = bool
  default = false
}

variable "enable_software_token_mfa" {
  type    = bool
  default = true
}

variable "username_case_sensitive" {
  type    = bool
  default = null
}

variable "device_configuration" {
  type    = any
  default = null
}

variable "lambda_config" {
  type = object({
    custom_email_sender = optional(object({
      lambda_arn     = optional(string)
      lambda_version = optional(string, "V1_0")
    }))
    custom_sms_sender = optional(object({
      lambda_arn     = optional(string)
      lambda_version = optional(string, "V1_0")
    }))
    create_auth_challenge          = optional(string)
    custom_message                 = optional(string)
    define_auth_challenge          = optional(string)
    post_authentication            = optional(string)
    post_confirmation              = optional(string)
    pre_authentication             = optional(string)
    pre_sign_up                    = optional(string)
    pre_token_generation           = optional(string)
    user_migration                 = optional(string)
    verify_auth_challenge_response = optional(string)
  })
  default = {}
}

variable "schema" {
  type = list(any)
  default = [
    {
      name                = "email"
      attribute_data_type = "String"
      required            = true
      mutable             = true
    }
  ]
}

variable "client_app_names" {
  type    = list(string)
  default = []
}

variable "client_generate_secret" {
  type    = bool
  default = false
}

variable "client_access_token_validity" {
  type    = number
  default = 120
}

variable "client_id_token_validity" {
  type    = number
  default = 120
}

variable "client_refresh_token_validity" {
  type    = number
  default = 7
}

variable "client_token_validity_units" {
  type    = map(string)
  default = {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

variable "client_allowed_oauth_user_pool_client" {
  type    = bool
  default = false
}

variable "client_enable_token_revocation" {
  type    = bool
  default = true
}

variable "client_explicit_auth_flows" {
  type    = list(string)
  default = ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"]
}

variable "client_prevent_user_existence_errors" {
  type    = string
  default = "LEGACY"
}

variable "client_read_attributes" {
  type    = list(string)
  default = []
}

variable "client_write_attributes" {
  type    = list(string)
  default = []
}

variable "client_callback_urls" {
  type    = list(string)
  default = []
}

variable "client_logout_urls" {
  type    = list(string)
  default = []
}

variable "client_allowed_oauth_flows" {
  type    = list(string)
  default = []
}

variable "client_allowed_oauth_scopes" {
  type    = list(string)
  default = []
}

variable "client_supported_identity_providers" {
  type    = list(string)
  default = []
}

variable "group_name" {
  type    = string
  default = ""
}

variable "group_precedence" {
  type    = number
  default = 0
}

variable "group_role_arn" {
  type    = string
  default = null
}

variable "domain_name" {
  type    = string
  default = ""
}

variable "domain_certificate_arn" {
  type    = string
  default = null
}

variable "create_route53_record" {
  type    = bool
  default = false
}

variable "route53_zone_id" {
  type    = string
  default = ""
}

locals {
  lambda_config_enabled = length([
    for v in values(var.lambda_config) : v if v != null
  ]) > 0

  lambda_sender_enabled = (
    var.lambda_config.custom_email_sender != null ||
    var.lambda_config.custom_sms_sender != null
  )

  lambda_function_needed = local.lambda_config_enabled && (
    local.lambda_sender_enabled ||
    length([
      for v in values(var.lambda_config) : v if v != null
    ]) > 0
  )
}

data "aws_iam_policy_document" "lambda_assume_role" {
  count = local.lambda_function_needed ? 1 : 0

  statement {
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "lambda_exec" {
  count = local.lambda_function_needed ? 1 : 0

  name               = "${var.pool_name}-lambda-exec"
  assume_role_policy = data.aws_iam_policy_document.lambda_assume_role[0].json
}

resource "aws_iam_role_policy" "lambda_logging" {
  count = local.lambda_function_needed ? 1 : 0

  name = "${var.pool_name}-lambda-logging"
  role = aws_iam_role.lambda_exec[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "arn:${data.aws_partition.current.partition}:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/${var.pool_name}-cognito-trigger:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic" {
  count = local.lambda_function_needed ? 1 : 0

  role       = aws_iam_role.lambda_exec[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

data "archive_file" "cognito_trigger" {
  count = local.lambda_function_needed ? 1 : 0

  type        = "zip"
  output_path = "${path.module}/cognito_trigger.zip"

  source {
    filename = "index.py"
    content  = <<EOF
import json

def handler(event, context):
    return event
EOF
  }
}

resource "aws_lambda_function" "cognito_trigger" {
  count = local.lambda_function_needed ? 1 : 0

  filename         = data.archive_file.cognito_trigger[0].output_path
  source_code_hash = data.archive_file.cognito_trigger[0].output_base64sha256
  function_name    = "${var.pool_name}-cognito-trigger"
  role             = aws_iam_role.lambda_exec[0].arn
  handler          = "index.handler"
  runtime          = "python3.12"
  timeout          = 30
}

resource "aws_cognito_user_pool" "main" {
  name                     = var.pool_name
  alias_attributes         = var.alias_attributes
  auto_verified_attributes = var.auto_verified_attributes
  mfa_configuration        = var.mfa_configuration

  email_verification_message = var.email_verification_message
  email_verification_subject = var.email_verification_subject
  sms_authentication_message = var.sms_authentication_message
  sms_verification_message   = var.sms_verification_message

  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only
  }

  verification_message_template {
    default_email_option = var.verification_message_template_by_link ? "CONFIRM_WITH_LINK" : "CONFIRM_WITH_CODE"
  }

  dynamic "username_configuration" {
    for_each = var.username_case_sensitive != null ? [1] : []

    content {
      case_sensitive = var.username_case_sensitive
    }
  }

  dynamic "sms_configuration" {
    for_each = (
      lookup(var.sms_configuration, "external_id", "") != "" &&
      lookup(var.sms_configuration, "sns_caller_arn", "") != ""
    ) ? [var.sms_configuration] : []

    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
    }
  }

  dynamic "software_token_mfa_configuration" {
    for_each = var.enable_software_token_mfa ? [1] : []

    content {
      enabled = true
    }
  }

  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []

    content {
      challenge_required_on_new_device      = lookup(device_configuration.value, "challenge_required_on_new_device", null)
      device_only_remembered_on_user_prompt = lookup(device_configuration.value, "device_only_remembered_on_user_prompt", null)
    }
  }

  dynamic "schema" {
    for_each = var.schema

    content {
      name                = schema.value.name
      attribute_data_type = schema.value.attribute_data_type
      required            = lookup(schema.value, "required", false)
      mutable             = lookup(schema.value, "mutable", true)

      dynamic "string_attribute_constraints" {
        for_each = (
          lookup(schema.value, "min_length", null) != null ||
          lookup(schema.value, "max_length", null) != null
        ) ? [1] : []

        content {
          min_length = lookup(schema.value, "min_length", null)
          max_length = lookup(schema.value, "max_length", null)
        }
      }
    }
  }

  dynamic "lambda_config" {
    for_each = local.lambda_config_enabled ? [1] : []

    content {
      create_auth_challenge          = var.lambda_config.create_auth_challenge
      custom_message                 = var.lambda_config.custom_message
      define_auth_challenge          = var.lambda_config.define_auth_challenge
      post_authentication            = var.lambda_config.post_authentication
      post_confirmation              = var.lambda_config.post_confirmation
      pre_authentication             = var.lambda_config.pre_authentication
      pre_sign_up                    = var.lambda_config.pre_sign_up
      pre_token_generation           = var.lambda_config.pre_token_generation
      user_migration                 = var.lambda_config.user_migration
      verify_auth_challenge_response = var.lambda_config.verify_auth_challenge_response

      dynamic "custom_email_sender" {
        for_each = var.lambda_config.custom_email_sender != null ? [var.lambda_config.custom_email_sender] : []

        content {
          lambda_arn     = coalesce(custom_email_sender.value.lambda_arn, aws_lambda_function.cognito_trigger[0].arn)
          lambda_version = custom_email_sender.value.lambda_version
        }
      }

      dynamic "custom_sms_sender" {
        for_each = var.lambda_config.custom_sms_sender != null ? [var.lambda_config.custom_sms_sender] : []

        content {
          lambda_arn     = coalesce(custom_sms_sender.value.lambda_arn, aws_lambda_function.cognito_trigger[0].arn)
          lambda_version = custom_sms_sender.value.lambda_version
        }
      }
    }
  }

  account_recovery_setting {
    dynamic "recovery_mechanism" {
      for_each = var.recovery_mechanisms

      content {
        name     = recovery_mechanism.value.name
        priority = recovery_mechanism.value.priority
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "main" {
  for_each = toset(var.client_app_names)

  name         = each.value
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = var.client_generate_secret

  access_token_validity  = var.client_access_token_validity
  id_token_validity      = var.client_id_token_validity
  refresh_token_validity = var.client_refresh_token_validity

  token_validity_units {
    access_token  = lookup(var.client_token_validity_units, "access_token", "minutes")
    id_token      = lookup(var.client_token_validity_units, "id_token", "minutes")
    refresh_token = lookup(var.client_token_validity_units, "refresh_token", "days")
  }

  allowed_oauth_flows_user_pool_client = var.client_allowed_oauth_user_pool_client
  enable_token_revocation              = var.client_enable_token_revocation
  explicit_auth_flows                  = var.client_explicit_auth_flows
  prevent_user_existence_errors        = var.client_prevent_user_existence_errors

  read_attributes  = length(var.client_read_attributes) > 0 ? var.client_read_attributes : null
  write_attributes = length(var.client_write_attributes) > 0 ? var.client_write_attributes : null

  callback_urls                = length(var.client_callback_urls) > 0 ? var.client_callback_urls : null
  logout_urls                  = length(var.client_logout_urls) > 0 ? var.client_logout_urls : null
  allowed_oauth_flows          = length(var.client_allowed_oauth_flows) > 0 ? var.client_allowed_oauth_flows : null
  allowed_oauth_scopes         = length(var.client_allowed_oauth_scopes) > 0 ? var.client_allowed_oauth_scopes : null
  supported_identity_providers = length(var.client_supported_identity_providers) > 0 ? var.client_supported_identity_providers : null
}

resource "aws_cognito_user_group" "main" {
  count = var.group_name != "" ? 1 : 0

  user_pool_id = aws_cognito_user_pool.main.id
  name         = var.group_name
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn
}

resource "aws_cognito_user_pool_domain" "main" {
  count = var.domain_name != "" ? 1 : 0

  domain          = var.domain_name
  user_pool_id    = aws_cognito_user_pool.main.id
  certificate_arn = var.domain_certificate_arn
}

resource "aws_route53_record" "cognito" {
  count = var.create_route53_record && var.route53_zone_id != "" ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn
    zone_id                = "Z2FDTNDATAQYW2"
    evaluate_target_health = false
  }
}

output "user_pool_id" {
  value = aws_cognito_user_pool.main.id
}

output "user_pool_arn" {
  value = aws_cognito_user_pool.main.arn
}

output "user_pool_client_ids" {
  value = { for name, client in aws_cognito_user_pool_client.main : name => client.id }
}

output "user_pool_domain_cloudfront_distribution_arn" {
  value = length(aws_cognito_user_pool_domain.main) > 0 ? aws_cognito_user_pool_domain.main[0].cloudfront_distribution_arn : null
}

output "user_group_name" {
  value = length(aws_cognito_user_group.main) > 0 ? aws_cognito_user_group.main[0].name : null
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_availability_zones" "available" {
  state = "available"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_identifier" {
  description = "Identifier name for the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gateway_name" {
  description = "Name tag for the NAT gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool from which the Elastic IP is drawn"
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az_index" {
  description = "Index into the available AZ list for Subnet A"
  type        = number
  default     = 0
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_a_map_public_ip_on_launch" {
  description = "Whether to map public IPs on launch for Subnet A"
  type        = bool
  default     = false
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az_index" {
  description = "Index into the available AZ list for Subnet B"
  type        = number
  default     = 1
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_b_map_public_ip_on_launch" {
  description = "Whether to map public IPs on launch for Subnet B"
  type        = bool
  default     = false
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az_index" {
  description = "Index into the available AZ list for Subnet C"
  type        = number
  default     = 2
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

variable "subnet_c_map_public_ip_on_launch" {
  description = "Whether to map public IPs on launch for Subnet C"
  type        = bool
  default     = false
}

locals {
  security_group_name = "DefaultSecurityGroup"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_a_az_index]
  map_public_ip_on_launch = var.subnet_a_map_public_ip_on_launch

  tags = {
    Name = var.subnet_a_name
  }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_b_az_index]
  map_public_ip_on_launch = var.subnet_b_map_public_ip_on_launch

  tags = {
    Name = var.subnet_b_name
  }
}

resource "aws_subnet" "private_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = data.aws_availability_zones.available.names[var.subnet_c_az_index]
  map_public_ip_on_launch = var.subnet_c_map_public_ip_on_launch

  tags = {
    Name = var.subnet_c_name
  }
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.main.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.main.id
}

resource "aws_eip" "nat" {
  domain           = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = var.nat_gateway_name
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.private_b.id

  tags = {
    Name = var.nat_gateway_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = local.security_group_name
  description = "Default security group allowing egress only within the VPC CIDR"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.security_group_name
  }
}

resource "aws_security_group_rule" "default_egress_vpc" {
  type              = "egress"
  security_group_id = aws_security_group.default.id
  from_port         = 0
  to_port           = 0
  protocol          = "-1"
  cidr_blocks       = [var.vpc_cidr]
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "When true a new Transit Gateway is provisioned; when false an existing one is resolved via id or name."
  type        = bool
  default     = true
}

variable "id" {
  description = "Existing Transit Gateway ID. Only used when create = false."
  type        = string
  default     = null
}

variable "name" {
  description = "Name tag used to filter an existing Transit Gateway and as the default Name tag of created resources."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "BGP ASN for the Transit Gateway (private 64512-65534 or AWS 32-bit 4200000000-4294967294)."
  type        = number
  default     = 65200

  validation {
    condition = (
      (var.amazon_side_asn >= 64512 && var.amazon_side_asn <= 65534) ||
      (var.amazon_side_asn >= 4200000000 && var.amazon_side_asn <= 4294967294)
    )
    error_message = "amazon_side_asn must be a private ASN between 64512-65534 or an AWS 32-bit ASN between 4200000000-4294967294."
  }
}

variable "auto_accept_shared_attachments" {
  description = "Whether attachments shared through RAM are automatically accepted."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either \"enable\" or \"disable\"."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled on the Transit Gateway."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either \"enable\" or \"disable\"."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether ECMP is enabled for VPN attachments on the Transit Gateway."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either \"enable\" or \"disable\"."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "List of IPv4 or IPv6 CIDR blocks to assign to the Transit Gateway."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks :
      can(cidrhost(cidr, 0)) || can(cidrnetmask(cidr))
    ])
    error_message = "Every entry in transit_gateway_cidr_blocks must be a syntactically valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = "Map of Transit Gateway route tables. Each entry can either be created or looked up by name."
  type = map(object({
    create     = optional(bool, true)
    id         = optional(string, null)
    name       = optional(string, null)
    local_tags = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (AWS account ID, OU ARN or organization ARN) to share the Transit Gateway with via RAM."
  type        = map(string)
  default     = {}

  validation {
    condition = alltrue([
      for principal in values(var.shared_principals) :
      length(principal) > 0 && can(regex(
        "^(\\d{12}|arn:aws[a-zA-Z0-9-]*:organizations::\\d{12}:(organization|ou)/.+)$",
        principal
      ))
    ])
    error_message = "Each shared principal must be a 12 digit AWS account ID, an organizations OU ARN, or an organizations organization ARN."
  }
}

variable "ram_resource_share_name" {
  description = "Explicit name for the RAM resource share. Defaults to the main resource name."
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags applied to every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  dynamic "filter" {
    for_each = var.id != null ? [1] : []
    content {
      name   = "transit-gateway-id"
      values = [var.id]
    }
  }

  dynamic "filter" {
    for_each = var.id == null ? [1] : []
    content {
      name   = "tag:Name"
      values = [coalesce(var.name, "tgw-main")]
    }
  }
}

data "aws_ec2_transit_gateway_route_table" "existing" {
  for_each = { for k, v in var.route_tables : k => v if !v.create }

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [coalesce(each.value.name, var.name, "tgw-main")]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  main_name = coalesce(var.name, "tgw-main")

  transit_gateway_id = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id

  created_route_table_ids  = { for k, v in aws_ec2_transit_gateway_route_table.this : k => v.id }
  existing_route_table_ids = { for k, v in data.aws_ec2_transit_gateway_route_table.existing : k => v.id }

  route_table_ids = merge(local.created_route_table_ids, local.existing_route_table_ids)
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"

  tags = merge(var.tags, { Name = local.main_name })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Transit Gateway route tables
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = { for k, v in var.route_tables : k => v if v.create }

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    each.value.local_tags,
    { Name = coalesce(each.value.name, var.name, "tgw-main") }
  )

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# RAM resource share
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = length(var.shared_principals) > 0 ? 1 : 0

  name                      = coalesce(var.ram_resource_share_name, local.main_name)
  allow_external_principals = true

  tags = merge(
    var.tags,
    { Name = coalesce(var.ram_resource_share_name, local.main_name) }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_association" "tgw" {
  count = length(aws_ram_resource_share.this)

  resource_arn       = aws_ec2_transit_gateway.this[0].arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the created or resolved Transit Gateway."
  value       = try(aws_ec2_transit_gateway.this[0].id, data.aws_ec2_transit_gateway.this[0].id)
}

output "transit_gateway_arn" {
  description = "ARN of the created or resolved Transit Gateway."
  value       = try(aws_ec2_transit_gateway.this[0].arn, data.aws_ec2_transit_gateway.this[0].arn)
}

output "route_table_ids" {
  description = "Map of route table keys to their IDs, covering both created and looked-up route tables."
  value       = local.route_table_ids
}

output "ram_resource_share_arn" {
  description = "ARN of the RAM resource share, or null when no principals are shared."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Explicit name for the S3 bucket. When null, the module generates a name from the corebucket- prefix plus a random hex suffix."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, append an additional random suffix to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who pays for requests made to the bucket (BucketOwner or Requester)."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be either \"BucketOwner\" or \"Requester\"."
  }
}

variable "encryption" {
  description = "Whether to apply server-side encryption configuration to the bucket."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an existing KMS key to use for server-side encryption. When empty, the module creates and manages its own rotating key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Whether to enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Whether to enable MFA delete on the bucket versioning configuration."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Whether to force destroy the bucket (delete all objects) when the resource is removed."
  type        = bool
  default     = false
}

variable "acl" {
  description = "Optional canned ACL. When supplied, ownership controls are set to ObjectWriter; otherwise BucketOwnerEnforced."
  type        = string
  default     = null
}

variable "policy" {
  description = "Optional JSON bucket policy document."
  type        = string
  default     = null
}

variable "grants" {
  description = "Optional list of ACL grants applied directly to the bucket."
  type = list(object({
    id          = optional(string)
    type        = string
    permissions = list(string)
    uri         = optional(string)
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to the bucket, KMS key, and replication role."
  type        = map(string)
  default     = {}
}

variable "transfer_acceleration_status" {
  description = "Optional transfer acceleration status (Enabled or Suspended)."
  type        = string
  default     = null

  validation {
    condition     = var.transfer_acceleration_status == null || contains(["Enabled", "Suspended"], var.transfer_acceleration_status)
    error_message = "transfer_acceleration_status must be either \"Enabled\" or \"Suspended\"."
  }
}

variable "logging" {
  description = "Optional access logging configuration specifying the target bucket and prefix."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "website" {
  description = "Optional website configuration. Supply index/error documents or a redirect-all hostname."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
  })
  default = null
}

variable "cors_rules" {
  description = "Optional list of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "Optional list of lifecycle rules covering expiration, noncurrent version expiration, transitions, and abort-incomplete-multipart settings."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string), {})
    }))
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      days                      = optional(number)
      newer_noncurrent_versions = optional(number)
    }))
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
    noncurrent_version_transition = optional(list(object({
      days                      = optional(number)
      storage_class             = string
      newer_noncurrent_versions = optional(number)
    })), [])
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = number
    }))
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Optional S3 object lock configuration with a default retention rule."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null

  validation {
    condition     = var.object_lock_configuration == null || contains(["COMPLIANCE", "GOVERNANCE"], var.object_lock_configuration.mode)
    error_message = "object_lock_configuration.mode must be either \"COMPLIANCE\" or \"GOVERNANCE\"."
  }
}

variable "replication_rules" {
  description = "Optional cross-region replication rules. Supplying any rule enables replication configuration."
  type = list(object({
    id       = string
    status   = optional(string, "Enabled")
    priority = optional(number)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string), {})
    }))
    destination = object({
      bucket             = string
      storage_class      = optional(string)
      account            = optional(string)
      replica_kms_key_id = optional(string)
    })
    delete_marker_replication_status = optional(string)
  }))
  default = []
}

variable "replication_role" {
  description = "ARN of an existing IAM role for replication. When null, the module creates a dedicated replication role."
  type        = string
  default     = null
}

###############################################################################
# Random suffixes
###############################################################################

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  count       = var.prefix ? 1 : 0
  byte_length = 4
}

###############################################################################
# Locals
###############################################################################

locals {
  base_bucket_name = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}"
  prefix_suffix    = var.prefix ? try(random_id.prefix_suffix[0].hex, "") : ""
  bucket_name      = var.prefix ? "${local.base_bucket_name}-${local.prefix_suffix}" : local.base_bucket_name

  effective_kms_key_arn = var.kms_key != "" ? var.kms_key : try(aws_kms_key.bucket[0].arn, null)

  replication_enabled = length(var.replication_rules) > 0

  replication_role_arn = var.replication_role != null ? var.replication_role : try(aws_iam_role.replication[0].arn, null)

  replication_destination_arns = local.replication_enabled ? distinct([for r in var.replication_rules : r.destination.bucket]) : []

  replication_destination_resources = flatten([
    for arn in local.replication_destination_arns : [arn, "${arn}/*"]
  ])

  tags = merge(var.tags, { Name = local.bucket_name })
}

###############################################################################
# KMS key (module-managed, created only when no external key is supplied)
###############################################################################

resource "aws_kms_key" "bucket" {
  count = var.kms_key == "" ? 1 : 0

  description             = "Customer-managed KMS key for S3 bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "bucket" {
  count = var.kms_key == "" ? 1 : 0

  name          = "alias/s3-${local.bucket_name}"
  target_key_id = aws_kms_key.bucket[0].key_id
}

###############################################################################
# S3 bucket
###############################################################################

resource "aws_s3_bucket" "bucket" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  request_payer       = var.request_payer
  object_lock_enabled = var.object_lock_configuration != null

  dynamic "grant" {
    for_each = var.grants
    content {
      id          = try(grant.value.id, null)
      type        = grant.value.type
      permissions = grant.value.permissions
      uri         = try(grant.value.uri, null)
    }
  }

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "bucket" {
  bucket = aws_s3_bucket.bucket.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "bucket" {
  bucket = aws_s3_bucket.bucket.id

  rule {
    object_ownership = var.acl != null ? "ObjectWriter" : "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_policy" "bucket" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.bucket.id
  policy = var.policy

  depends_on = [
    aws_s3_bucket_public_access_block.bucket,
  ]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "bucket" {
  count = var.encryption ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key_arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "bucket" {
  bucket = aws_s3_bucket.bucket.id

  versioning_configuration {
    status     = var.versioning ? "Enabled" : "Suspended"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_accelerate_configuration" "bucket" {
  count = var.transfer_acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.bucket.id
  status = var.transfer_acceleration_status
}

resource "aws_s3_bucket_logging" "bucket" {
  count = var.logging != null ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix

  depends_on = [
    aws_s3_bucket_public_access_block.bucket,
    aws_s3_bucket_policy.bucket,
  ]
}

resource "aws_s3_bucket_website_configuration" "bucket" {
  count = var.website != null ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [var.website.index_document] : []
    content {
      suffix = index_document.value
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [var.website.error_document] : []
    content {
      key = error_document.value
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [var.website.redirect_all_requests_to] : []
    content {
      host_name = redirect_all_requests_to.value
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "bucket" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  dynamic "cors_rule" {
    for_each = var.cors_rules
    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "bucket" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  dynamic "rule" {
    for_each = var.lifecycle_rules
    content {
      id     = rule.value.id
      status = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []
        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []
        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "transition" {
        for_each = rule.value.transition
        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transition
        content {
          noncurrent_days           = try(noncurrent_version_transition.value.days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []
        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }
}

resource "aws_s3_bucket_object_lock_configuration" "bucket" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.bucket.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.bucket,
  ]
}

###############################################################################
# Replication
###############################################################################

resource "aws_s3_bucket_replication_configuration" "bucket" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.bucket.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules
    content {
      id       = rule.value.id
      status   = rule.value.status
      priority = try(rule.value.priority, null)

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []
        content {
          prefix = try(filter.value.prefix, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})
            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account, null)

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [rule.value.destination.replica_kms_key_id] : []
          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []
        content {
          status = delete_marker_replication.value
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.bucket,
  ]
}

resource "aws_iam_role" "replication" {
  count = local.replication_enabled && var.replication_role == null ? 1 : 0

  name = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.replication_enabled && var.replication_role == null ? 1 : 0

  name = "CoreS3ReplicationPolicy_${local.bucket_name}"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket",
          "s3:GetBucketVersioning",
        ]
        Resource = [
          aws_s3_bucket.bucket.arn,
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging",
        ]
        Resource = [
          "${aws_s3_bucket.bucket.arn}/*",
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags",
          "s3:ObjectOwnerOverrideToBucketOwner",
        ]
        Resource = local.replication_destination_resources
      }
    ]
  })
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The name of the bucket."
  value       = aws_s3_bucket.bucket.id
}

output "bucket_arn" {
  description = "The ARN of the bucket."
  value       = aws_s3_bucket.bucket.arn
}

output "bucket_regional_domain_name" {
  description = "The region-specific domain name of the bucket."
  value       = aws_s3_bucket.bucket.bucket_regional_domain_name
}

output "website_endpoint" {
  description = "The website endpoint of the bucket when website hosting is configured."
  value       = try(aws_s3_bucket_website_configuration.bucket[0].website_endpoint, null)
}

output "kms_key_arn" {
  description = "The ARN of the KMS key used for encryption (module-created or supplied)."
  value       = local.effective_kms_key_arn
}

output "replication_role_arn" {
  description = "The ARN of the replication role (module-created or supplied)."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.awsRegion

  default_tags {
    tags = local.common_tags
  }
}

################################################################################
# Variables
################################################################################

variable "awsRegion" {
  description = "AWS region in which the network stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix used to name and tag all resources in this stack."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner responsible for the resources in this stack."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names to distinguish build instances."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether public subnets auto-assign public IPv4 addresses on launch."
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Optional explicit first availability zone; defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional explicit second availability zone; falls back to awsAz1 when set, otherwise the second available AZ."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for public subnet A."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for public subnet B."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for management subnet A."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for management subnet B."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for private subnet A."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for private subnet B."
  type        = string
  default     = "10.1.120.0/24"
}

################################################################################
# Data Sources
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Locals
################################################################################

locals {
  az1 = coalesce(var.awsAz1, data.aws_availability_zones.available.names[0])
  az2 = coalesce(var.awsAz2, var.awsAz1, data.aws_availability_zones.available.names[1])

  common_tags = {
    Project = var.projectPrefix
    Owner   = var.resourceOwner
    Build   = var.buildSuffix
  }
}

################################################################################
# VPC
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-vpc-${var.buildSuffix}"
    }
  )
}

################################################################################
# Public Subnets
################################################################################

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-public-${local.az1}-${var.buildSuffix}"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-public-${local.az2}-${var.buildSuffix}"
      Tier = "public"
    }
  )
}

################################################################################
# Management Subnets
################################################################################

resource "aws_subnet" "mgmt_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-management-${local.az1}-${var.buildSuffix}"
      Tier = "management"
    }
  )
}

resource "aws_subnet" "mgmt_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubMgmtBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-management-${local.az2}-${var.buildSuffix}"
      Tier = "management"
    }
  )
}

################################################################################
# Private Subnets
################################################################################

resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivACidr
  availability_zone       = local.az1
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-private-${local.az1}-${var.buildSuffix}"
      Tier = "private"
    }
  )
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.vpcMainSubPrivBCidr
  availability_zone       = local.az2
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-private-${local.az2}-${var.buildSuffix}"
      Tier = "private"
    }
  )
}

################################################################################
# Internet Gateway
################################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-igw-${var.buildSuffix}"
    }
  )
}

################################################################################
# Route Table and Main Route Table Association
################################################################################

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${var.projectPrefix}-rt-main-${var.buildSuffix}"
    }
  )
}

resource "aws_main_route_table_association" "main" {
  vpc_id         = aws_vpc.main.id
  route_table_id = aws_route_table.main.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

################################################################################
# Input variables
################################################################################

variable "region" {
  description = "AWS region in which the benchmark infrastructure is created."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name applied to every named resource in this configuration."
  type        = string
  default     = "benchmark"

  validation {
    condition     = can(regex("^[a-zA-Z0-9-]+$", var.name))
    error_message = "The name must contain only alphanumeric characters and hyphens."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the self-contained VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create."
  type        = number
  default     = 1

  validation {
    condition     = var.listener_rule_count >= 1 && var.listener_rule_count <= 100
    error_message = "The listener rule count must be between 1 and 100."
  }
}

################################################################################
# Locals
################################################################################

locals {
  common_tags = {
    Name = var.name
  }

  alb_name         = "${var.name}-alb"
  target_group_name = "${var.name}-tg"
}

################################################################################
# Availability zones (static provider metadata)
################################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# Network
################################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = local.common_tags
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = local.common_tags
}

resource "aws_security_group" "alb" {
  name        = local.alb_name
  description = "Allow all intra-VPC traffic to and from the internal ${var.name} ALB."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic to destinations within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = local.common_tags
}

################################################################################
# Internal Application Load Balancer
################################################################################

resource "aws_lb" "main" {
  name                       = local.alb_name
  internal                   = true
  load_balancer_type         = "application"
  subnets                    = aws_subnet.public[*].id
  security_groups            = [aws_security_group.alb.id]
  drop_invalid_header_fields = true
  enable_deletion_protection = false

  tags = local.common_tags
}

resource "aws_lb_target_group" "main" {
  name     = local.target_group_name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    port                = "8081"
    protocol            = "HTTP"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = local.common_tags
}

################################################################################
# Self-signed certificate imported into ACM
################################################################################

resource "tls_private_key" "main" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "main" {
  private_key_pem = tls_private_key.main.private_key_pem

  subject {
    common_name  = "${var.name}.internal"
    organization = "benchmark"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
    "client_auth",
  ]

  dns_names = [
    var.name,
    "${var.name}.internal",
    "*.${var.name}.internal",
  ]

  is_ca_certificate = false
}

resource "aws_acm_certificate" "main" {
  certificate_body  = tls_self_signed_cert.main.cert_pem
  private_key       = tls_private_key.main.private_key_pem
  certificate_chain = tls_self_signed_cert.main.cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = local.common_tags
}

################################################################################
# HTTPS listener and path-based rules
################################################################################

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.main.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = local.common_tags
}

resource "aws_lb_listener_rule" "path" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = local.common_tags
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "Identifier of the benchmark VPC."
  value       = aws_vpc.main.id
}

output "subnet_ids" {
  description = "Identifiers of the benchmark subnets."
  value       = aws_subnet.public[*].id
}

output "alb_arn" {
  description = "ARN of the internal Application Load Balancer."
  value       = aws_lb.main.arn
}

output "alb_dns_name" {
  description = "DNS name of the internal Application Load Balancer."
  value       = aws_lb.main.dns_name
}

output "target_group_arn" {
  description = "ARN of the HTTP target group on port 8080."
  value       = aws_lb_target_group.main.arn
}

output "https_listener_arn" {
  description = "ARN of the HTTPS listener on port 443."
  value       = aws_lb_listener.https.arn
}

output "listener_rule_arns" {
  description = "ARNs of the path-based listener rules."
  value       = aws_lb_listener_rule.path[*].arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which to deploy the isolated VPC networking stack."
  type        = string
  default     = "us-east-1"
}

variable "resource_name_prefix" {
  description = "Prefix applied to the Name tag of every resource created by this stack."
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy of the VPC instances (default, dedicated or host)."
  type        = string
  default     = "default"
}

variable "enable_dns_hostnames" {
  description = "Whether DNS hostnames are enabled for instances launched in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported inside the VPC."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "List of CIDR blocks used for the private subnets (one per subnet, paired with the first AZs in the region)."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound (ingress) rules applied to the shared network ACL. Default allows only ephemeral return traffic."
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      action      = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 1024
      to_port     = 65535
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound (egress) rules applied to the shared network ACL. Default allows only HTTPS traffic."
  type        = list(map(string))
  default = [
    {
      rule_number = 100
      protocol    = "tcp"
      action      = "allow"
      cidr_block  = "0.0.0.0/0"
      from_port   = 443
      to_port     = 443
    }
  ]
}

locals {
  name_prefix = var.resource_name_prefix

  common_tags = {
    Environment = var.resource_name_prefix
    ManagedBy   = "Terraform"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_caller_identity" "current" {}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-subnet-${count.index + 1}"
      Type = "private"
    }
  )
}

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-rt-${count.index + 1}"
      Type = "private"
    }
  )
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_network_acl" "private" {
  vpc_id = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.public_inbound_acl_rules

    content {
      rule_no    = tonumber(ingress.value["rule_number"])
      protocol   = ingress.value["protocol"]
      action     = ingress.value["action"]
      cidr_block = ingress.value["cidr_block"]
      from_port  = tonumber(ingress.value["from_port"])
      to_port    = tonumber(ingress.value["to_port"])
    }
  }

  dynamic "egress" {
    for_each = var.public_outbound_acl_rules

    content {
      rule_no    = tonumber(egress.value["rule_number"])
      protocol   = egress.value["protocol"]
      action     = egress.value["action"]
      cidr_block = egress.value["cidr_block"]
      from_port  = tonumber(egress.value["from_port"])
      to_port    = tonumber(egress.value["to_port"])
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-private-nacl"
    }
  )
}

resource "aws_network_acl_association" "private" {
  count = length(var.private_subnets)

  network_acl_id = aws_network_acl.private.id
  subnet_id      = aws_subnet.private[count.index].id
}

resource "aws_kms_key" "s3" {
  description             = "Customer managed key used to encrypt internal S3 data reached through the ${local.name_prefix} S3 gateway endpoint."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-s3-cmk"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "s3" {
  name          = "alias/${local.name_prefix}-s3-cmk"
  target_key_id = aws_kms_key.s3.key_id
}

resource "aws_s3_bucket" "internal" {
  bucket = lower("${local.name_prefix}-internal-data-${data.aws_caller_identity.current.account_id}")

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-internal-data"
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "internal" {
  bucket = aws_s3_bucket.internal.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "internal" {
  bucket = aws_s3_bucket.internal.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "internal" {
  bucket = aws_s3_bucket.internal.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "s3_endpoint" {
  statement {
    sid    = "AllowInternalS3WorkloadAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.internal.arn,
      "${aws_s3_bucket.internal.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceVpc"
      values   = [aws_vpc.main.id]
    }
  }
}

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.main.id
  service_name      = "com.amazonaws.${var.aws_region}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id
  policy            = data.aws_iam_policy_document.s3_endpoint.json

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-s3-gateway-endpoint"
    }
  )
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Controls whether the SQS queue(s) will be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Exact name of the queue. Conflicts with `name_prefix`."
  type        = string
  default     = null

  validation {
    condition     = var.name == null || (length(trimspace(var.name)) > 0 && length(var.name) <= 80)
    error_message = "The queue name must contain between 1 and 80 characters."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate the queue name. Conflicts with `name`."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || (length(trimspace(var.name_prefix)) > 0 && length(var.name_prefix) <= 80)
    error_message = "The queue name prefix must contain between 1 and 80 characters."
  }
}

variable "fifo_queue" {
  description = "Whether the queue is a FIFO queue. The `.fifo` suffix is appended automatically."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content based deduplication on FIFO queues"
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level (FIFO only)"
  type        = string
  default     = null

  validation {
    condition     = var.deduplication_scope == null || contains(["queue", "messageGroup"], var.deduplication_scope)
    error_message = "Valid values for deduplication_scope are `queue` or `messageGroup`."
  }
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group (FIFO only)"
  type        = string
  default     = null

  validation {
    condition     = var.fifo_throughput_limit == null || contains(["perQueue", "perMessageId"], var.fifo_throughput_limit)
    error_message = "Valid values for fifo_throughput_limit are `perQueue` or `perMessageId`."
  }
}

variable "sqs_managed_sse_enabled" {
  description = "Enables SQS managed server-side encryption (SSE-SQS). Automatically applied when no KMS master key is provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "ID or ARN of a custom KMS key used for SSE-KMS. When omitted, SQS managed SSE is used."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "Length of time, in seconds, for which SQS can reuse a data key to encrypt/decrypt messages (SSE-KMS only)"
  type        = number
  default     = null
}

variable "create_queue_policy" {
  description = "Controls whether a queue policy is attached to the main queue"
  type        = bool
  default     = false
}

variable "queue_policy" {
  description = "JSON policy document (source) to attach to the main queue"
  type        = string
  default     = ""
}

variable "queue_policy_override" {
  description = "JSON policy document (override) merged over `queue_policy` before being attached to the main queue"
  type        = string
  default     = ""
}

variable "create_dlq" {
  description = "Controls whether a dead-letter queue is created and configured as the redrive target of the main queue"
  type        = bool
  default     = false
}

variable "dlq_name_suffix" {
  description = "Suffix appended to the main queue name to build the dead-letter queue name"
  type        = string
  default     = "-dlq"

  validation {
    condition     = length(trimspace(var.dlq_name_suffix)) > 0
    error_message = "The dead-letter queue name suffix must not be empty."
  }
}

variable "max_receive_count" {
  description = "Number of times a message is delivered before being moved to the dead-letter queue"
  type        = number
  default     = 5

  validation {
    condition     = var.max_receive_count >= 1
    error_message = "The max receive count must be greater than or equal to 1."
  }
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether a redrive allow policy restricting redrive permissions to the main queue is attached to the dead-letter queue"
  type        = bool
  default     = true
}

variable "delay_seconds" {
  description = "Seconds for which the delivery of all messages in the queue is delayed"
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "Limit of how many bytes a message can contain before SQS rejects it"
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "Number of seconds SQS retains a message"
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "Seconds for which a ReceiveMessage call will wait for a message to arrive (long polling)"
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "Visibility timeout for the queue"
  type        = number
  default     = 30
}

variable "tags" {
  description = "A map of tags to assign to the queues"
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  create = var.create

  fifo_suffix       = ".fifo"
  default_base_name = "sqs-queue"

  # ---------------------------------------------------------------------------
  # Naming (`name` wins over `name_prefix`; a sensible default is used when
  # neither is supplied so that the module can be applied unattended)
  # ---------------------------------------------------------------------------
  name_provided        = var.name != null && trimspace(var.name) != ""
  name_prefix_set      = var.name_prefix != null && trimspace(var.name_prefix) != ""
  name_prefix_provided = !local.name_provided && local.name_prefix_set

  base_name = local.name_provided ? var.name : (local.name_prefix_provided ? var.name_prefix : local.default_base_name)

  # FIFO queue names must terminate with the `.fifo` suffix
  main_fifo_name = endswith(local.base_name, local.fifo_suffix) ? local.base_name : "${local.base_name}${local.fifo_suffix}"

  # The provider appends a unique suffix to `name_prefix`, which would break the
  # mandatory `.fifo` ending, so FIFO queues always use an explicit `name`.
  use_explicit_name = local.name_provided || var.fifo_queue

  queue_name        = local.use_explicit_name ? (var.fifo_queue ? local.main_fifo_name : local.base_name) : null
  queue_name_prefix = local.use_explicit_name ? null : local.base_name

  # ---------------------------------------------------------------------------
  # Dead-letter queue naming
  # ---------------------------------------------------------------------------
  dlq_base_name = "${local.base_name}${var.dlq_name_suffix}"
  dlq_fifo_name = endswith(local.dlq_base_name, local.fifo_suffix) ? local.dlq_base_name : "${local.dlq_base_name}${local.fifo_suffix}"

  dlq_name        = local.use_explicit_name ? (var.fifo_queue ? local.dlq_fifo_name : local.dlq_base_name) : null
  dlq_name_prefix = local.use_explicit_name ? null : local.dlq_base_name

  # ---------------------------------------------------------------------------
  # Encryption: SQS managed SSE applies automatically when no KMS key is given
  # ---------------------------------------------------------------------------
  kms_key_id                        = var.kms_master_key_id != null && trimspace(var.kms_master_key_id) != "" ? var.kms_master_key_id : null
  sqs_managed_sse_enabled           = local.kms_key_id == null ? var.sqs_managed_sse_enabled : false
  kms_data_key_reuse_period_seconds = local.kms_key_id == null ? null : var.kms_data_key_reuse_period_seconds

  # ---------------------------------------------------------------------------
  # Queue policy: source + override merged, Resource defaulting to the main ARN
  # ---------------------------------------------------------------------------
  policy_source   = var.queue_policy != null && trimspace(var.queue_policy) != "" ? jsondecode(var.queue_policy) : {}
  policy_override = var.queue_policy_override != null && trimspace(var.queue_policy_override) != "" ? jsondecode(var.queue_policy_override) : {}

  queue_policy_json = jsonencode(merge(
    {
      Version  = "2012-10-17"
      Resource = local.main_queue_arn
    },
    local.policy_source,
    local.policy_override,
  ))

  # ---------------------------------------------------------------------------
  # Resource references (null safe when nothing is created)
  # ---------------------------------------------------------------------------
  main_queue_arn  = try(aws_sqs_queue.main[0].arn, null)
  main_queue_url  = try(aws_sqs_queue.main[0].url, null)
  main_queue_name = try(aws_sqs_queue.main[0].name, null)

  dlq_queue_arn  = try(aws_sqs_queue.dlq[0].arn, null)
  dlq_queue_url  = try(aws_sqs_queue.dlq[0].url, null)
  dlq_queue_name = try(aws_sqs_queue.dlq[0].name, null)

  main_tags = merge(var.tags, {
    Name = coalesce(local.queue_name, local.queue_name_prefix, local.default_base_name)
  })

  dlq_tags = merge(var.tags, {
    Name = coalesce(local.dlq_name, local.dlq_name_prefix, "${local.default_base_name}${var.dlq_name_suffix}")
  })
}

################################################################################
# Main queue
################################################################################

resource "aws_sqs_queue" "main" {
  count = var.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  kms_master_key_id                 = local.kms_key_id
  kms_data_key_reuse_period_seconds = local.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  redrive_policy = var.create_dlq ? jsonencode({
    deadLetterTargetArn = local.dlq_queue_arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = local.main_tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = !(local.name_provided && local.name_prefix_set)
      error_message = "Only one of `name` or `name_prefix` can be set at the same time."
    }
  }
}

################################################################################
# Queue policy (optional)
################################################################################

resource "aws_sqs_queue_policy" "main" {
  count = var.create && var.create_queue_policy ? 1 : 0

  queue_url = local.main_queue_url
  policy    = local.queue_policy_json
}

################################################################################
# Dead-letter queue (optional)
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = var.create && var.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  fifo_queue                  = var.fifo_queue
  content_based_deduplication = var.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = var.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = var.fifo_queue ? var.fifo_throughput_limit : null

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  # Inherits the encryption settings of the main queue
  kms_master_key_id                 = local.kms_key_id
  kms_data_key_reuse_period_seconds = local.kms_data_key_reuse_period_seconds
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  tags = local.dlq_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_sqs_queue_redrive_allow_policy" "dlq" {
  count = var.create && var.create_dlq && var.create_dlq_redrive_allow_policy ? 1 : 0

  queue_url = local.dlq_queue_url

  redrive_allow_policy = jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [local.main_queue_arn]
  })
}

################################################################################
# Outputs
################################################################################

output "main_queue_arn" {
  description = "ARN of the main SQS queue"
  value       = local.main_queue_arn
}

output "main_queue_url" {
  description = "URL of the main SQS queue"
  value       = local.main_queue_url
}

output "main_queue_name" {
  description = "Name of the main SQS queue"
  value       = local.main_queue_name
}

output "dlq_queue_arn" {
  description = "ARN of the dead-letter queue"
  value       = local.dlq_queue_arn
}

output "dlq_queue_url" {
  description = "URL of the dead-letter queue"
  value       = local.dlq_queue_url
}

output "dlq_queue_name" {
  description = "Name of the dead-letter queue"
  value       = local.dlq_queue_name
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "backup_name" {
  description = "Base name used to name the backup vault, backup plan, and backup selections. Defaults to \"backup\" so apply is non-interactive; override in a real pipeline."
  type        = string
  default     = "backup"

  validation {
    condition     = length(trimspace(var.backup_name)) > 0
    error_message = "backup_name must be a non-empty string."
  }
}

variable "account_type" {
  description = "Account role for this deployment. Either \"workload\" (creates backup plans, IAM role and selections) or \"backup\" (vault only, typically a central backup account)."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be either \"workload\" or \"backup\"."
  }
}

variable "kms_key_arn" {
  description = "Optional customer managed KMS key ARN used to encrypt the backup vault and the notification topic."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON resource policy attached to the backup vault (for example, to allow cross-account copy into this vault)."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention period in days. When set, a vault lock configuration is created."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Optional maximum retention period in days for the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Optional number of days the vault lock remains changeable before becoming immutable."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to send AWS Backup vault events to an SNS topic."
  type        = bool
  default     = false
}

variable "backup_vault_events" {
  description = "List of AWS Backup vault events that trigger SNS notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "sns_topic_arn" {
  description = "Optional pre-existing SNS topic ARN for vault notifications. When null, an SNS topic is created and managed by this configuration."
  type        = string
  default     = null
}

variable "rule_schedule" {
  description = "Cron or rate expression that defines when the backup plan rule runs."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "recovery_point_tags" {
  description = "Tags applied to recovery points created by the backup plan rule."
  type        = map(string)
  default     = {}
}

variable "copy_actions" {
  description = "List of cross-region and/or cross-account copy actions for the backup plan rule. The destination vault ARN must already exist in the target account/region."
  type = list(object({
    destination_vault_arn = string
    lifecycle = optional(object({
      cold_storage_after = optional(number, 30)
      delete_after       = optional(number, 120)
    }), {})
  }))
  default = []
}

variable "selection_resources" {
  description = "Optional list of explicit resource ARNs to include in an additional backup selection."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to all taggable resources created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_iam_policy" "backup_service_role_for_backup" {
  name = "AWSBackupServiceRolePolicyForBackup"
}

###############################################################################
# Locals
###############################################################################

locals {
  is_workload = var.account_type == "workload"

  create_vault_lock          = var.min_retention_days != null
  create_vault_policy        = var.vault_policy != null
  create_notifications_topic = var.enable_aws_backup_vault_notifications && var.sns_topic_arn == null
  create_vault_notifications = var.enable_aws_backup_vault_notifications
  create_explicit_selection  = local.is_workload && length(var.selection_resources) > 0

  common_tags = merge(
    {
      Name        = var.backup_name
      ManagedBy   = "terraform"
      AccountType = var.account_type
    },
    var.tags,
  )

  # Prefer a caller supplied topic; otherwise use the topic managed here.
  # `try` keeps the expression valid when the managed topic has count = 0.
  sns_topic_arn = var.sns_topic_arn != null ? var.sns_topic_arn : try(aws_sns_topic.backup_notifications[0].arn, null)
}

###############################################################################
# Backup vault
###############################################################################

resource "aws_backup_vault" "main" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_policy" "main" {
  count = local.create_vault_policy ? 1 : 0

  backup_vault_name = aws_backup_vault.main.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_lock_configuration" "main" {
  count = local.create_vault_lock ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

###############################################################################
# Vault notifications
###############################################################################

resource "aws_sns_topic" "backup_notifications" {
  count = local.create_notifications_topic ? 1 : 0

  name              = "backup-notifications-${var.backup_name}"
  kms_master_key_id = var.kms_key_arn
  tags              = local.common_tags
}

resource "aws_sns_topic_policy" "backup_notifications" {
  count = local.create_notifications_topic ? 1 : 0

  arn = aws_sns_topic.backup_notifications[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "backup-notifications-policy"
    Statement = [
      {
        Sid       = "AllowBackupServicePublish"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "SNS:Publish"
        Resource  = aws_sns_topic.backup_notifications[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })
}

resource "aws_backup_vault_notifications" "main" {
  count = local.create_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.main.name
  sns_topic_arn       = local.sns_topic_arn
  backup_vault_events = var.backup_vault_events
}

###############################################################################
# Backup service IAM role (workload accounts only)
###############################################################################

resource "aws_iam_role" "backup" {
  count = local.is_workload ? 1 : 0

  name_prefix = "aws-backup-"
  description = "Service role assumed by AWS Backup to protect resources in ${var.backup_name}."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowBackupServiceAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "backup.amazonaws.com" }
        Action    = "sts:AssumeRole"
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup_service_role_for_backup" {
  count = local.is_workload ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = data.aws_iam_policy.backup_service_role_for_backup.arn
}

###############################################################################
# Backup plan and selections (workload accounts only)
###############################################################################

resource "aws_backup_plan" "main" {
  count = local.is_workload ? 1 : 0

  name = "plan-${var.backup_name}-backup"

  rule {
    rule_name         = "rule-${var.backup_name}-backup"
    target_vault_name = aws_backup_vault.main.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = var.recovery_point_tags

    dynamic "copy_action" {
      for_each = var.copy_actions

      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        lifecycle {
          cold_storage_after = copy_action.value.lifecycle.cold_storage_after
          delete_after       = copy_action.value.lifecycle.delete_after
        }
      }
    }
  }

  tags = local.common_tags
}

resource "aws_backup_selection" "tags" {
  count = local.is_workload ? 1 : 0

  name         = "plan-${var.backup_name}-selection-tags"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.main[0].id

  resources = ["*"]

  condition {
    string_equals {
      key   = "Backup"
      value = "true"
    }
  }
}

resource "aws_backup_selection" "resources" {
  count = local.create_explicit_selection ? 1 : 0

  name         = "plan-${var.backup_name}-selection-resources"
  iam_role_arn = aws_iam_role.backup[0].arn
  plan_id      = aws_backup_plan.main[0].id

  resources = var.selection_resources
}

###############################################################################
# Outputs
###############################################################################

output "backup_vault_arn" {
  description = "ARN of the backup vault."
  value       = aws_backup_vault.main.arn
}

output "backup_vault_name" {
  description = "Name of the backup vault."
  value       = aws_backup_vault.main.name
}

output "backup_plan_id" {
  description = "ID of the backup plan when account_type is \"workload\"."
  value       = try(aws_backup_plan.main[0].id, null)
}

output "backup_iam_role_arn" {
  description = "ARN of the AWS Backup service role when account_type is \"workload\"."
  value       = try(aws_iam_role.backup[0].arn, null)
}

output "backup_notifications_topic_arn" {
  description = "SNS topic ARN used for backup vault notifications, if any."
  value       = local.sns_topic_arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }

    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }
}

################################################################################
# Inputs
################################################################################

variable "config_name" {
  description = "Base name for the AWS Config stack. When null or empty the naming convention falls back to \"config\" plus a generated petname suffix."
  type        = string
  default     = null
}

variable "environment" {
  description = "Environment name applied to every resource tag."
  type        = string
  default     = "prod"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

################################################################################
# Naming convention: default to "config", append a petname suffix for uniqueness
################################################################################

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  provided_name = var.config_name == null ? "" : trimspace(var.config_name)
  base_name     = local.provided_name != "" ? local.provided_name : "config"
  name          = "${local.base_name}-${random_pet.this.id}"

  bucket_name = "${local.name}-config-snapshots-${data.aws_caller_identity.current.account_id}"
  key_prefix  = "awsconfig/records"

  tags = merge(var.tags, {
    Name        = local.name
    Prefix      = local.base_name
    Environment = var.environment
    ManagedBy   = "terraform"
  })
}

################################################################################
# Provider metadata
################################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

################################################################################
# KMS customer managed key used to encrypt the AWS Config SNS topic and the
# snapshot bucket (dual purpose: SNS topic + S3 default encryption).
################################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableAccountKeyAdministrationAndUse"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowSnsServiceToEncryptTopicMessages"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["sns.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey*",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "config" {
  description             = "Customer managed key used to encrypt AWS Config artifacts (SNS topic and snapshot bucket) for ${local.name}"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.tags
}

resource "aws_kms_alias" "config" {
  name          = "alias/${local.name}-config"
  target_key_id = aws_kms_key.config.key_id
}

################################################################################
# SNS topic that receives AWS Config notifications
################################################################################

resource "aws_sns_topic" "config" {
  name              = local.name
  kms_master_key_id = aws_kms_key.config.id
  tags              = local.tags
}

data "aws_iam_policy_document" "sns" {
  statement {
    sid    = "AllowAccountOwnerAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "SNS:GetTopicAttributes",
      "SNS:SetTopicAttributes",
      "SNS:AddPermission",
      "SNS:RemovePermission",
      "SNS:DeleteTopic",
      "SNS:Subscribe",
      "SNS:ListSubscriptionsByTopic",
      "SNS:Publish",
      "SNS:Receive",
    ]

    resources = [aws_sns_topic.config.arn]
  }

  statement {
    sid    = "AllowAWSConfigToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["SNS:Publish"]
    resources = [aws_sns_topic.config.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_sns_topic_policy" "config" {
  arn    = aws_sns_topic.config.arn
  policy = data.aws_iam_policy_document.sns.json
}

################################################################################
# S3 bucket that stores AWS Config snapshots
################################################################################

resource "aws_s3_bucket" "config" {
  bucket        = local.bucket_name
  force_destroy = true
  tags          = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "config" {
  bucket                  = aws_s3_bucket.config.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Default encryption uses the dedicated customer managed key so that AWS Config
# snapshot data is encrypted with a CMK (clears Trivy AWS-0132).
resource "aws_s3_bucket_server_side_encryption_configuration" "config" {
  bucket = aws_s3_bucket.config.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.config.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "config" {
  bucket = aws_s3_bucket.config.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid    = "AWSConfigBucketPermissionsCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.config.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AWSConfigBucketExistenceCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.config.arn]

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }

  statement {
    sid    = "AWSConfigBucketDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/${local.key_prefix}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "AWS:SourceAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "config" {
  bucket     = aws_s3_bucket.config.id
  policy     = data.aws_iam_policy_document.bucket.json
  depends_on = [aws_s3_bucket_public_access_block.config]
}

################################################################################
# IAM role assumed by AWS Config
################################################################################

data "aws_iam_policy_document" "config_assume_role" {
  statement {
    sid     = "AllowAWSConfigToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["config.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "config" {
  name               = local.name
  description        = "Service role used by AWS Config to record configuration changes and evaluate rules"
  assume_role_policy = data.aws_iam_policy_document.config_assume_role.json
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

data "aws_iam_policy_document" "config_inline" {
  statement {
    sid    = "ConfigBucketPermissionsCheck"
    effect = "Allow"

    actions = [
      "s3:GetBucketAcl",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.config.arn]
  }

  statement {
    sid       = "ConfigBucketSnapshotDelivery"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.config.arn}/${local.key_prefix}/*"]
  }

  statement {
    sid       = "ConfigSnsNotifications"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.config.arn]
  }

  statement {
    sid    = "ConfigKmsEncryptedArtifactsAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey*",
    ]

    resources = [aws_kms_key.config.arn]
  }
}

resource "aws_iam_role_policy" "config" {
  name   = "${local.name}-config-delivery"
  role   = aws_iam_role.config.id
  policy = data.aws_iam_policy_document.config_inline.json
}

################################################################################
# Recorder, delivery channel and recorder status
################################################################################

resource "aws_config_configuration_recorder" "config" {
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "config" {
  s3_bucket_name = aws_s3_bucket.config.id
  s3_key_prefix  = local.key_prefix
  sns_topic_arn  = aws_sns_topic.config.arn

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_configuration_recorder_status" "config" {
  name       = aws_config_configuration_recorder.config.name
  is_enabled = true

  depends_on = [
    aws_config_delivery_channel.config,
    aws_iam_role_policy_attachment.config_managed,
    aws_iam_role_policy.config,
    aws_s3_bucket_policy.config,
    aws_sns_topic_policy.config,
  ]
}

################################################################################
# Managed AWS Config rules
#
# All rules below are published by AWS and are evaluated on configuration
# changes, which is the default evaluation trigger for these identifiers.
################################################################################

resource "aws_config_config_rule" "cloudtrail_enabled" {
  name = "cloudtrail-enabled"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name = "iam-pw-policy"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  input_parameters = jsonencode({
    MinimumPasswordLength      = "14"
    PasswordReusePrevention    = "24"
    RequireLowercaseCharacters = "true"
    RequireNumbers             = "true"
    RequireSymbols             = "true"
    RequireUppercaseCharacters = "true"
  })

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name = "ec2-vpc"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name = "root-mfa-enabled"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

# ACM_CERTIFICATE_EXPIRATION_CHECK is a periodic rule, so it is evaluated on a
# schedule instead of on configuration changes.
resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  input_parameters = jsonencode({
    daysToExpiration = "30"
  })

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name = "ebs-inuse-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name = "ec2-imdsv2-check"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name = "rds-encrypted"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private" {
  name = "rds-private"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name = "rds-private-snapshots"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "required_tags" {
  name = "required-tags"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  # The managed REQUIRED_TAGS rule only accepts tag1Key/tag1Value ...
  # tag6Key/tag6Value; resource-type restriction is expressed via scope.
  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  tags       = local.tags
  depends_on = [aws_config_configuration_recorder.config]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

#############################################
