terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "prefix" {
  description = "Prefix applied to all resource names created by this stack."
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ARN of an existing ACM certificate for the HTTPS listener. When null a self-signed certificate is generated and imported."
  type        = string
  default     = null
}

variable "url" {
  description = "Optional external URL override for the n8n WEBHOOK_URL environment variable."
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Number of ECS tasks to run."
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for n8n."
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider (FARGATE or FARGATE_SPOT)."
  type        = string
  default     = "FARGATE_SPOT"
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  azs                  = slice(data.aws_availability_zones.available.names, 0, 3)
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  container_name = "n8n"

  certificate_arn = var.certificate_arn != null ? var.certificate_arn : aws_acm_certificate.n8n[0].arn

  webhook_url = coalesce(var.url, "https://${aws_lb.main.dns_name}")

  common_tags = {
    Project   = var.prefix
    ManagedBy = "terraform"
  }
}

###############################################################################
# Networking - VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-igw"
  })
}

###############################################################################
# Networking - Subnets (private x3, public x3)
###############################################################################

resource "aws_subnet" "private" {
  count = 3

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-private-${count.index + 1}"
    Tier = "private"
  })
}

resource "aws_subnet" "public" {
  count = 3

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-public-${count.index + 1}"
    Tier = "public"
  })
}

###############################################################################
# Networking - Route tables (no NAT / no VPN egress)
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = 3

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count = 3

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Security groups
###############################################################################

resource "aws_security_group" "alb" {
  name        = "${var.prefix}-alb-sg"
  description = "Ingress HTTP/HTTPS for the ${var.prefix} internal ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-alb-sg"
  })
}

resource "aws_security_group" "tasks" {
  name        = "${var.prefix}-tasks-sg"
  description = "n8n ECS task traffic from the ALB only"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n container port from the ALB security group"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-tasks-sg"
  })
}

resource "aws_security_group" "efs" {
  name        = "${var.prefix}-efs-sg"
  description = "NFS access to the ${var.prefix} EFS file system"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from within the VPC"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-efs-sg"
  })
}

###############################################################################
# TLS / ACM certificate for the HTTPS listener
###############################################################################

resource "tls_private_key" "n8n" {
  count = var.certificate_arn == null ? 1 : 0

  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "n8n" {
  count = var.certificate_arn == null ? 1 : 0

  private_key_pem = tls_private_key.n8n[0].private_key_pem

  subject {
    common_name  = "${var.prefix}.internal"
    organization = "n8n"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "n8n" {
  count = var.certificate_arn == null ? 1 : 0

  private_key       = tls_private_key.n8n[0].private_key_pem
  certificate_body  = tls_self_signed_cert.n8n[0].cert_pem
  certificate_chain = tls_self_signed_cert.n8n[0].cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-cert"
  })
}

###############################################################################
# Application Load Balancer (internal, placed in the public subnets)
###############################################################################

resource "aws_lb" "main" {
  name                       = "${var.prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-alb"
  })
}

resource "aws_lb_target_group" "n8n" {
  name                 = "${var.prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  target_type          = "ip"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-tg"
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-https-listener"
  })
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-http-listener"
  })
}

###############################################################################
# EFS - encrypted persistent storage for n8n
###############################################################################

resource "aws_efs_file_system" "n8n" {
  creation_token = "${var.prefix}-efs"
  encrypted      = true

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-efs"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_efs_mount_target" "n8n" {
  count = 3

  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-efs-ap"
  })
}

###############################################################################
# CloudWatch logs
###############################################################################

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.prefix}-logs"
  retention_in_days = 1

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-logs"
  })
}

###############################################################################
# IAM
###############################################################################

resource "aws_iam_role" "task_role" {
  name = "${var.prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-task-role"
  })
}

resource "aws_iam_role" "execution_role" {
  name = "${var.prefix}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-execution-role"
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.prefix}-task-logs"
  role = aws_iam_role.task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_efs" {
  name = "${var.prefix}-task-efs"
  role = aws_iam_role.task_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:ClientRootAccess"
        ]
        Resource = aws_efs_file_system.n8n.arn
      }
    ]
  })
}

resource "aws_iam_role_policy" "execution_logs" {
  name = "${var.prefix}-execution-logs"
  role = aws_iam_role.execution_role.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      }
    ]
  })
}

###############################################################################
# ECS cluster
###############################################################################

resource "aws_ecs_cluster" "main" {
  name = "${var.prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-cluster"
  })
}

resource "aws_ecs_cluster_capacity_providers" "main" {
  cluster_name       = aws_ecs_cluster.main.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

###############################################################################
# ECS task definition
###############################################################################

resource "aws_ecs_task_definition" "n8n" {
  family                   = "${var.prefix}-task"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  task_role_arn            = aws_iam_role.task_role.arn
  execution_role_arn       = aws_iam_role.execution_role.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = local.container_name
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.name
          "awslogs-stream-prefix" = var.prefix
        }
      }
    }
  ])

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-task"
  })
}

###############################################################################
# ECS service
###############################################################################

resource "aws_ecs_service" "n8n" {
  name            = "${var.prefix}-service"
  cluster         = aws_ecs_cluster.main.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = local.container_name
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_ecs_cluster_capacity_providers.main,
    aws_efs_mount_target.n8n,
  ]

  tags = merge(local.common_tags, {
    Name = "${var.prefix}-service"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name."
  type        = string
  default     = "production"
}

variable "stack" {
  description = "Logical stack name for the data platform."
  type        = string
  default     = "data"
}

variable "admin_cidr" {
  description = "Placeholder administrative CIDR allowed to reach the bastion host over SSH."
  type        = string
  default     = "203.0.113.0/24"
}

locals {
  application = "dosomething-quasar"
  environment = var.environment
  stack       = var.stack

  common_tags = {
    Application = local.application
    Environment = local.environment
    Stack       = local.stack
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.255.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

resource "aws_subnet" "rds_1a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.255.100.0/24"
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.255.101.0/24"
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

resource "aws_db_subnet_group" "rds" {
  name       = "quasar-rds"
  subnet_ids = [aws_subnet.rds_1a.id, aws_subnet.rds_1e.id]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS"
  })
}

resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host access for the Quasar data stack."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the administrative CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [var.admin_cidr]
  }

  egress {
    description = "Intra-VPC egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HAProxy load balancer for the Quasar data stack."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from public clients"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from public clients"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from the bastion host"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Intra-VPC egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "CI/CD automation node for the Quasar data stack."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion host"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "Jenkins web UI from the HA proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Intra-VPC egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute nodes for the Quasar data stack."
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "SSH from the bastion host"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from the Jenkins node"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Intra-VPC egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database tier for the Quasar data stack."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "PostgreSQL from anywhere (explicit data-stack baseline exception)"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from the ETL nodes"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Intra-VPC egress only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.2"
    }
  }
}

###############################################################################
# Data sources (static / provider metadata only - never remote infra lookups)
###############################################################################

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

###############################################################################
# Global creation control
###############################################################################

variable "create" {
  description = "Global creation control. When false, no resources are created."
  type        = bool
  default     = true
}

variable "environment" {
  description = "Environment name used for tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Identity variables
###############################################################################

variable "function_name" {
  description = "Name of the Lambda function that CodeDeploy will deploy."
  type        = string
  default     = "codedeploy-bluegreen-demo-fn"
}

variable "alias_name" {
  description = "Name of the Lambda alias used for blue/green traffic shifting."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Lambda version currently receiving traffic (blue)."
  type        = string
  default     = "1"
}

variable "target_version" {
  description = "Lambda version that will receive traffic after deployment (green)."
  type        = string
  default     = "2"
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked before traffic is shifted to the new version."
  type        = string
  default     = ""
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional Lambda ARN invoked after traffic is shifted to the new version."
  type        = string
  default     = ""
}

###############################################################################
# Behaviour variables
###############################################################################

variable "app_name" {
  description = "Name of the CodeDeploy application (and base name for related resources)."
  type        = string
  default     = "codedeploy-bluegreen-demo"
}

variable "deployment_group_name" {
  description = "Optional explicit deployment group name. Defaults to <app_name>-<alias_name>."
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create the CodeDeploy application."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an already-existing CodeDeploy application."
  type        = bool
  default     = false
}

variable "create_deployment_group" {
  description = "Whether to create the CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an already-existing CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "deployment_config_name" {
  description = "CodeDeploy deployment configuration name."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "create_codedeploy_role" {
  description = "Whether to create the IAM role used by CodeDeploy."
  type        = bool
  default     = true
}

variable "codedeploy_role_arn" {
  description = "Existing CodeDeploy role ARN to use when create_codedeploy_role is false."
  type        = string
  default     = ""
}

variable "codedeploy_service_principals" {
  description = "STS service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline policy granting lambda:InvokeFunction for lifecycle hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline policy granting sns:Publish for notification triggers."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to generate the AppSpec revision and the deployment script."
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to actually execute the generated deployment script."
  type        = bool
  default     = false
}

variable "save_deploy_script" {
  description = "Whether to persist the generated AppSpec and deploy script locally."
  type        = bool
  default     = false
}

variable "force_deploy" {
  description = "When true, a random UUID trigger forces the deployment to re-run on every apply."
  type        = bool
  default     = false
}

variable "aws_cli_command" {
  description = "AWS CLI executable used inside the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between deployment status polls."
  type        = number
  default     = 5
}

variable "wait_for_deployment" {
  description = "Whether the generated script waits for the deployment to reach a terminal state."
  type        = bool
  default     = true
}

variable "alarm_names" {
  description = "CloudWatch alarm names used to monitor the deployment."
  type        = list(string)
  default     = []
}

variable "ignore_poll_alarm_failure" {
  description = "Whether to ignore failures while polling CloudWatch alarms."
  type        = bool
  default     = false
}

variable "auto_rollback_enabled" {
  description = "Whether automatic rollback is enabled for the deployment group."
  type        = bool
  default     = true
}

variable "auto_rollback_events" {
  description = "Events that trigger an automatic rollback."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "trigger_names" {
  description = "Names of the SNS notification triggers (index-aligned with trigger_target_arns)."
  type        = list(string)
  default     = []
}

variable "trigger_target_arns" {
  description = "Target ARNs of the SNS notification triggers (index-aligned with trigger_names)."
  type        = list(string)
  default     = []
}

variable "trigger_events" {
  description = "CodeDeploy deployment lifecycle events that fire each notification trigger."
  type        = list(string)
  default     = ["DeploymentFailure"]
}

###############################################################################
# Locals
###############################################################################

locals {
  region     = data.aws_region.current.name
  account_id = data.aws_caller_identity.current.account_id
  partition  = "aws"

  common_tags = merge(
    var.tags,
    {
      Name        = var.app_name
      Environment = var.environment
      ManagedBy   = "terraform"
    }
  )

  base_deployment_group_name = coalesce(var.deployment_group_name, "${var.app_name}-${var.alias_name}")

  codedeploy_app_name = try(aws_codedeploy_app.this[0].name, var.app_name)

  resolved_deployment_group_name = try(
    aws_codedeploy_deployment_group.this[0].deployment_group_name,
    local.base_deployment_group_name
  )

  codedeploy_role_arn = try(aws_iam_role.codedeploy[0].arn, var.codedeploy_role_arn)

  lambda_hooks = merge(
    var.before_allow_traffic_hook_arn != "" ? { BeforeAllowTraffic = var.before_allow_traffic_hook_arn } : {},
    var.after_allow_traffic_hook_arn != "" ? { AfterAllowTraffic = var.after_allow_traffic_hook_arn } : {}
  )

  appspec_properties = merge(
    {
      Name           = var.function_name
      Alias          = var.alias_name
      CurrentVersion = tostring(var.current_version)
      TargetVersion  = tostring(var.target_version)
    },
    length(keys(local.lambda_hooks)) > 0 ? { Hooks = [local.lambda_hooks] } : {}
  )

  appspec = jsonencode({
    version = "0.0"
    Resources = [
      {
        (var.function_name) = {
          Type       = "AWS::Lambda::Function"
          Properties = local.appspec_properties
        }
      }
    ]
  })

  appspec_path        = "${path.module}/appspec.json"
  deploy_script_path  = "${path.module}/deploy.sh"
  deploy_artifacts_on = var.create && var.create_deployment && (var.save_deploy_script || var.run_deployment)

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    AWS_REGION="${local.region}"
    APPLICATION_NAME="${local.codedeploy_app_name}"
    DEPLOYMENT_GROUP_NAME="${local.resolved_deployment_group_name}"
    APPSPEC_FILE="${local.appspec_path}"
    WAIT_FOR_DEPLOYMENT="${var.wait_for_deployment}"
    SLEEP_TIMER="${var.get_deployment_sleep_timer}"

    echo "Creating CodeDeploy deployment for $${APPLICATION_NAME} (group: $${DEPLOYMENT_GROUP_NAME})"

    DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
      --application-name "$${APPLICATION_NAME}" \
      --deployment-group-name "$${DEPLOYMENT_GROUP_NAME}" \
      --revision "file://$${APPSPEC_FILE}" \
      --region "$${AWS_REGION}" \
      --query 'deploymentId' \
      --output text)

    echo "Deployment started: $${DEPLOYMENT_ID}"

    if [ "$${WAIT_FOR_DEPLOYMENT}" != "true" ]; then
      echo "Skipping deployment monitoring."
      exit 0
    fi

    while true; do
      STATUS=$(${var.aws_cli_command} deploy get-deployment \
        --deployment-id "$${DEPLOYMENT_ID}" \
        --region "$${AWS_REGION}" \
        --query 'deploymentInfo.status' \
        --output text)

      echo "Deployment status: $${STATUS}"

      case "$${STATUS}" in
        Succeeded)
          echo "Deployment completed successfully."
          exit 0
          ;;
        Failed|Stopped)
          echo "Deployment did not succeed: $${STATUS}" >&2
          exit 1
          ;;
        *)
          sleep "$${SLEEP_TIMER}"
          ;;
      esac
    done
  EOT
}

###############################################################################
# Lambda execution role (greenfield: the compute target is created in-file)
###############################################################################

resource "aws_iam_role" "lambda" {
  count = var.create ? 1 : 0

  name = "${var.function_name}-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution" {
  count = var.create ? 1 : 0

  role       = aws_iam_role.lambda[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

###############################################################################
# Lambda function code (placeholder packaged from a local stub)
###############################################################################

resource "local_file" "lambda_handler" {
  count = var.create ? 1 : 0

  content = <<-EOT
    import json


    def handler(event, context):
        """Placeholder handler for the blue/green deployment target."""
        return {
            "statusCode": 200,
            "body": json.dumps({"message": "ok", "alias": "${var.alias_name}"}),
        }
  EOT

  filename        = "${path.module}/lambda_src/index.py"
  file_permission = "0644"
}

data "archive_file" "lambda_package" {
  count = var.create ? 1 : 0

  type        = "zip"
  source_file = local_file.lambda_handler[0].filename
  output_path = "${path.module}/lambda_src/index.zip"

  depends_on = [local_file.lambda_handler]
}

resource "aws_lambda_function" "this" {
  count = var.create ? 1 : 0

  function_name = var.function_name
  role          = aws_iam_role.lambda[0].arn
  handler       = "index.handler"
  runtime       = "python3.12"
  publish       = true

  filename         = data.archive_file.lambda_package[0].output_path
  source_code_hash = data.archive_file.lambda_package[0].output_base64sha256

  tags = local.common_tags

  depends_on = [aws_iam_role_policy_attachment.lambda_basic_execution]
}

resource "aws_lambda_alias" "this" {
  count = var.create ? 1 : 0

  name             = var.alias_name
  description      = "Blue/green alias managed by Terraform"
  function_name    = aws_lambda_function.this[0].function_name
  function_version = aws_lambda_function.this[0].version
}

###############################################################################
# CodeDeploy application
###############################################################################

resource "aws_codedeploy_app" "this" {
  count = var.create && var.create_app && !var.use_existing_app ? 1 : 0

  name             = var.app_name
  compute_platform = "Lambda"

  tags = local.common_tags
}

###############################################################################
# CodeDeploy IAM role
###############################################################################

resource "aws_iam_role" "codedeploy" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  name = "${var.app_name}-codedeploy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = var.codedeploy_service_principals
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  count = var.create && var.create_codedeploy_role ? 1 : 0

  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSCodeDeployRoleForLambda"
}

resource "aws_iam_role_policy" "codedeploy_hooks" {
  count = var.create && var.create_codedeploy_role && var.attach_hooks_policy && (
    var.before_allow_traffic_hook_arn != "" || var.after_allow_traffic_hook_arn != ""
  ) ? 1 : 0

  name = "${var.app_name}-codedeploy-hooks"
  role = aws_iam_role.codedeploy[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "lambda:InvokeFunction"
        ]
        Resource = compact([
          var.before_allow_traffic_hook_arn,
          var.after_allow_traffic_hook_arn
        ])
      }
    ]
  })
}

resource "aws_iam_role_policy" "codedeploy_triggers" {
  count = var.create && var.create_codedeploy_role && var.attach_triggers_policy ? 1 : 0

  name = "${var.app_name}-codedeploy-triggers"
  role = aws_iam_role.codedeploy[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "sns:Publish"
        ]
        Resource = length(var.trigger_target_arns) > 0 ? var.trigger_target_arns : ["*"]
      }
    ]
  })
}

###############################################################################
# CodeDeploy deployment group
###############################################################################

resource "aws_codedeploy_deployment_group" "this" {
  count = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? 1 : 0

  app_name               = local.codedeploy_app_name
  deployment_group_name  = local.base_deployment_group_name
  service_role_arn       = local.codedeploy_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.auto_rollback_enabled
    events  = var.auto_rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = length(var.alarm_names) > 0 ? [1] : []

    content {
      enabled                   = true
      alarms                    = var.alarm_names
      ignore_poll_alarm_failure = var.ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = {
      for idx, name in var.trigger_names : idx => {
        name = name
        arn  = var.trigger_target_arns[idx]
      } if length(var.trigger_target_arns) > idx
    }

    content {
      trigger_name       = trigger_configuration.value.name
      trigger_target_arn = trigger_configuration.value.arn
      trigger_events     = var.trigger_events
    }
  }

  tags = merge(local.common_tags, {
    LambdaAliasArn = aws_lambda_alias.this[0].arn
  })
}

###############################################################################
# Locally generated deployment artifacts
###############################################################################

resource "local_file" "appspec" {
  count = local.deploy_artifacts_on ? 1 : 0

  content  = local.appspec
  filename = local.appspec_path
}

resource "local_file" "deploy_script" {
  count = local.deploy_artifacts_on ? 1 : 0

  content         = local.deploy_script
  filename        = local.deploy_script_path
  file_permission = "0755"
}

resource "null_resource" "deployment" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    force = var.force_deploy ? uuid() : sha256(jsonencode([
      local.appspec,
      local.codedeploy_app_name,
      local.resolved_deployment_group_name,
      var.function_name,
      var.alias_name
    ]))
  }

  provisioner "local-exec" {
    working_dir = path.module
    command     = "bash ${local.deploy_script_path}"
  }

  depends_on = [
    local_file.appspec,
    local_file.deploy_script
  ]
}

###############################################################################
# Outputs
###############################################################################

output "codedeploy_app_name" {
  description = "Name of the created CodeDeploy application (null when not created)."
  value       = var.create && var.create_app && !var.use_existing_app ? try(aws_codedeploy_app.this[0].name, null) : null
}

output "codedeploy_deployment_group_id" {
  description = "ID of the created CodeDeploy deployment group (null when not created)."
  value       = var.create && var.create_deployment_group && !var.use_existing_deployment_group ? try(aws_codedeploy_deployment_group.this[0].id, null) : null
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy IAM role (null when not created)."
  value       = var.create && var.create_codedeploy_role ? try(aws_iam_role.codedeploy[0].arn, null) : null
}

output "appspec_path" {
  description = "Path to the generated AppSpec revision file (null when not generated)."
  value       = local.deploy_artifacts_on ? local.appspec_path : null
}

output "deploy_script_path" {
  description = "Path to the generated deployment script (null when not generated)."
  value       = local.deploy_artifacts_on ? local.deploy_script_path : null
}

output "lambda_function_name" {
  description = "Name of the deployment target Lambda function (null when not created)."
  value       = var.create ? try(aws_lambda_function.this[0].function_name, null) : null
}

output "lambda_alias_arn" {
  description = "ARN of the Lambda alias used for traffic shifting (null when not created)."
  value       = var.create ? try(aws_lambda_alias.this[0].arn, null) : null
}

output "aws_account_id" {
  description = "Account ID in which the resources are deployed."
  value       = local.account_id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "internal_domain" {
  description = "Internal DNS domain name used for DHCP option set and the private Route 53 hosted zone."
  type        = string
  default     = "internal"
}

variable "public_dns_resolver" {
  description = "Public DNS resolver handed to DHCP clients in addition to AmazonProvidedDNS."
  type        = string
  default     = "8.8.8.8"
}

variable "admin_cidrs" {
  description = "List of admin CIDR ranges allowed to SSH into instances via the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

variable "environment" {
  description = "Environment name applied to all resources via tags."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  common_tags = merge(
    {
      Environment = var.environment
      ManagedBy   = "terraform"
    },
    var.tags
  )
}

data "aws_availability_zones" "available" {
  state = "available"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "ig"
  })
}

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain
