resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "SSH access from configured admin CIDRs and from group members"
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.admin_cidrs

    content {
      description = "SSH from admin CIDR ${ingress.value}"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  ingress {
    description = "SSH from group members"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Home SSH"
  })
}

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "SSH access from within the VPC and from group members"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from group members"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Allow all traffic within the VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Packer SSH"
  })
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

variable "base_bucket_name" {
  type    = string
  default = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  type    = bool
  default = false
}

variable "use_random_suffix" {
  type    = bool
  default = false
}

variable "enable_s3_public_access_block" {
  type    = bool
  default = true
}

variable "object_ownership" {
  type    = string
  default = "BucketOwnerEnforced"
}

variable "kms_master_key_id" {
  type    = string
  default = null
}

variable "bucket_key_enabled" {
  type    = bool
  default = false
}

variable "versioning_status" {
  type    = string
  default = "Enabled"
}

variable "force_destroy" {
  type    = bool
  default = false
}

variable "transition_default_minimum_object_size" {
  type    = string
  default = "all_storage_classes_128K"
}

variable "enable_analytics" {
  type    = bool
  default = true
}

variable "enable_bucket_inventory" {
  type    = bool
  default = false
}

variable "logging_bucket" {
  type    = string
  default = null
}

variable "transfer_acceleration" {
  type    = string
  default = null
}

variable "s3_bucket_acl" {
  type    = string
  default = null
}

variable "cors_rules" {
  type    = list(any)
  default = []
}

variable "custom_bucket_policy" {
  type    = string
  default = ""
}

variable "tags" {
  type    = map(string)
  default = {}
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "aws_iam_account_alias" "this" {
  account_alias = local.account_alias
}

locals {
  account_alias = substr(
    "${replace(lower(var.base_bucket_name), "/[^a-z0-9-]/", "-")}-${random_id.bucket_suffix.hex}",
    0,
    63
  )

  alias_prefix    = var.use_account_alias_prefix ? "${lower(aws_iam_account_alias.this.account_alias)}-" : ""
  random_prefix   = var.use_random_suffix ? "${random_id.bucket_suffix.hex}-" : ""
  bucket_name     = "${local.alias_prefix}${local.random_prefix}${var.base_bucket_name}"
  log_bucket_name = substr("${local.bucket_name}-logs", 0, 63)

  effective_kms_key_arn = var.kms_master_key_id != null ? var.kms_master_key_id : aws_kms_key.this.arn
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key for S3 bucket ${local.bucket_name}"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  tags = merge(var.tags, { Name = local.bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms_key_policy" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUseOfKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key_policy" "this" {
  key_id = aws_kms_key.this.id
  policy = data.aws_iam_policy_document.kms_key_policy.json
}

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = merge(var.tags, { Name = local.bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.effective_kms_key_arn
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket                                 = aws_s3_bucket.this.id
  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  depends_on = [aws_s3_bucket_versioning.this]

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {
      prefix = ""
    }

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-transition"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }
  }

  rule {
    id     = "noncurrent-version-expiration"
    status = "Enabled"

    filter {
      prefix = ""
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  rule {
    id     = "analytics-export-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketAnalytics/"
    }

    expiration {
      days = 30
    }
  }

  rule {
    id     = "inventory-export-expiration"
    status = "Enabled"

    filter {
      prefix = "_AWSBucketInventory/"
    }

    expiration {
      days = 14
    }
  }
}

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "analytics"

  filter {
    prefix = "_AWSBucketAnalytics/"
  }

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = "_AWSBucketAnalytics/"
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket                   = aws_s3_bucket.this.id
  name                     = "inventory"
  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
    "ObjectLockRetainUntilDate",
    "ObjectLockMode",
    "ObjectLockLegalHoldStatus",
    "IntelligentTieringAccessTier",
    "BucketKeyStatus",
    "ChecksumAlgorithm",
  ]

  filter {
    prefix = "_AWSBucketInventory/"
  }

  destination {
    bucket {
      bucket_arn = aws_s3_bucket.this.arn
      format     = "ORC"
      prefix     = "_AWSBucketInventory/"
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

data "aws_iam_policy_document" "bucket_policy" {
  source_policy_documents = compact([var.custom_bucket_policy])

  statement {
    sid    = "DenyNonTLS"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowS3InventoryAndAnalytics"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectAcl",
    ]

    resources = [
      "${aws_s3_bucket.this.arn}/_AWSBucketAnalytics/*",
      "${aws_s3_bucket.this.arn}/_AWSBucketInventory/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

resource "aws_s3_bucket" "log_target" {
  bucket        = local.log_bucket_name
  force_destroy = var.force_destroy

  tags = merge(var.tags, { Name = local.log_bucket_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "log_target" {
  bucket = aws_s3_bucket.log_target.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "log_target" {
  bucket = aws_s3_bucket.log_target.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

resource "aws_s3_bucket_versioning" "log_target" {
  bucket = aws_s3_bucket.log_target.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "log_bucket_policy" {
  statement {
    sid    = "AllowS3LoggingDelivery"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logging.s3.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.log_target.arn}/*"]
  }
}

resource "aws_s3_bucket_policy" "log_target" {
  bucket = aws_s3_bucket.log_target.id
  policy = data.aws_iam_policy_document.log_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.log_target]
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_bucket != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

output "bucket_id" {
  value = aws_s3_bucket.this.id
}

output "bucket_arn" {
  value = aws_s3_bucket.this.arn
}

output "bucket_name" {
  value = local.bucket_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

############################################################################
# Data sources (static / well-known provider metadata only)
############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

############################################################################
# Core bucket configuration
############################################################################

variable "bucket_name" {
  description = "Name of the S3 bucket. Mutually exclusive with bucket_name_prefix."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || length(var.bucket_name) <= 63
    error_message = "The S3 bucket name must be 63 characters or less."
  }
}

variable "bucket_name_prefix" {
  description = "Prefix used to generate a unique S3 bucket name. Mutually exclusive with bucket_name."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name_prefix == null || length(var.bucket_name_prefix) <= 37
    error_message = "The S3 bucket name prefix must be 37 characters or less."
  }
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket when the bucket is destroyed."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition     = contains(["BucketOwnerEnforced", "ObjectWriter", "BucketOwnerPreferred"], var.object_ownership)
    error_message = "object_ownership must be one of BucketOwnerEnforced, ObjectWriter or BucketOwnerPreferred."
  }
}

variable "bucket_acl" {
  description = "Canned ACL applied to the bucket when object ownership is ObjectWriter."
  type        = string
  default     = "private"

  validation {
    condition = contains([
      "private",
      "public-read",
      "public-read-write",
      "authenticated-read",
      "aws-exec-read",
      "bucket-owner-read",
      "bucket-owner-full-control",
      "log-delivery-write",
    ], var.bucket_acl)
    error_message = "bucket_acl must be a valid S3 canned ACL."
  }
}

############################################################################
# Public access block
############################################################################

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for this bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for this bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for this bucket."
  type        = bool
  default     = true
}

############################################################################
# Encryption
############################################################################

variable "sse_algorithm" {
  description = "Server-side encryption algorithm used when no KMS key is supplied."
  type        = string
  default     = "AES256"

  validation {
    condition     = contains(["AES256", "aws:kms", "aws:kms:dsse"], var.sse_algorithm)
    error_message = "sse_algorithm must be one of AES256, aws:kms or aws:kms:dsse."
  }
}

variable "kms_key_arn" {
  description = "ARN of an existing KMS key used for SSE-KMS. When set, the SSE algorithm is switched to aws:kms."
  type        = string
  default     = null
}

variable "create_kms_key" {
  description = "Whether a KMS key should be created and used when no kms_key_arn is provided."
  type        = bool
  default     = false
}

variable "kms_key_deletion_window_in_days" {
  description = "Duration in days before the KMS key is deleted after destruction."
  type        = number
  default     = 30
}

variable "bucket_key_enabled" {
  description = "Whether S3 bucket keys should be enabled (only meaningful with SSE-KMS)."
  type        = bool
  default     = false
}

############################################################################
# Versioning / notifications / logging / object lock
############################################################################

variable "versioning_enabled" {
  description = "Whether bucket versioning is enabled. When false the status is Suspended."
  type        = bool
  default     = false
}

variable "eventbridge_enabled" {
  description = "Whether EventBridge notifications are enabled for the bucket."
  type        = bool
  default     = false
}

variable "logging_enabled" {
  description = "Whether S3 server access logging is enabled for the bucket."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Name of the bucket that receives the server access logs."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix applied to the delivered server access log objects."
  type        = string
  default     = "logs/"
}

variable "logging_source_bucket_arns" {
  description = "ARNs of source buckets allowed to deliver logs into this bucket."
  type        = list(string)
  default     = []
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled on the bucket (must be set at creation time)."
  type        = bool
  default     = false
}

variable "object_lock_configuration" {
  description = "Default retention rule applied to objects when Object Lock is enabled."
  type = object({
    mode  = optional(string, "GOVERNANCE")
    days  = optional(number, null)
    years = optional(number, null)
  })
  default = {
    mode  = "GOVERNANCE"
    days  = 30
    years = null
  }

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_configuration.mode)
    error_message = "The object lock retention mode must be either GOVERNANCE or COMPLIANCE."
  }
}

############################################################################
# Bucket policy
############################################################################

variable "custom_bucket_policy" {
  description = "Optional user supplied bucket policy JSON merged with the enforced policies."
  type        = string
  default     = null

  validation {
    condition     = var.custom_bucket_policy == null || can(jsondecode(var.custom_bucket_policy))
    error_message = "custom_bucket_policy must be valid JSON."
  }
}

variable "attach_elb_log_delivery_policy" {
  description = "Whether a policy statement allowing ELB access log delivery is attached to the bucket."
  type        = bool
  default     = false
}

variable "elb_log_delivery_principal_arns" {
  description = "ARNs of the AWS ELB log delivery accounts allowed to write access logs to the bucket."
  type        = list(string)
  default     = []
}

############################################################################
# CORS / inventory / replication / lifecycle
############################################################################

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string, null)
    allowed_headers = optional(list(string), [])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number, null)
  }))
  default = []
}

variable "inventory_configurations" {
  description = "List of S3 inventory configurations for the bucket."
  type = list(object({
    name                     = string
    enabled                  = optional(bool, true)
    included_object_versions = optional(string, "All")
    schedule_frequency       = string
    optional_fields          = optional(list(string), [])
    destination = object({
      bucket_arn = string
      prefix     = optional(string, null)
      account_id = optional(string, null)
      format     = optional(string, "Parquet")
      encryption = optional(object({
        sse_kms_key_id = optional(string, null)
        sse_s3         = optional(bool, false)
      }), null)
    })
  }))
  default = []

  validation {
    condition = alltrue([
      for cfg in var.inventory_configurations :
      contains(["All", "Current"], cfg.included_object_versions)
    ])
    error_message = "included_object_versions must be either All or Current."
  }

  validation {
    condition = alltrue([
      for cfg in var.inventory_configurations :
      contains(["CSV", "ORC", "Parquet"], cfg.destination.format)
    ])
    error_message = "The inventory destination format must be one of CSV, ORC or Parquet."
  }
}

variable "replication_configurations" {
  description = "List of cross-region replication rules applied to the bucket."
  type = list(object({
    id       = string
    priority = optional(number, null)
    status   = optional(string, "Enabled")
    filter = optional(object({
      prefix = optional(string, null)
      tags   = optional(map(string), {})
    }), null)
    delete_marker_replication_status = optional(string, null)
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects    = optional(object({ enabled = bool }), null)
      replica_modifications_status = optional(string, null)
    }), null)
    destination = object({
      bucket             = string
      account            = optional(string, null)
      storage_class      = optional(string, "STANDARD")
      replica_kms_key_id = optional(string, null)
      metrics = optional(object({
        status                  = optional(string, "Enabled")
        event_threshold_minutes = optional(number, null)
      }), null)
      replication_time = optional(object({
        status  = optional(string, "Enabled")
        minutes = optional(number, 15)
      }), null)
    })
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle rules applied to the bucket."
  type = list(object({
    id     = string
    status = optional(string, "Enabled")
    prefix = optional(string, null)
    filter = optional(object({
      prefix                   = optional(string, null)
      object_size_greater_than = optional(number, null)
      object_size_less_than    = optional(number, null)
      tags                     = optional(map(string), {})
    }), null)
    expiration = optional(object({
      days                         = optional(number, null)
      date                         = optional(string, null)
      expired_object_delete_marker = optional(bool, null)
    }), null)
    transitions = optional(list(object({
      days          = optional(number, null)
      date          = optional(string, null)
      storage_class = string
    })), [])
    noncurrent_version_expiration = optional(object({
      noncurrent_days           = optional(number, null)
      newer_noncurrent_versions = optional(number, null)
    }), null)
    noncurrent_version_transitions = optional(list(object({
      noncurrent_days           = optional(number, null)
      storage_class             = string
      newer_noncurrent_versions = optional(number, null)
    })), [])
    abort_incomplete_multipart_upload = optional(object({
      days_after_initiation = optional(number, null)
    }), null)
  }))
  default = []
}

############################################################################
# Locals
############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  effective_kms_key_arn = (
    var.kms_key_arn != null
    ? var.kms_key_arn
    : (var.create_kms_key ? aws_kms_key.this[0].arn : null)
  )

  sse_algorithm      = local.effective_kms_key_arn != null ? "aws:kms" : var.sse_algorithm
  bucket_key_enabled = local.effective_kms_key_arn != null ? true : var.bucket_key_enabled

  object_lock_days  = var.object_lock_configuration.years != null ? null : var.object_lock_configuration.days
  object_lock_years = var.object_lock_configuration.years

  replication_destination_bucket_arns = distinct([
    for rule in var.replication_configurations :
    can(regex("^arn:", rule.destination.bucket))
    ? rule.destination.bucket
    : "arn:${local.partition}:s3:::${rule.destination.bucket}"
  ])

  lifecycle_rules = {
    for rule in var.lifecycle_rules : rule.id => rule
  }

  inventory_configurations = {
    for config in var.inventory_configurations : config.name => config
  }
}

############################################################################
# KMS key used for SSE-KMS (only created when requested)
############################################################################

resource "aws_kms_key" "this" {
  count = var.create_kms_key ? 1 : 0

  description             = "KMS key used to encrypt the S3 bucket"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "kms" {
  count = var.create_kms_key ? 1 : 0

  statement {
    sid    = "EnableAccountKeyAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "kms:CancelKeyDeletion",
      "kms:CreateGrant",
      "kms:DescribeKey",
      "kms:DisableKey",
      "kms:DisableKeyRotation",
      "kms:EnableKey",
      "kms:EnableKeyRotation",
      "kms:GetKeyPolicy",
      "kms:GetKeyRotationStatus",
      "kms:ListGrants",
      "kms:ListKeyPolicies",
      "kms:ListResourceTags",
      "kms:PutKeyPolicy",
      "kms:RetireGrant",
      "kms:RevokeGrant",
      "kms:ScheduleKeyDeletion",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:UpdateKeyDescription",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ServiceUsage"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "aws:ViaAWSService"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key_policy" "this" {
  count = var.create_kms_key ? 1 : 0

  key_id = aws_kms_key.this[0].id
  policy = data.aws_iam_policy_document.kms[0].json
}

############################################################################
# S3 bucket and bucket level configuration
############################################################################

resource "aws_s3_bucket" "this" {
  bucket              = var.bucket_name
  bucket_prefix       = var.bucket_name_prefix
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_enabled

  tags = var.tags

  lifecycle {
    precondition {
      condition     = !(var.bucket_name != null && var.bucket_name_prefix != null)
      error_message = "Only one of bucket_name or bucket_name_prefix may be specified."
    }

    precondition {
      condition     = !(var.object_lock_enabled && var.logging_enabled)
      error_message = "S3 Object Lock cannot be combined with server access logging."
    }

    precondition {
      condition     = !(var.object_lock_enabled && !var.versioning_enabled)
      error_message = "S3 Object Lock requires bucket versioning to be enabled."
    }

    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.bucket_acl

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = local.effective_kms_key_arn
    }

    bucket_key_enabled = local.bucket_key_enabled
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

############################################################################
# Bucket policy: custom policy + enforced TLS + logging permissions
############################################################################

data "aws_iam_policy_document" "bucket" {
  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []

  statement {
    sid    = "EnforceTLSRequestsOnly"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid     = "AllowS3ServerAccessLogDelivery"
      effect  = "Allow"
      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/*"]

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [local.account_id]
      }
    }
  }

  dynamic "statement" {
    for_each = (var.attach_elb_log_delivery_policy && length(var.elb_log_delivery_principal_arns) > 0) ? [1] : []

    content {
      sid     = "AllowELBAccessLogDelivery"
      effect  = "Allow"
      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/AWSLogs/*"]

      principals {
        type        = "AWS"
        identifiers = var.elb_log_delivery_principal_arns
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket.json

  depends_on = [
    aws_s3_bucket_public_access_block.this,
    aws_s3_bucket_ownership_controls.this,
  ]
}

############################################################################
# Event notifications
############################################################################

resource "aws_s3_bucket_notification" "this" {
  bucket      = aws_s3_bucket.this.id
  eventbridge = var.eventbridge_enabled
}

############################################################################
# Server access logging
############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = var.logging_enabled ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = var.logging_target_bucket != null
      error_message = "logging_target_bucket must be provided when logging_enabled is true."
    }

    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Server access logging cannot be combined with S3 Object Lock."
    }
  }
}

############################################################################
# Object Lock configuration
############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = local.object_lock_days
      years = local.object_lock_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = !var.logging_enabled
      error_message = "S3 Object Lock cannot be combined with server access logging."
    }
  }
}

############################################################################
# Cross-region replication (IAM role + configuration)
############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_iam_role" "replication" {
  name_prefix        = "s3-replication-"
  description        = "IAM role assumed by S3 to replicate objects"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = var.tags
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "ReplicationSourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetBucketVersioning",
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:PutBucketVersioning",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "ReplicationSourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  dynamic "statement" {
    for_each = length(local.replication_destination_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "ReplicationDestinationBucketPermissions"
      effect = "Allow"

      actions = [
        "s3:ObjectOwnerOverrideToBucketOwner",
        "s3:ReplicateDelete",
        "s3:ReplicateObject",
        "s3:ReplicateTags",
      ]

      resources = concat(
        local.replication_destination_bucket_arns,
        [for arn in local.replication_destination_bucket_arns : "${arn}/*"],
      )
    }
  }

  dynamic "statement" {
    for_each = local.effective_kms_key_arn != null ? [local.effective_kms_key_arn] : []

    content {
      sid    = "ReplicationKmsPermissions"
      effect = "Allow"

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:Encrypt",
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyWithoutPlaintext",
        "kms:ReEncryptFrom",
        "kms:ReEncryptTo",
      ]

      resources = [statement.value]
    }
  }
}

resource "aws_iam_role_policy" "replication" {
  name_prefix = "s3-replication-"
  role        = aws_iam_role.replication.id
  policy      = data.aws_iam_policy_document.replication.json
}

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_configurations) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication.arn

  dynamic "rule" {
    for_each = { for index, rule in var.replication_configurations : tostring(index) => rule }

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []

        content {
          prefix = filter.value.prefix

          dynamic "tag" {
            for_each = filter.value.tags != null ? filter.value.tags : {}

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication_status != null ? [rule.value.delete_marker_replication_status] : []

        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []

            content {
              status = sse_kms_encrypted_objects.value.enabled ? "Enabled" : "Disabled"
            }
          }

          dynamic "replica_modifications" {
            for_each = source_selection_criteria.value.replica_modifications_status != null ? [source_selection_criteria.value.replica_modifications_status] : []

            content {
              status = replica_modifications.value
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        account       = rule.value.destination.account
        storage_class = rule.value.destination.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.destination.replica_kms_key_id != null ? [rule.value.destination.replica_kms_key_id] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "metrics" {
          for_each = rule.value.destination.metrics != null ? [rule.value.destination.metrics] : []

          content {
            status = metrics.value.status

            dynamic "event_threshold" {
              for_each = metrics.value.event_threshold_minutes != null ? [metrics.value.event_threshold_minutes] : []

              content {
                minutes = event_threshold.value
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = rule.value.destination.replication_time != null ? [rule.value.destination.replication_time] : []

          content {
            status = replication_time.value.status

            dynamic "time" {
              for_each = replication_time.value.minutes != null ? [replication_time.value.minutes] : []

              content {
                minutes = time.value
              }
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "S3 replication requires bucket versioning to be enabled."
    }
  }
}

############################################################################
# Inventory configurations
############################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = local.inventory_configurations

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  enabled                  = each.value.enabled
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.schedule_frequency
  }

  destination {
    bucket {
      format     = each.value.destination.format
      bucket_arn = each.value.destination.bucket_arn
      prefix     = each.value.destination.prefix
      account_id = each.value.destination.account_id

      dynamic "encryption" {
        for_each = each.value.destination.encryption != null ? [each.value.destination.encryption] : []

        content {
          dynamic "sse_kms" {
            for_each = encryption.value.sse_kms_key_id != null ? [encryption.value.sse_kms_key_id] : []

            content {
              key_id = sse_kms.value
            }
          }

          dynamic "sse_s3" {
            for_each = encryption.value.sse_s3 ? [1] : []

            content {}
          }
        }
      }
    }
  }
}

############################################################################
# CORS configuration
############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }
}

############################################################################
# Lifecycle configuration
############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = local.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.status
      prefix = rule.value.prefix

      dynamic "filter" {
        for_each = rule.value.filter != null ? [rule.value.filter] : []

        content {
          prefix                   = try(filter.value.prefix, null)
          object_size_greater_than = try(filter.value.object_size_greater_than, null)
          object_size_less_than    = try(filter.value.object_size_less_than, null)

          dynamic "tag" {
            for_each = try(filter.value.tags, {})

            content {
              key   = tag.key
              value = tag.value
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days                         = expiration.value.days
          date                         = expiration.value.date
          expired_object_delete_marker = expiration.value.expired_object_delete_marker
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          date          = transition.value.date
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = noncurrent_version_expiration.value.noncurrent_days
          newer_noncurrent_versions = noncurrent_version_expiration.value.newer_noncurrent_versions
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days           = noncurrent_version_transition.value.noncurrent_days
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = noncurrent_version_transition.value.newer_noncurrent_versions
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload != null ? [rule.value.abort_incomplete_multipart_upload] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value.days_after_initiation
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Account-wide security baseline and IAM governance
#
# NOTE: This file intentionally contains no `provider` block and no
# `terraform { backend { ... } }` block — both are injected/managed by the
# deployment harness. A `required_version` / `required_providers` block IS
# declared (Terraform safely merges these across files).
###############################################################################

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "group_name_prefix" {
  description = "Prefix used to name the developer and admin IAM groups."
  type        = string
  default     = "app"
}

variable "allowed_s3_region" {
  description = "The single AWS region in which principals are allowed to create new S3 buckets."
  type        = string
  default     = "us-east-1"
}

###############################################################################
# Data sources (static / provider metadata lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  partition = data.aws_partition.current.partition

  developer_group_name = "${var.group_name_prefix}_developer"
  admin_group_name     = "${var.group_name_prefix}_admin"

  terraform_state_bucket_name = "${var.group_name_prefix}-terraform-state-${data.aws_caller_identity.current.account_id}"

  caller_user_arn  = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:user/&{aws:username}"
  mfa_device_arn   = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:mfa/*"
  root_account_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  developer_managed_policy_names = toset([
    "IAMReadOnlyAccess",
    "IAMUserChangePassword",
    "IAMUserSSHKeys",
  ])

  # NOTE: aws_iam_group and aws_iam_service_linked_role do NOT expose a `tags`
  # argument in the AWS provider, so local.tags is applied only to resource
  # types that support tagging (aws_iam_policy, aws_iam_role, aws_s3_bucket,
  # aws_kms_key).
  tags = {
    Project   = "account-security-baseline"
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Account password policy
###############################################################################

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
  hard_expiry                    = false
}

###############################################################################
# Account-level S3 public access block
###############################################################################

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Customer managed KMS key for the remote-state bucket
###############################################################################

resource "aws_kms_key" "terraform_state" {
  description             = "Customer managed key used to encrypt the Terraform remote-state S3 bucket."
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(local.tags, {
    Name = "${var.group_name_prefix}-terraform-state"
  })
}

resource "aws_kms_alias" "terraform_state" {
  name          = "alias/${var.group_name_prefix}-terraform-state"
  target_key_id = aws_kms_key.terraform_state.key_id
}

###############################################################################
# Remote-state bucket and service-linked roles
###############################################################################

resource "aws_s3_bucket" "terraform_state" {
  bucket = local.terraform_state_bucket_name

  tags = merge(local.tags, {
    Name = local.terraform_state_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraform_state.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_public_access_block" "terraform_state" {
  bucket = aws_s3_bucket.terraform_state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# Service-linked roles referenced by the developer MFA policy.
# NOTE: service-linked roles do not support tags in the AWS provider.
resource "aws_iam_service_linked_role" "ec2" {
  aws_service_name = "ec2.amazonaws.com"
  description      = "Service-linked role used by Amazon EC2."
}

resource "aws_iam_service_linked_role" "autoscaling" {
  aws_service_name = "autoscaling.amazonaws.com"
  description      = "Service-linked role used by EC2 Auto Scaling."
}

###############################################################################
# IAM groups
###############################################################################

resource "aws_iam_group" "developer" {
  name = local.developer_group_name
  path = "/"
}

resource "aws_iam_group" "admin" {
  name = local.admin_group_name
  path = "/"
}

###############################################################################
# Developer group: AWS managed policy attachments
###############################################################################

resource "aws_iam_group_policy_attachment" "developer_managed" {
  for_each = local.developer_managed_policy_names

  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/${each.value}"
}

###############################################################################
# Developer group: self-management of personal access keys
###############################################################################

data "aws_iam_policy_document" "developer_self_manage_access_keys" {
  statement {
    sid    = "ManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:GetAccessKeyLastUsed",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]

    resources = [local.caller_user_arn]
  }
}

resource "aws_iam_policy" "developer_self_manage_access_keys" {
  name        = "${var.group_name_prefix}_developer_self_manage_access_keys"
  description = "Allows members to manage their own IAM access keys."
  policy      = data.aws_iam_policy_document.developer_self_manage_access_keys.json
  tags        = local.tags
}

resource "aws_iam_group_policy_attachment" "developer_self_manage_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_manage_access_keys.arn
}

###############################################################################
# Developer group: virtual MFA device self-management (MFA required to deactivate)
###############################################################################

data "aws_iam_policy_document" "developer_manage_mfa_devices" {
  statement {
    sid    = "ManageOwnVirtualMFADevice"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ListVirtualMFADevices",
      "iam:ResyncMFADevice",
    ]

    resources = [
      local.mfa_device_arn,
      local.caller_user_arn,
    ]
  }

  statement {
    sid    = "DenyMFADeviceChangesWithoutMFA"
    effect = "Deny"

    actions = [
      "iam:DeactivateMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      local.mfa_device_arn,
      local.caller_user_arn,
    ]

    condition {
      test     = "BoolIfExists"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["false"]
    }
  }
}

resource "aws_iam_policy" "developer_manage_mfa_devices" {
  name        = "${var.group_name_prefix}_developer_manage_mfa_devices"
  description = "Allows members to manage their own virtual MFA devices; MFA is required to deactivate a device."
  policy      = data.aws_iam_policy_document.developer_manage_mfa_devices.json
  tags        = local.tags
}

resource "aws_iam_group_policy_attachment" "developer_manage_mfa_devices" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_manage_mfa_devices.arn
}

###############################################################################
# Developer group: MFA-gated S3 access
###############################################################################

data "aws_iam_policy_document" "developer_s3_mfa" {
  statement {
    sid       = "AllowS3OnlyWithMFA"
    effect    = "Allow"
    actions   = ["s3:*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid       = "DenyBucketCreationOutsideAllowedRegion"
    effect    = "Deny"
    actions   = ["s3:CreateBucket"]
    resources = ["*"]

    condition {
      test     = "StringNotEquals"
      variable = "aws:RequestedRegion"
      values   = [var.allowed_s3_region]
    }
  }

  statement {
    sid       = "DenyAccessToTerraformStateBucket"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [
      aws_s3_bucket.terraform_state.arn,
      "${aws_s3_bucket.terraform_state.arn}/*",
    ]
  }
}

resource "aws_iam_policy" "developer_s3_mfa" {
  name        = "${var.group_name_prefix}_developer_s3_mfa"
  description = "MFA-gated S3 access, restricted bucket creation region and denied access to the remote-state bucket."
  policy      = data.aws_iam_policy_document.developer_s3_mfa.json
  tags        = local.tags
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

###############################################################################
# Developer group: MFA-gated compute, load balancing, monitoring and scaling
###############################################################################

data "aws_iam_policy_document" "developer_compute_mfa" {
  statement {
    sid    = "AllowComputeServicesOnlyWithMFA"
    effect = "Allow"

    actions = [
      "ec2:*",
      "elasticloadbalancing:*",
      "cloudwatch:*",
      "autoscaling:*",
    ]

    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowPassingServiceLinkedRolesOnlyWithMFA"
    effect = "Allow"

    actions = ["iam:PassRole"]

    resources = [
      aws_iam_service_linked_role.ec2.arn,
      aws_iam_service_linked_role.autoscaling.arn,
    ]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "developer_compute_mfa" {
  name        = "${var.group_name_prefix}_developer_compute_mfa"
  description = "MFA-gated access to EC2, ELB, CloudWatch, Auto Scaling and their service-linked roles."
  policy      = data.aws_iam_policy_document.developer_compute_mfa.json
  tags        = local.tags
}

resource "aws_iam_group_policy_attachment" "developer_compute_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_compute_mfa.arn
}

###############################################################################
# Administrative access: role assumable by the account root principal
###############################################################################

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid     = "AllowAccountRootToAssumeAdminRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.root_account_arn]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "admin"
  description          = "Administrative role assumable by the account root principal with MFA."
  max_session_duration = 3600
  assume_role_policy   = data.aws_iam_policy_document.admin_assume_role.json
  tags                 = local.tags
}

###############################################################################
# Administrative access: full administrative policy conditioned on MFA
###############################################################################

data "aws_iam_policy_document" "admin_full_access" {
  statement {
    sid       = "FullAdministrativeAccessOnlyWithMFA"
    effect    = "Allow"
    actions   = ["*"]
    resources = ["*"]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_full_access" {
  name        = "${var.group_name_prefix}_admin_full_access"
  description = "Full administrative access, granted only when MFA is present."
  policy      = data.aws_iam_policy_document.admin_full_access.json
  tags        = local.tags
}

resource "aws_iam_role_policy_attachment" "admin_full_access" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access.arn
}

###############################################################################
# Admin group: assume the admin role when MFA is present
###############################################################################

data "aws_iam_policy_document" "admin_group_assume_admin_role" {
  statement {
    sid       = "AssumeAdminRoleOnlyWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "admin_group_assume_admin_role" {
  name        = "${var.group_name_prefix}_admin_assume_admin_role"
  description = "Allows admin group members to assume the administrative role when MFA is present."
  policy      = data.aws_iam_policy_document.admin_group_assume_admin_role.json
  tags        = local.tags
}

resource "aws_iam_group_policy_attachment" "admin_group_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_admin_role.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
  }
}

################################################################################
# Variables
################################################################################

variable "config" {
  description = "Path to the YAML file that drives the CI/CD pipeline orchestration framework. If the file does not exist, an embedded default configuration is used."
  type        = string
  default     = "config.yml"
}

variable "create_default_pipeline_role" {
  description = "Whether to create the shared default CodePipeline service role under the /terraforest/ path."
  type        = bool
  default     = true
}

variable "name_prefix" {
  description = "Name prefix applied to every resource created by this stack."
  type        = string
  default     = "terraforest"
}

variable "environment" {
  description = "Environment name merged into the shared common tags."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional tags merged into local.common_tags for every taggable resource."
  type        = map(string)
  default     = {}
}

################################################################################
# Account / region metadata (static provider lookups only)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Locals - the YAML configuration file is decoded exactly once
################################################################################

locals {
  # Embedded, minimal, account-agnostic default configuration. Used whenever the
  # file referenced by var.config is not present on disk, so that the stack can
  # always be planned and applied unattended.
  default_config_yaml = <<-EOT
    connections: {}
    pipelines: {}
    triggers: {}
  EOT

  config = fileexists(var.config) ? yamldecode(file(var.config)) : yamldecode(local.default_config_yaml)

  name_prefix = var.name_prefix
  account_id  = data.aws_caller_identity.current.account_id
  region      = data.aws_region.current.name
  partition   = data.aws_partition.current.partition

  common_tags = merge(
    {
      Project     = local.name_prefix
      ManagedBy   = "terraform"
      Environment = var.environment
    },
    var.tags,
  )

  # ---------------------------------------------------------------------------
  # CodeStar connections
  # ---------------------------------------------------------------------------
  connection_provider_types = ["Bitbucket", "GitHub", "GitHub Enterprise Server"]

  connections = {
    for k, v in try(local.config.connections, {}) : k => v
    if contains(local.connection_provider_types, try(v.provider_type, ""))
  }

  github_enterprise_connections = {
    for k, v in local.connections : k => v
    if try(v.provider_type, "") == "GitHub Enterprise Server"
  }

  connection_arns = {
    for k, v in aws_codestarconnections_connection.this : k => v.arn
  }

  # ---------------------------------------------------------------------------
  # Pipelines -> stages -> actions
  #
  # Built as a flattened list of self-describing objects (each carrying its own
  # literal "key" attribute) and then collapsed into a single map with ONE
  # top-level object for-expression. An object for-expression may not be the
  # direct value of another object for-expression, hence flatten(...) first.
  # ---------------------------------------------------------------------------
  pipelines = try(local.config.pipelines, {})

  base_actions = {
    for a in flatten([
      for p_name, p in try(local.pipelines, {}) : [
        for s_idx, s in try(p.stages, []) : [
          for a_idx, act in try(s.actions, []) : {
            key              = format("%s/%d/%d", p_name, s_idx, a_idx)
            pipeline         = p_name
            stage_index      = s_idx
            action_index     = a_idx
            name             = try(act.name, "action-${a_idx}")
            category         = try(act.category, "Build")
            owner            = try(act.owner, "AWS")
            provider         = try(act.provider, "CodeBuild")
            version          = tostring(try(act.version, 1))
            run_order        = try(act.run_order, null)
            role_arn         = try(act.role_arn, null)
            input_artifacts  = try(tolist(try(act.input_artifacts, [])), [])
            output_artifacts = try(tolist(try(act.output_artifacts, [])), [])
            configuration    = try(act.configuration, {})

            connection      = try(act.connection, null)
            repository_name = try(act.repository_name, null)
            branch_name     = try(act.branch_name, try(act.branch, null))
            ecr_repository  = try(act.ecr_repository, null)
            image_tag       = try(act.image_tag, null)
            s3_bucket       = try(act.s3_bucket, null)
            s3_object_key   = try(act.s3_object_key, null)
            user_parameters = try(act.user_parameters, null)
            custom_data     = try(act.custom_data, null)

            project_name  = try(act.project_name, null)
            function_name = try(act.function_name, null)
            runtime       = try(act.runtime, null)
            handler       = try(act.handler, null)
            buildspec     = try(act.buildspec, "buildspec.yml")
          }
        ]
      ]
    ]) : a.key => a
  }

  # ---------------------------------------------------------------------------
  # CodeBuild actions
  # ---------------------------------------------------------------------------
  codebuild_actions = {
    for k, a in local.base_actions : k => merge(a, {
      project_name = substr(
        coalesce(try(a.project_name, null), format("%s-%s", local.name_prefix, replace(k, "/", "-"))),
        0,
        255,
      )
    })
    if a.category == "Build" && a.provider == "CodeBuild"
  }

  # ---------------------------------------------------------------------------
  # Manual approval actions
  # ---------------------------------------------------------------------------
  approval_actions = {
    for k, a in local.base_actions : k => a
    if a.category == "Approval"
  }

  approval_topic_arns = {
    for k, v in aws_sns_topic.approval : k => v.arn
  }

  # ---------------------------------------------------------------------------
  # Lambda invoke actions (inline, self-contained function source so the stack
  # remains deployable inside a greenfield account with no external artifacts)
  # ---------------------------------------------------------------------------
  lambda_sources = {
    "python3.12" = { file = "index.py", handler = "index.handler", content = "def handler(event, context):\n    return event\n" }
    "python3.11" = { file = "index.py", handler = "index.handler", content = "def handler(event, context):\n    return event\n" }
    "nodejs22.x" = { file = "index.js", handler = "index.handler", content = "exports.handler = async (event) => event;\n" }
    "nodejs20.x" = { file = "index.js", handler = "index.handler", content = "exports.handler = async (event) => event;\n" }
    "ruby3.3"    = { file = "index.rb", handler = "index.handler", content = "def handler(event:, context:)\n  event\nend\n" }
    "java21"     = { file = "Handler.java", handler = "com.terraforest.Handler::handleRequest", content = "package com.terraforest;\n\npublic class Handler {\n    public Object handleRequest(Object event, Object context) {\n        return event;\n    }\n}\n" }
    "dotnet8"    = { file = "Function.cs", handler = "Terraforest::Terraforest.Function::Handler", content = "public class Function\n{\n    public object Handler(object input, object context) => input;\n}\n" }
  }

  lambda_actions_raw = {
    for k, a in local.base_actions : k => a
    if a.category == "Invoke" && a.provider == "Lambda"
  }

  lambda_runtimes = {
    for k, a in local.lambda_actions_raw :
    k => contains(keys(local.lambda_sources), coalesce(a.runtime, "")) ? a.runtime : "python3.12"
  }

  lambda_actions = {
    for k, a in local.lambda_actions_raw : k => merge(a, {
      function_name = substr(
        coalesce(try(a.function_name, null), format("%s-%s", local.name_prefix, replace(k, "/", "-"))),
        0,
        64,
      )
      runtime        = local.lambda_runtimes[k]
      handler        = coalesce(try(a.handler, null), local.lambda_sources[local.lambda_runtimes[k]].handler)
      source_file    = local.lambda_sources[local.lambda_runtimes[k]].file
      source_content = local.lambda_sources[local.lambda_runtimes[k]].content
    })
  }

  # ---------------------------------------------------------------------------
  # Normalised action definitions consumed by aws_codepipeline
  # ---------------------------------------------------------------------------
  pipeline_actions = {
    for k, a in local.base_actions : k => {
      name             = a.name
      category         = a.category
      owner            = a.owner
      provider         = a.provider
      version          = a.version
      run_order        = a.run_order
      role_arn         = a.role_arn
      input_artifacts  = a.input_artifacts
      output_artifacts = a.output_artifacts

      configuration = merge(
        a.configuration,
        a.provider == "CodeStarSourceConnection" ? {
          ConnectionArn        = lookup(local.connection_arns, coalesce(a.connection, ""), "")
          FullRepositoryId     = coalesce(a.repository_name, "")
          BranchName           = coalesce(a.branch_name, "main")
          OutputArtifactFormat = "CODE_ZIP"
        } : {},
        a.provider == "CodeCommit" ? {
          RepositoryName       = coalesce(a.repository_name, "")
          BranchName           = coalesce(a.branch_name, "main")
          PollForSourceChanges = "false"
        } : {},
        a.provider == "S3" ? {
          S3Bucket             = coalesce(a.s3_bucket, aws_s3_bucket.artifacts.bucket)
          S3ObjectKey          = coalesce(a.s3_object_key, "")
          PollForSourceChanges = "false"
        } : {},
        a.provider == "ECR" ? {
          RepositoryName = coalesce(a.ecr_repository, coalesce(a.repository_name, ""))
          ImageTag       = coalesce(a.image_tag, "latest")
        } : {},
        a.provider == "CodeBuild" ? {
          ProjectName = try(local.codebuild_actions[k].project_name, "")
        } : {},
        a.provider == "Lambda" ? {
          FunctionName   = try(local.lambda_actions[k].function_name, "")
          UserParameters = coalesce(a.user_parameters, "")
        } : {},
        a.category == "Approval" ? {
          CustomData      = coalesce(a.custom_data, "")
          NotificationArn = lookup(local.approval_topic_arns, k, "")
        } : {}
      )
    }
  }

  # ---------------------------------------------------------------------------
  # Triggers - one EventBridge rule per configured trigger type
  # ---------------------------------------------------------------------------
  triggers = {
    for k, v in try(local.config.triggers, {}) : k => v
    if contains(keys(local.pipelines), k)
  }

  codecommit_branch_triggers = merge([
    for p, t in local.triggers : {
      for i, e in try(t.codecommit_branch_changes, []) :
      format("%s/codecommit-branch/%d", p, i) => {
        pipeline    = p
        rule_name   = format("terrabits-%s-codecommit-branch-%d", p, i)
        description = try(e.description, "Start pipeline ${p} on CodeCommit branch changes")
        state       = "ENABLED"
        event_pattern = jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = [format("arn:%s:codecommit:%s:%s:%s", local.partition, local.region, local.account_id, e.repository_name)]
          detail = merge(
            {
              event         = try(e.events, ["referenceCreated", "referenceUpdated"])
              referenceType = ["branch"]
            },
            try(e.branch_name, null) != null ? { referenceName = [e.branch_name] } : {}
          )
        })
      }
    }
  ]...)

  codecommit_tag_triggers = merge([
    for p, t in local.triggers : {
      for i, e in try(t.codecommit_tag_changes, []) :
      format("%s/codecommit-tag/%d", p, i) => {
        pipeline    = p
        rule_name   = format("terrabits-%s-codecommit-tag-%d", p, i)
        description = try(e.description, "Start pipeline ${p} on CodeCommit tag changes")
        state       = "ENABLED"
        event_pattern = jsonencode({
          source      = ["aws.codecommit"]
          detail-type = ["CodeCommit Repository State Change"]
          resources   = [format("arn:%s:codecommit:%s:%s:%s", local.partition, local.region, local.account_id, e.repository_name)]
          detail = merge(
            {
              event         = try(e.events, ["referenceCreated", "referenceUpdated"])
              referenceType = ["tag"]
            },
            try(e.tag_names, null) != null ? { referenceName = e.tag_names } : {}
          )
        })
      }
    }
  ]...)

  schedule_triggers = merge([
    for p, t in local.triggers : {
      for i, e in try(t.schedules, []) :
      format("%s/schedule/%d", p, i) => {
        pipeline            = p
        rule_name           = format("terrabits-%s-schedule-%d", p, i)
        description         = try(e.description, "Scheduled start of pipeline ${p}")
        state               = try(e.state, "ENABLED")
        schedule_expression = e.expression
      }
    }
  ]...)

  pattern_triggers = merge([
    for p, t in local.triggers : {
      for i, e in try(t.event_patterns, []) :
      format("%s/pattern/%d", p, i) => {
        pipeline      = p
        rule_name     = format("terrabits-%s-pattern-%d", p, i)
        description   = try(e.description, "Custom EventBridge pattern trigger for pipeline ${p}")
        state         = "ENABLED"
        event_pattern = try(tostring(e.pattern), null) != null ? tostring(e.pattern) : jsonencode(e.pattern)
      }
    }
  ]...)

  trigger_rules = merge(
    local.codecommit_branch_triggers,
    local.codecommit_tag_triggers,
    local.schedule_triggers,
    local.pattern_triggers,
  )

  # ---------------------------------------------------------------------------
  # Least privilege ARN collections used by the default pipeline role
  # ---------------------------------------------------------------------------
  codecommit_repository_arns = [
    for n in distinct([
      for k, a in local.base_actions : a.repository_name
      if a.provider == "CodeCommit" && a.repository_name != null
    ]) :
    format("arn:%s:codecommit:%s:%s:%s", local.partition, local.region, local.account_id, n)
  ]

  ecr_repository_arns = [
    for n in distinct([
      for k, a in local.base_actions : coalesce(a.ecr_repository, a.repository_name)
      if a.provider == "ECR" && coalesce(a.ecr_repository, a.repository_name) != null
    ]) :
    format("arn:%s:ecr:%s:%s:repository/%s", local.partition, local.region, local.account_id, n)
  ]

  codebuild_project_arns = [for k, v in aws_codebuild_project.action : v.arn]

  codestar_connection_arns = [for k, v in aws_codestarconnections_connection.this : v.arn]

  approval_topic_arns_list = [for k, v in aws_sns_topic.approval : v.arn]

  codepipeline_role_arn = one(aws_iam_role.codepipeline_default[*].arn)

  # Principals granted direct use of the S3 CMK (least privilege: key ARN only)
  kms_principal_role_arns = compact(concat(
    [local.codepipeline_role_arn],
    [for k, v in aws_iam_role.codebuild : v.arn],
    [for k, v in aws_iam_role.lambda : v.arn],
  ))
}

################################################################################
# CodePipeline artifact bucket
################################################################################

resource "aws_s3_bucket" "artifacts" {
  bucket = "${local.name_prefix}-artifacts-${local.account_id}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "artifacts" {
  bucket = aws_s3_bucket.artifacts.id

  versioning_configuration {
    status = "Enabled"
  }
}

################################################################################
# CodeBuild cache bucket
################################################################################

resource "aws_s3_bucket" "build_cache" {
  bucket = "${local.name_prefix}-build-cache-${local.account_id}"

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this.arn
    }
  }
}

resource "aws_s3_bucket_versioning" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "build_cache" {
  bucket = aws_s3_bucket.build_cache.id

  rule {
    id     = "expire-build-cache"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }

    expiration {
      days = 30
    }
  }
}

################################################################################
# Customer managed KMS key for S3 artifact / build cache encryption
################################################################################

resource "aws_kms_key" "this" {
  description             = "${local.name_prefix} CodePipeline artifacts and CodeBuild cache encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid       = "EnableRootAccountAccess"
          Effect    = "Allow"
          Principal = { AWS = "arn:${local.partition}:iam::${local.account_id}:root" }
          Action    = "kms:*"
          Resource  = "*"
        },
      ],
      length(local.kms_principal_role_arns) > 0 ? [
        {
          Sid       = "AllowPipelineBuildLambdaRolesUseKey"
          Effect    = "Allow"
          Principal = { AWS = local.kms_principal_role_arns }
          Action = [
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:DescribeKey",
            "kms:ReEncryptFrom",
            "kms:ReEncryptTo",
          ]
          Resource = "*"
        },
      ] : []
    )
  })

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.name_prefix}-artifacts-cache"
  target_key_id = aws_kms_key.this.key_id
}

################################################################################
# CodeStar connections (Bitbucket / GitHub / GitHub Enterprise Server)
################################################################################

resource "aws_codestarconnections_host" "this" {
  for_each = local.github_enterprise_connections

  name              = try(each.value.host_name, "${local.name_prefix}-${each.key}")
  provider_type     = "GitHubEnterpriseServer"
  provider_endpoint = each.value.provider_endpoint

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_codestarconnections_connection" "this" {
  for_each = local.connections

  name          = try(each.value.name, each.key)
  provider_type = try(each.value.provider_type, "") == "GitHub Enterprise Server" ? "GitHubEnterpriseServer" : each.value.provider_type
  host_arn      = contains(keys(local.github_enterprise_connections), each.key) ? aws_codestarconnections_host.this[each.key].arn : null

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

################################################################################
# Default CodePipeline service role (path /terraforest/)
################################################################################

resource "aws_iam_role" "codepipeline_default" {
  count = var.create_default_pipeline_role ? 1 : 0

  name = "${local.name_prefix}-codepipeline-default"
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CodePipelineAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "codepipeline.amazonaws.com" }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codepipeline_default" {
  count = var.create_default_pipeline_role ? 1 : 0

  name = "${local.name_prefix}-codepipeline-default-policy"
  role = aws_iam_role.codepipeline_default[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = concat(
      [
        {
          Sid    = "ArtifactBucketAccess"
          Effect = "Allow"
          Action = [
            "s3:GetObject",
            "s3:GetObjectVersion",
            "s3:PutObject",
            "s3:DeleteObject",
            "s3:ListBucket",
            "s3:GetBucketLocation",
          ]
          Resource = [
            aws_s3_bucket.artifacts.arn,
            "${aws_s3_bucket.artifacts.arn}/*",
          ]
        },
        {
          Sid    = "ArtifactBucketKmsAccess"
          Effect = "Allow"
          Action = [
            "kms:Decrypt",
            "kms:GenerateDataKey",
            "kms:DescribeKey",
          ]
          Resource = aws_kms_key.this.arn
        },
      ],
      length(local.codecommit_repository_arns) > 0 ? [
        {
          Sid    = "CodeCommitSourceAccess"
          Effect = "Allow"
          Action = [
            "codecommit:GetBranch",
            "codecommit:GetCommit",
            "codecommit:GitPull",
            "codecommit:UploadArchive",
            "codecommit:BatchGetRepositories",
          ]
          Resource = local.codecommit_repository_arns
        },
      ] : [],
      length(local.codebuild_project_arns) > 0 ? [
        {
          Sid    = "CodeBuildActionAccess"
          Effect = "Allow"
          Action = [
            "codebuild:BatchGetBuilds",
            "codebuild:StartBuild",
          ]
          Resource = local.codebuild_project_arns
        },
      ] : [],
      length(local.ecr_repository_arns) > 0 ? [
        {
          Sid    = "EcrSourceAccess"
          Effect = "Allow"
          Action = [
            "ecr:GetAuthorizationToken",
            "ecr:BatchCheckLayerAvailability",
            "ecr:GetDownloadUrlForLayer",
            "ecr:BatchGetImage",
          ]
          Resource = local.ecr_repository_arns
        },
      ] : [],
      length(local.codestar_connection_arns) > 0 ? [
        {
          Sid      = "CodeStarConnectionAccess"
          Effect   = "Allow"
          Action   = "codestar-connections:UseConnection"
          Resource = local.codestar_connection_arns
        },
      ] : [],
      length(local.approval_topic_arns_list) > 0 ? [
        {
          Sid      = "ApprovalNotificationAccess"
          Effect   = "Allow"
          Action   = "sns:Publish"
          Resource = local.approval_topic_arns_list
        },
      ] : []
    )
  })
}

################################################################################
# CodeBuild projects instantiated from the YAML action definitions
################################################################################

resource "aws_iam_role" "codebuild" {
  for_each = local.codebuild_actions

  name = substr("${each.value.project_name}-service-role", 0, 64)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "CodeBuildAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "codebuild.amazonaws.com" }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "codebuild" {
  for_each = local.codebuild_actions

  name = "codebuild-base-policy"
  role = aws_iam_role.codebuild[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ArtifactsAndCacheAccess"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:GetObjectVersion",
          "s3:PutObject",
          "s3:GetBucketLocation",
          "s3:ListBucket",
        ]
        Resource = [
          aws_s3_bucket.artifacts.arn,
          "${aws_s3_bucket.artifacts.arn}/*",
          aws_s3_bucket.build_cache.arn,
          "${aws_s3_bucket.build_cache.arn}/*",
        ]
      },
      {
        Sid    = "KmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.this.arn
      },
      {
        Sid    = "LogGroupAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          format("arn:%s:logs:%s:%s:log-group:/aws/codebuild/*", local.partition, local.region, local.account_id),
          format("arn:%s:logs:%s:%s:log-group:/aws/codebuild/*:*", local.partition, local.region, local.account_id),
        ]
      },
    ]
  })
}

resource "aws_codebuild_project" "action" {
  for_each = local.codebuild_actions

  name          = each.value.project_name
  description   = try(each.value.description, "CodeBuild project for pipeline ${each.value.pipeline}")
  service_role  = aws_iam_role.codebuild[each.key].arn
  build_timeout = try(each.value.build_timeout, 60)

  artifacts {
    type = "CODEPIPELINE"
  }

  cache {
    type     = "S3"
    location = aws_s3_bucket.build_cache.bucket
  }

  environment {
    compute_type                = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
    image                       = try(each.value.image, "aws/codebuild/amazonlinux2-x86_64-standard:4.0")
    type                        = try(each.value.environment_type, "LINUX_CONTAINER")
    image_pull_credentials_type = try(each.value.image_pull_credentials_type, "CODEBUILD")
    privileged_mode             = try(each.value.privileged_mode, false)

    dynamic "environment_variable" {
      for_each = try(each.value.environment_variables, [])

      content {
        name  = environment_variable.value.name
        value = environment_variable.value.value
        type  = try(environment_variable.value.type, "PLAINTEXT")
      }
    }
  }

  source {
    type      = "CODEPIPELINE"
    buildspec = each.value.buildspec
  }

  tags = local.common_tags
}

################################################################################
# Lambda invoke actions instantiated from the YAML action definitions
################################################################################

data "archive_file" "lambda" {
  for_each = local.lambda_actions

  type        = "zip"
  output_path = "${path.module}/.terraform/archives/${replace(each.key, "/", "-")}.zip"

  source {
    content  = each.value.source_content
    filename = each.value.source_file
  }
}

resource "aws_iam_role" "lambda" {
  for_each = local.lambda_actions

  name = substr("${each.value.function_name}-service-role", 0, 64)

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "LambdaAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "lambda.amazonaws.com" }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "lambda" {
  for_each = local.lambda_actions

  name = "lambda-base-policy"
  role = aws_iam_role.lambda[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "LogGroupAccess"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
        ]
        Resource = [
          format("arn:%s:logs:%s:%s:log-group:/aws/lambda/%s", local.partition, local.region, local.account_id, each.value.function_name),
          format("arn:%s:logs:%s:%s:log-group:/aws/lambda/%s:*", local.partition, local.region, local.account_id, each.value.function_name),
        ]
      },
      {
        Sid    = "ArtifactBucketKmsAccess"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey",
        ]
        Resource = aws_kms_key.this.arn
      },
    ]
  })
}

resource "aws_lambda_function" "action" {
  for_each = local.lambda_actions

  function_name    = each.value.function_name
  role             = aws_iam_role.lambda[each.key].arn
  runtime          = each.value.runtime
  handler          = each.value.handler
  filename         = data.archive_file.lambda[each.key].output_path
  source_code_hash = data.archive_file.lambda[each.key].output_base64sha256
  timeout          = try(each.value.timeout, 60)
  memory_size      = try(each.value.memory_size, 128)

  tags = local.common_tags
}

resource "aws_lambda_permission" "action" {
  for_each = local.lambda_actions

  statement_id  = "AllowExecutionFromCodePipeline"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.action[each.key].function_name
  principal     = "codepipeline.amazonaws.com"
  source_arn    = format("arn:%s:codepipeline:%s:%s:%s", local.partition, local.region, local.account_id, each.value.pipeline)
}

################################################################################
# Manual approval SNS topics
################################################################################

resource "aws_sns_topic" "approval" {
  for_each = local.approval_actions

  name = substr("${local.name_prefix}-approval-${replace(each.key, "/", "-")}", 0, 256)

  tags = local.common_tags
}

resource "aws_sns_topic_policy" "approval" {
  for_each = local.approval_actions

  arn = aws_sns_topic.approval[each.key].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCodePipelinePublish"
        Effect    = "Allow"
        Principal = { Service = "codepipeline.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.approval[each.key].arn
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })
}

################################################################################
# CodePipelines (dynamic stages and actions)
################################################################################

resource "aws_codepipeline" "pipeline" {
  for_each = local.pipelines

  name     = each.key
  role_arn = try(each.value.role_arn, null) != null ? each.value.role_arn : local.codepipeline_role_arn

  artifact_store {
    location = aws_s3_bucket.artifacts.bucket
    type     = "S3"
  }

  dynamic "stage" {
    for_each = try(each.value.stages, [])

    content {
      name = try(stage.value.name, "stage-${stage.key}")

      dynamic "action" {
        for_each = [
          for a_idx, a in try(stage.value.actions, []) :
          local.pipeline_actions[format("%s/%d/%d", each.key, stage.key, a_idx)]
        ]

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          run_order        = action.value.run_order
          role_arn         = action.value.role_arn
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          configuration    = action.value.configuration
        }
      }
    }
  }

  tags = local.common_tags
}

################################################################################
# EventBridge trigger roles ("terrabits-<pipeline>")
################################################################################

resource "aws_iam_role" "eventbridge_trigger" {
  for_each = local.triggers

  name = "terrabits-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EventBridgeAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "events.amazonaws.com" }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy" "eventbridge_trigger" {
  for_each = local.triggers

  name = "terrabits-${each.key}-start-pipeline"
  role = aws_iam_role.eventbridge_trigger[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "StartOwnPipelineOnly"
        Effect   = "Allow"
        Action   = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.pipeline[each.key].arn
      }
    ]
  })
}

################################################################################
# EventBridge rules and targets
################################################################################

resource "aws_cloudwatch_event_rule" "pipeline" {
  for_each = local.trigger_rules

  name                = each.value.rule_name
  description         = each.value.description
  state               = each.value.state
  event_bus_name      = "default"
  schedule_expression = try(each.value.schedule_expression, null)
  event_pattern       = try(each.value.event_pattern, null)

  tags = local.common_tags
}

resource "aws_cloudwatch_event_target" "pipeline" {
  for_each = local.trigger_rules

  rule           = aws_cloudwatch_event_rule.pipeline[each.key].name
  event_bus_name = "default"
  target_id      = "terrabits-${each.value.pipeline}"
  arn            = aws_codepipeline.pipeline[each.value.pipeline].arn
  role_arn       = aws_iam_role.eventbridge_trigger[each.value.pipeline].arn
}

################################################################################
# Outputs
################################################################################

output "artifact_bucket_name" {
  description = "Name of the S3 bucket holding CodePipeline artifacts."
  value       = aws_s3_bucket.artifacts.bucket
}

output "build_cache_bucket_name" {
  description = "Name of the S3 bucket holding CodeBuild build cache objects."
  value       = aws_s3_bucket.build_cache.bucket
}

output "artifacts_kms_key_arn" {
  description = "ARN of the customer managed KMS key used for S3 artifact and build cache encryption."
  value       = aws_kms_key.this.arn
}

output "artifacts_kms_key_alias" {
  description = "Alias of the customer managed KMS key used for S3 artifact and build cache encryption."
  value       = aws_kms_alias.this.name
}

output "codepipeline_default_role_arn" {
  description = "ARN of the shared default CodePipeline role created under the /terraforest/ path."
  value       = local.codepipeline_role_arn
}

output "codestar_connection_arns" {
  description = "ARNs of the created CodeStar connections. NOTE: every new connection starts in PENDING status. The authorization handshake must be completed manually in the AWS console (Developer Tools > Connections > Update pending connection) before the connection can be used by any pipeline."
  value       = local.connection_arns
}

output "codestar_connection_handshake_status" {
  description = "Reminder map: each CodeStar connection below requires a manual console handshake while its status is PENDING."
  value = {
    for k, v in aws_codestarconnections_connection.this : k => "PENDING - complete the authorization handshake manually in the AWS console before use"
  }
}

output "codestar_host_arns" {
  description = "ARNs of the GitHub Enterprise Server hosts backing the GitHub Enterprise Server connections."
  value       = { for k, v in aws_codestarconnections_host.this : k => v.arn }
}

output "pipeline_names" {
  description = "Names of the CodePipelines created from the YAML configuration."
  value       = { for k, v in aws_codepipeline.pipeline : k => v.name }
}

output "pipeline_arns" {
  description = "ARNs of the CodePipelines created from the YAML configuration."
  value       = { for k, v in aws_codepipeline.pipeline : k => v.arn }
}

output "codebuild_project_names" {
  description = "Names of the CodeBuild projects instantiated for Build actions."
  value       = { for k, v in aws_codebuild_project.action : k => v.name }
}

output "lambda_function_names" {
  description = "Names of the Lambda functions instantiated for Invoke actions."
  value       = { for k, v in aws_lambda_function.action : k => v.function_name }
}

output "eventbridge_trigger_role_arns" {
  description = "ARNs of the terrabits-<pipeline> EventBridge trigger roles."
  value       = { for k, v in aws_iam_role.eventbridge_trigger : k => v.arn }
}

output "eventbridge_rule_names" {
  description = "Names of the EventBridge rules created for the configured pipeline triggers."
  value       = { for k, v in aws_cloudwatch_event_rule.pipeline : k => v.name }
}

output "approval_topic_arns" {
  description = "ARNs of the SNS topics attached to manual approval actions."
  value       = local.approval_topic_arns
}

terraform {
  required_version = ">= 1.9.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Static provider metadata (safe, non-inventory data sources only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Greenfield VPC - the module always has a real VPC to attach to
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "security-group-module-vpc" })
}

###############################################################################
# Variables - every variable carries a default so `terraform apply` is
# fully non-interactive for both the new and existing security-group paths.
###############################################################################

variable "vpc_id" {
  description = "Optional caller-supplied VPC ID used by the existing-security-group path. When empty the module falls back to the VPC it creates."
  type        = string
  default     = ""

  validation {
    condition     = var.vpc_id == "" || can(regex("^vpc-[0-9a-f]+$", var.vpc_id))
    error_message = "vpc_id must be empty or a valid VPC identifier beginning with \"vpc-\"."
  }
}

variable "create_security_group_module" {
  description = "Master toggle for the module. When false, no security group, rule, or prefix list resources are created."
  type        = bool
  default     = true
}

variable "create_new_security_group" {
  description = "When true a brand new security group is created. When false, rules are attached to existing_security_group_id instead."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to manage rules on. Required when create_new_security_group is false; never hardcoded."
  type        = string
  default     = ""

  validation {
    condition     = var.create_new_security_group || !var.create_security_group_module || length(var.existing_security_group_id) > 0
    error_message = "existing_security_group_id must be supplied when create_new_security_group is false and the module is enabled."
  }

  validation {
    condition     = var.existing_security_group_id == "" || can(regex("^sg-[0-9a-f]+$", var.existing_security_group_id))
    error_message = "existing_security_group_id must be empty or a valid security group identifier beginning with \"sg-\"."
  }
}

variable "security_group_name" {
  description = "Explicit name for the newly created security group. When empty, security_group_name_prefix is used instead."
  type        = string
  default     = ""
}

variable "security_group_name_prefix" {
  description = "Name prefix used when security_group_name is empty. Must NOT begin with \"sg-\", which AWS reserves for its own generated security group identifiers; the reserved-token collision causes the create call to be rejected. Preferred with create_before_destroy replacements because the provider appends a unique suffix."
  type        = string
  default     = "terraform-sg-"
}

variable "security_group_description" {
  description = "Description applied to the newly created security group."
  type        = string
  default     = "Managed by Terraform"
}

# NOTE: The new security group always uses `create_before_destroy = true`.
# Terraform resolves `lifecycle` meta-arguments at graph-construction time, so
# they cannot reference variables/locals. `create_before_destroy` is therefore
# intentionally a fixed literal rather than a caller-configurable variable.

variable "revoke_rules_on_delete" {
  description = "Value for the new security group's revoke_rules_on_delete setting (a provider-level resource argument, not a lifecycle meta-argument)."
  type        = bool
  default     = false
}

variable "ingress_rules_new" {
  description = "Ingress rules applied inline to the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id (use \"self\" to reference the created group), or prefix_list_id."
  type = list(object({
    description                  = optional(string, "")
    from_port                    = number
    to_port                      = number
    protocol                     = string
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules_new :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : s
        if s != null
      ]) == 1
    ])
    error_message = "Each ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.ingress_rules_new :
      (r.cidr_ipv4 == null ? true : can(cidrhost(r.cidr_ipv4, 0))) &&
      (r.cidr_ipv6 == null ? true : can(cidrhost(r.cidr_ipv6, 0)))
    ])
    error_message = "cidr_ipv4 and cidr_ipv6, when set, must contain valid CIDR notation."
  }
}

variable "egress_rules_new" {
  description = "Egress rules applied inline to the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id (use \"self\" to reference the created group), or prefix_list_id. The shipped default is restricted to the module's own VPC CIDR (10.0.0.0/16) so the group keeps outbound reachability without opening unrestricted internet egress. Callers who genuinely require unrestricted internet egress must explicitly opt in by supplying cidr_ipv4 = \"0.0.0.0/0\" in their root module."
  type = list(object({
    description                  = optional(string, "")
    from_port                    = number
    to_port                      = number
    protocol                     = string
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = [
    {
      description = "Allow outbound within VPC"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_ipv4   = "10.0.0.0/16"
    }
  ]

  validation {
    condition = alltrue([
      for r in var.egress_rules_new :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : s
        if s != null
      ]) == 1
    ])
    error_message = "Each egress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.egress_rules_new :
      (r.cidr_ipv4 == null ? true : can(cidrhost(r.cidr_ipv4, 0))) &&
      (r.cidr_ipv6 == null ? true : can(cidrhost(r.cidr_ipv6, 0)))
    ])
    error_message = "cidr_ipv4 and cidr_ipv6, when set, must contain valid CIDR notation."
  }
}

variable "ingress_rules_existing" {
  description = "Ingress rules attached to the existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id (use \"self\" to reference the target group), or prefix_list_id."
  type = list(object({
    description                  = optional(string, "")
    from_port                    = number
    to_port                      = number
    protocol                     = string
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for r in var.ingress_rules_existing :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : s
        if s != null
      ]) == 1
    ])
    error_message = "Each ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.ingress_rules_existing :
      (r.cidr_ipv4 == null ? true : can(cidrhost(r.cidr_ipv4, 0))) &&
      (r.cidr_ipv6 == null ? true : can(cidrhost(r.cidr_ipv6, 0)))
    ])
    error_message = "cidr_ipv4 and cidr_ipv6, when set, must contain valid CIDR notation."
  }
}

variable "egress_rules_existing" {
  description = "Egress rules attached to the existing security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id (use \"self\" to reference the target group), or prefix_list_id. The shipped default is restricted to 10.0.0.0/16 so the target group keeps in-VPC outbound reachability without opening unrestricted internet egress. Callers who genuinely require unrestricted internet egress must explicitly opt in by supplying cidr_ipv4 = \"0.0.0.0/0\" in their root module."
  type = list(object({
    description                  = optional(string, "")
    from_port                    = number
    to_port                      = number
    protocol                     = string
    cidr_ipv4                    = optional(string)
    cidr_ipv6                    = optional(string)
    referenced_security_group_id = optional(string)
    prefix_list_id               = optional(string)
  }))
  default = [
    {
      description = "Allow outbound within VPC"
      from_port   = 0
      to_port     = 0
      protocol    = "-1"
      cidr_ipv4   = "10.0.0.0/16"
    }
  ]

  validation {
    condition = alltrue([
      for r in var.egress_rules_existing :
      length([
        for s in [r.cidr_ipv4, r.cidr_ipv6, r.referenced_security_group_id, r.prefix_list_id] : s
        if s != null
      ]) == 1
    ])
    error_message = "Each egress rule must set exactly one of cidr_ipv4, cidr_ipv6, referenced_security_group_id, or prefix_list_id."
  }

  validation {
    condition = alltrue([
      for r in var.egress_rules_existing :
      (r.cidr_ipv4 == null ? true : can(cidrhost(r.cidr_ipv4, 0))) &&
      (r.cidr_ipv6 == null ? true : can(cidrhost(r.cidr_ipv6, 0)))
    ])
    error_message = "cidr_ipv4 and cidr_ipv6, when set, must contain valid CIDR notation."
  }
}

variable "create_prefix_list" {
  description = "When true (and no existing prefix list IDs are supplied) a customer-managed EC2 prefix list is created."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name for the created managed prefix list. Falls back to a sensible default when empty."
  type        = string
  default     = ""
}

variable "prefix_list_address_family" {
  description = "Address family of the created managed prefix list."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either \"IPv4\" or \"IPv6\"."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries allowed on the created managed prefix list."
  type        = number
  default     = 5

  validation {
    condition     = var.prefix_list_max_entries > 0
    error_message = "prefix_list_max_entries must be greater than zero."
  }
}

variable "prefix_list_cidrs" {
  description = "CIDR entries to populate on the created managed prefix list."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for c in var.prefix_list_cidrs : can(cidrhost(c, 0))])
    error_message = "Every entry in prefix_list_cidrs must be a valid CIDR block."
  }
}

variable "existing_prefix_list_ids" {
  description = "Existing managed prefix list IDs. When non-empty, prefix list creation is skipped."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags merged into the common tag set applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = merge(
    {
      ManagedBy = "terraform"
      Module    = "aws-security-group"
    },
    var.tags,
  )

  vpc_id = coalesce(var.vpc_id, aws_vpc.main.id)

  security_group_name = var.security_group_name != "" ? var.security_group_name : "security-group"

  prefix_list_resolved_name = var.prefix_list_name != "" ? var.prefix_list_name : "managed-prefix-list"
}

###############################################################################
# New security group (inline rules)
###############################################################################

resource "aws_security_group" "this" {
  count = var.create_security_group_module && var.create_new_security_group ? 1 : 0

  name        = var.security_group_name != "" ? var.security_group_name : null
  name_prefix = var.security_group_name != "" ? null : var.security_group_name_prefix
  description = var.security_group_description
  vpc_id      = local.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  dynamic "ingress" {
    for_each = var.ingress_rules_new
    content {
      description      = ingress.value.description
      from_port        = ingress.value.from_port
      to_port          = ingress.value.to_port
      protocol         = ingress.value.protocol
      cidr_blocks      = ingress.value.cidr_ipv4 != null ? [ingress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = ingress.value.cidr_ipv6 != null ? [ingress.value.cidr_ipv6] : null
      prefix_list_ids  = ingress.value.prefix_list_id != null ? [ingress.value.prefix_list_id] : null
      security_groups  = ingress.value.referenced_security_group_id != null && ingress.value.referenced_security_group_id != "self" ? [ingress.value.referenced_security_group_id] : null
      self             = ingress.value.referenced_security_group_id == "self"
    }
  }

  dynamic "egress" {
    for_each = var.egress_rules_new
    content {
      description      = egress.value.description
      from_port        = egress.value.from_port
      to_port          = egress.value.to_port
      protocol         = egress.value.protocol
      cidr_blocks      = egress.value.cidr_ipv4 != null ? [egress.value.cidr_ipv4] : null
      ipv6_cidr_blocks = egress.value.cidr_ipv6 != null ? [egress.value.cidr_ipv6] : null
      prefix_list_ids  = egress.value.prefix_list_id != null ? [egress.value.prefix_list_id] : null
      security_groups  = egress.value.referenced_security_group_id != null && egress.value.referenced_security_group_id != "self" ? [egress.value.referenced_security_group_id] : null
      self             = egress.value.referenced_security_group_id == "self"
    }
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.common_tags, { Name = local.security_group_name })
}

###############################################################################
# Existing security group rule path (for_each only - never mixed with count)
###############################################################################

resource "aws_security_group_rule" "ingress_existing" {
  for_each = var.create_security_group_module && !var.create_new_security_group ? {
    for i, r in var.ingress_rules_existing : "ingress-${i}" => r
  } : {}

  type              = "ingress"
  security_group_id = var.existing_security_group_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  source_security_group_id = each.value.referenced_security_group_id == "self" ? var.existing_security_group_id : each.value.referenced_security_group_id
}

resource "aws_security_group_rule" "egress_existing" {
  for_each = var.create_security_group_module && !var.create_new_security_group ? {
    for i, r in var.egress_rules_existing : "egress-${i}" => r
  } : {}

  type              = "egress"
  security_group_id = var.existing_security_group_id
  description       = each.value.description
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  protocol          = each.value.protocol

  cidr_blocks              = each.value.cidr_ipv4 != null ? [each.value.cidr_ipv4] : null
  ipv6_cidr_blocks         = each.value.cidr_ipv6 != null ? [each.value.cidr_ipv6] : null
  prefix_list_ids          = each.value.prefix_list_id != null ? [each.value.prefix_list_id] : null
  source_security_group_id = each.value.referenced_security_group_id == "self" ? var.existing_security_group_id : each.value.referenced_security_group_id
}

###############################################################################
# Optional customer-managed EC2 prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.create_security_group_module && var.create_prefix_list && length(var.existing_prefix_list_ids) == 0 ? 1 : 0

  name           = local.prefix_list_resolved_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, cidr in var.prefix_list_cidrs : tostring(idx) => cidr }
    content {
      cidr        = entry.value
      description = "Managed prefix list entry ${entry.key}"
    }
  }

  tags = merge(local.common_tags, { Name = local.prefix_list_resolved_name })
}

###############################################################################
# Outputs - valid for both the new and existing security-group paths
###############################################################################

output "security_group_id" {
  description = "ID of the newly created security group, or the supplied existing security group ID."
  value       = var.create_new_security_group ? try(aws_security_group.this[0].id, null) : var.existing_security_group_id
}

output "security_group_arn" {
  description = "ARN of the newly created security group, or a derived ARN for the supplied existing security group."
  value = var.create_new_security_group ? try(aws_security_group.this[0].arn, null) : (
    var.existing_security_group_id != "" ? "arn:${data.aws_partition.current.partition}:ec2:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:security-group/${var.existing_security_group_id}" : null
  )
}

output "security_group_name" {
  description = "Name of the newly created security group, or the supplied existing security group ID for the existing path."
  value       = var.create_new_security_group ? try(aws_security_group.this[0].name, null) : var.existing_security_group_id
}

output "managed_prefix_list_id" {
  description = "ID of the created managed prefix list, or the first supplied existing prefix list ID."
  value       = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : try(var.existing_prefix_list_ids[0], null)
}

output "vpc_id" {
  description = "Effective VPC ID targeted by the module (caller-supplied or module-created)."
  value       = local.vpc_id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "environment" {
  description = "Deployment environment name applied to every resource tag."
  type        = string
  default     = "dev"
}

variable "table_name_prefix" {
  description = "Optional prefix prepended to every DynamoDB table name. Defaults to an empty string so table names match the application schema."
  type        = string
  default     = ""
}

locals {
  ssm_prefix_files_invitations = "/file-service/dynamodb/invitations/"
  ssm_prefix_files             = "/file-service/dynamodb/files/"
  ssm_prefix_hashes            = "/hashes-service/dynamodb/hashes/"
  ssm_prefix_storage           = "/file-service/dynamodb/storage/"
  ssm_prefix_wallets           = "/wallet-service/dynamodb/wallets/"
}

resource "aws_dynamodb_table" "near_app_actions_mapping" {
