    Name        = "${var.table_name_prefix}near-app-actions-mapping"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_dynamodb_table" "near_app_actions_master" {
  name         = "${var.table_name_prefix}near-app-actions-master"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "actionId"

  attribute {
    name = "actionId"
