    type = "S"
  }

  attribute {
    name = "pk1"
    type = "S"
  }

  attribute {
    name = "sk1"
    type = "S"
  }

  global_secondary_index {
    name            = "GSI1"
    hash_key        = "pk1"
    range_key       = "sk1"
    projection_type = "ALL"
  }

  ttl {
    attribute_name = "ttl"
    enabled        = true
  }

  tags = {
    Name        = "${var.table_name_prefix}near-storage"
    Environment = var.environment
  }

  lifecycle {
    prevent_destroy = true
  }
}

