terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "name" {
  description = "Name of the Transfer Family server. When empty, a random two-word pet name is generated."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Endpoint type of the Transfer Family server: PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of \"PUBLIC\", \"VPC\" or \"VPC_ENDPOINT\"."
  }
}

variable "protocols" {
  description = "Protocols enabled on the Transfer Family server."
  type        = list(string)
  default     = ["SFTP"]

  validation {
    condition     = length(var.protocols) > 0 && alltrue([for p in var.protocols : contains(["SFTP", "FTPS", "FTP", "AS2"], p)])
    error_message = "protocols must contain one or more of \"SFTP\", \"FTPS\", \"FTP\" or \"AS2\"."
  }
}

variable "security_policy_name" {
  description = "Transfer Family security policy name."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ACM certificate ARN. When set, FTPS is enabled for the server."
  type        = string
  default     = null
}

variable "host_key" {
  description = "RSA private key used for the server host key."
  type        = string
  default     = null
  sensitive   = true
}

variable "logging_role_arn" {
  description = "Existing IAM role ARN used for Transfer Family logging. When empty a dedicated role is created."
  type        = string
  default     = ""
}

variable "structured_log_destinations" {
  description = "ARNs of CloudWatch log groups that receive structured Transfer Family logs."
  type        = list(string)
  default     = []
}

variable "protocol_details" {
  description = "Optional protocol details (map). Supported keys: as2_transports, passive_ip, set_stat_option, tls_session_resumption_mode."
  type        = any
  default     = null
}

variable "identity_provider_type" {
  description = "Identity provider used to authenticate users: SERVICE_MANAGED or API_GATEWAY."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of \"SERVICE_MANAGED\" or \"API_GATEWAY\"."
  }
}

variable "api_gateway_url" {
  description = "API Gateway URL used when identity_provider_type is API_GATEWAY."
  type        = string
  default     = ""
}

variable "subdomain" {
  description = "DNS label prefixing the Route 53 CNAME record."
  type        = string
  default     = "sftp"

  validation {
    condition     = can(regex("^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$", var.subdomain))
    error_message = "subdomain must be a valid lower case DNS label (1-63 characters, alphanumeric or hyphen, no leading/trailing hyphen)."
  }
}

variable "domain_name" {
  description = "Public DNS domain used for the optional Route 53 CNAME record (e.g. example.com)."
  type        = string
  default     = ""
}

variable "hosted_zone_id" {
  description = "Existing Route 53 hosted zone ID. When empty a new hosted zone for var.domain_name is created."
  type        = string
  default     = ""
}

variable "sftp_users" {
  description = "Map of SFTP users keyed by user name."
  type = map(object({
    bucket_name           = optional(string, null)
    home_directory_prefix = optional(string, "")
    home_directory_type   = optional(string, "LOGICAL")
  }))
  default = {}

  validation {
    condition     = alltrue([for u in var.sftp_users : contains(["LOGICAL", "PATH"], u.home_directory_type)])
    error_message = "home_directory_type must be either \"LOGICAL\" or \"PATH\"."
  }
}

variable "user_public_keys" {
  description = "Map of user name to a list of SSH public keys for that user."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Tags applied to every taggable resource created by this configuration."
  type        = map(string)
  default     = {}
}

variable "vpc_id" {
  description = "Existing VPC ID used for VPC / VPC_ENDPOINT endpoints. When empty a dedicated VPC is created."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Existing subnet IDs used for VPC / VPC_ENDPOINT endpoints. When empty dedicated public subnets are created."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Existing security group IDs for the VPC endpoint. When empty a dedicated security group is created."
  type        = list(string)
  default     = []
}

variable "vpc_cidr" {
  description = "CIDR block of the VPC created for VPC / VPC_ENDPOINT endpoints."
  type        = string
  default     = "10.0.0.0/16"
}

variable "sftp_ingress_cidr_blocks" {
  description = "CIDR blocks allowed to reach the SFTP endpoint on port 22."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "log_retention_in_days" {
  description = "Retention of the CloudWatch log group used for Transfer Family logs."
  type        = number
  default     = 90
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_prefix_list" "s3" {
  name = "com.amazonaws.${data.aws_region.current.name}.s3"
}

###############################################################################
# Random server name
###############################################################################

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

###############################################################################
# Locals
###############################################################################

locals {
  server_name = var.name != "" ? var.name : random_pet.this.id

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  tags = merge(var.tags, { Name = local.server_name })

  # ---------------------------------------------------------------------------
  # Transfer Family logging
  # ---------------------------------------------------------------------------
  logging_role_arn = var.logging_role_arn != "" ? var.logging_role_arn : try(aws_iam_role.transfer_logging[0].arn, null)

  # ---------------------------------------------------------------------------
  # API Gateway identity provider
  # ---------------------------------------------------------------------------
  api_gateway_enabled    = var.identity_provider_type == "API_GATEWAY" && var.api_gateway_url != ""
  identity_provider_type = local.api_gateway_enabled ? "API_GATEWAY" : "SERVICE_MANAGED"

  # ---------------------------------------------------------------------------
  # Networking
  # ---------------------------------------------------------------------------
  is_vpc_endpoint_type = contains(["VPC", "VPC_ENDPOINT"], var.endpoint_type)

  create_network        = local.is_vpc_endpoint_type && var.vpc_id == "" && length(var.subnet_ids) == 0
  create_security_group = local.is_vpc_endpoint_type && length(var.security_group_ids) == 0

  vpc_id             = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.main[0].id, null)
  subnet_ids         = length(var.subnet_ids) > 0 ? var.subnet_ids : aws_subnet.public[*].id
  security_group_ids = length(var.security_group_ids) > 0 ? var.security_group_ids : aws_security_group.transfer[*].id

  # Service name of the EC2 Interface VPC endpoint that fronts the Transfer
  # Family service in this partition/region.
  transfer_vpc_endpoint_service_name = "com.amazonaws.${local.region}.transfer.server"

  # ---------------------------------------------------------------------------
  # DNS
  # ---------------------------------------------------------------------------
  create_route53_zone   = var.hosted_zone_id == "" && var.domain_name != ""
  zone_id               = var.hosted_zone_id != "" ? var.hosted_zone_id : try(aws_route53_zone.this[0].zone_id, null)
  create_route53_record = var.domain_name != "" && (var.hosted_zone_id != "" || local.create_route53_zone)

  # ---------------------------------------------------------------------------
  # Protocol details
  # ---------------------------------------------------------------------------
  protocol_details = var.protocol_details == null ? {} : var.protocol_details

  # ---------------------------------------------------------------------------
  # SFTP users
  # ---------------------------------------------------------------------------
  user_prefix = {
    for user_name, user in var.sftp_users :
    user_name => trim(user.home_directory_prefix == null ? "" : user.home_directory_prefix, "/")
  }

  user_bucket_name = {
    for user_name, user in var.sftp_users :
    user_name => (user.bucket_name == null || user.bucket_name == "") ? "${local.server_name}-${user_name}" : user.bucket_name
  }

  # ---------------------------------------------------------------------------
  # SSH public keys flattened into a map keyed by "<user>-<index>"
  # ---------------------------------------------------------------------------
  user_keys_flat = flatten([
    for user_name, keys in var.user_public_keys : [
      for index, key in keys : {
        id   = "${user_name}-${index}"
        user = user_name
        key  = key
      }
    ] if contains(keys(var.sftp_users), user_name)
  ])

  user_keys = { for item in local.user_keys_flat : item.id => item }
}

###############################################################################
# Transfer Family logging role
###############################################################################

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  name = "${local.server_name}-transfer-logging"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "TransferAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "transfer.amazonaws.com" }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

###############################################################################
# CloudWatch log group for the Transfer Family server
###############################################################################

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = var.log_retention_in_days
  tags              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# API Gateway authorization role (AWS Transfer invokes API Gateway)
###############################################################################

resource "aws_iam_role" "api_gateway" {
  count = local.api_gateway_enabled ? 1 : 0

  name = "${local.server_name}-transfer-apigw"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "TransferAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "transfer.amazonaws.com" }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "api_gateway" {
  count = local.api_gateway_enabled ? 1 : 0

  name = "${local.server_name}-transfer-apigw-logs"
  role = aws_iam_role.api_gateway[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CloudWatchLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.transfer.arn,
          "${aws_cloudwatch_log_group.transfer.arn}:log-stream:*"
        ]
      }
    ]
  })
}

###############################################################################
# Networking for VPC / VPC_ENDPOINT endpoints
###############################################################################

resource "aws_vpc" "main" {
  count = local.create_network ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${local.server_name}-vpc" })
}

resource "aws_subnet" "public" {
  count = local.create_network ? 2 : 0

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = true

  tags = merge(local.tags, { Name = "${local.server_name}-public-${count.index}" })
}

resource "aws_internet_gateway" "main" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(local.tags, { Name = "${local.server_name}-igw" })
}

resource "aws_route_table" "public" {
  count = local.create_network ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.tags, { Name = "${local.server_name}-public-rt" })
}

resource "aws_route_table_association" "public" {
  count = local.create_network ? 2 : 0

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Security group for the Transfer endpoint
# Port 22 ingress is required by the SFTP protocol for remote clients.
###############################################################################

resource "aws_security_group" "transfer" {
  count = local.create_security_group ? 1 : 0

  name_prefix = "${local.server_name}-transfer-"
  description = "Ingress for the AWS Transfer Family SFTP endpoint"
  vpc_id      = local.vpc_id

  tags = merge(local.tags, { Name = "${local.server_name}-transfer" })

  ingress {
    description = "SFTP"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.sftp_ingress_cidr_blocks
  }

  egress {
    description     = "HTTPS to Amazon S3"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    prefix_list_ids = [data.aws_prefix_list.s3.id]
  }

  egress {
    description = "HTTPS to AWS service endpoints (Transfer Family, CloudWatch Logs)"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  lifecycle {
    create_before_destroy = true
  }
}

###############################################################################
# Elastic IP per subnet (VPC hosted Transfer endpoints only)
###############################################################################

resource "aws_eip" "transfer" {
  count = var.endpoint_type == "VPC" ? length(local.subnet_ids) : 0

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.server_name}-eip-${count.index}" })
}

###############################################################################
# EC2 Interface VPC endpoint fronting the Transfer Family service
###############################################################################

resource "aws_vpc_endpoint" "transfer" {
  count = var.endpoint_type == "VPC_ENDPOINT" ? 1 : 0

  vpc_id            = local.vpc_id
  vpc_endpoint_type = "Interface"
  service_name      = local.transfer_vpc_endpoint_service_name

  subnet_ids         = local.subnet_ids
  security_group_ids = local.security_group_ids

  tags = merge(local.tags, { Name = "${local.server_name}-vpce" })
}

###############################################################################
# Transfer Family server
###############################################################################

resource "aws_transfer_server" "this" {
  domain                      = "S3"
  endpoint_type               = var.endpoint_type
  protocols                   = var.protocols
  security_policy_name        = var.security_policy_name
  certificate                 = var.certificate_arn
  host_key                    = var.host_key
  logging_role                = local.logging_role_arn
  structured_log_destinations = length(var.structured_log_destinations) > 0 ? var.structured_log_destinations : null
  identity_provider_type      = local.identity_provider_type
  invocation_role             = local.api_gateway_enabled ? try(aws_iam_role.api_gateway[0].arn, null) : null
  url                         = local.api_gateway_enabled ? var.api_gateway_url : null

  tags = local.tags

  dynamic "endpoint_details" {
    for_each = var.endpoint_type == "PUBLIC" ? [] : [1]

    content {
      vpc_id             = var.endpoint_type == "VPC" ? local.vpc_id : null
      subnet_ids         = var.endpoint_type == "VPC" ? local.subnet_ids : null
      security_group_ids = var.endpoint_type == "VPC" ? local.security_group_ids : null
      vpc_endpoint_id    = var.endpoint_type == "VPC_ENDPOINT" ? try(aws_vpc_endpoint.transfer[0].id, null) : null
    }
  }

  dynamic "protocol_details" {
    for_each = length(keys(local.protocol_details)) > 0 ? [local.protocol_details] : []

    content {
      as2_transports              = try(protocol_details.value.as2_transports, null)
      passive_ip                  = try(protocol_details.value.passive_ip, null)
      set_stat_option             = try(protocol_details.value.set_stat_option, null)
      tls_session_resumption_mode = try(protocol_details.value.tls_session_resumption_mode, null)
    }
  }
}

###############################################################################
# Route 53
###############################################################################

resource "aws_route53_zone" "this" {
  count = local.create_route53_zone ? 1 : 0

  name = var.domain_name

  tags = merge(local.tags, { Name = "${local.server_name}-zone" })
}

resource "aws_route53_record" "transfer" {
  count = local.create_route53_record ? 1 : 0

  zone_id = local.zone_id
  name    = "${var.subdomain}.${var.domain_name}"
  type    = "CNAME"
  ttl     = 300
  records = [aws_transfer_server.this.endpoint]
}

###############################################################################
# Per-user S3 home buckets
###############################################################################

resource "aws_s3_bucket" "user_home" {
  for_each = var.sftp_users

  bucket = local.user_bucket_name[each.key]

  tags = merge(local.tags, {
    Name          = local.user_bucket_name[each.key]
    TransferUser  = each.key
    TransferServe = local.server_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "user_home" {
  for_each = aws_s3_bucket.user_home

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "user_home" {
  for_each = aws_s3_bucket.user_home

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "user_home" {
  for_each = aws_s3_bucket.user_home

  bucket = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "user_home" {
  for_each = aws_s3_bucket.user_home

  bucket = each.value.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "DenyInsecureTransport"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource = [
          each.value.arn,
          "${each.value.arn}/*"
        ]
        Condition = {
          Bool = { "aws:SecureTransport" = "false" }
        }
      }
    ]
  })
}

###############################################################################
# Per-user IAM role, inline policy and Transfer user
###############################################################################

resource "aws_iam_role" "sftp_user" {
  for_each = var.sftp_users

  name = "${local.server_name}-${each.key}-transfer"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "TransferAssumeRole"
        Effect    = "Allow"
        Action    = "sts:AssumeRole"
        Principal = { Service = "transfer.amazonaws.com" }
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = merge(local.tags, { TransferUser = each.key })
}

resource "aws_iam_role_policy" "sftp_user" {
  for_each = var.sftp_users

  name = "${local.server_name}-${each.key}-s3-access"
  role = aws_iam_role.sftp_user[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListHomeBucket"
        Effect = "Allow"
        Action = [
          "s3:ListBucket",
          "s3:GetBucketLocation"
        ]
        Resource = [
          aws_s3_bucket.user_home[each.key].arn
        ]
      },
      {
        Sid    = "ReadWriteHomeDirectory"
        Effect = "Allow"
        Action = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          local.user_prefix[each.key] == "" ? "${aws_s3_bucket.user_home[each.key].arn}/*" : "${aws_s3_bucket.user_home[each.key].arn}/${local.user_prefix[each.key]}/*"
        ]
      }
    ]
  })
}

resource "aws_transfer_user" "this" {
  for_each = var.sftp_users

  server_id           = aws_transfer_server.this.id
  user_name           = each.key
  role                = aws_iam_role.sftp_user[each.key].arn
  home_directory_type = each.value.home_directory_type
  home_directory      = local.user_prefix[each.key] == "" ? "/${aws_s3_bucket.user_home[each.key].id}" : "/${aws_s3_bucket.user_home[each.key].id}/${local.user_prefix[each.key]}"

  tags = merge(local.tags, { TransferUser = each.key })
}

resource "aws_transfer_ssh_key" "this" {
  for_each = local.user_keys

  server_id = aws_transfer_server.this.id
  user_name = each.value.user
  body      = each.value.key
}

###############################################################################
# Outputs
###############################################################################

output "transfer_server_id" {
  description = "ID of the AWS Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "transfer_server_arn" {
  description = "ARN of the AWS Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "transfer_server_endpoint" {
  description = "Endpoint hostname of the AWS Transfer Family server."
  value       = aws_transfer_server.this.endpoint
}

output "transfer_server_logging_role_arn" {
  description = "IAM role ARN used for Transfer Family logging."
  value       = local.logging_role_arn
}

output "transfer_cloudwatch_log_group_name" {
  description = "CloudWatch log group used for Transfer Family logs."
  value       = aws_cloudwatch_log_group.transfer.name
}

output "route53_record_fqdn" {
  description = "FQDN of the Route 53 CNAME record when created."
  value       = try(aws_route53_record.transfer[0].fqdn, null)
}

output "transfer_security_group_id" {
  description = "ID of the security group created for the Transfer endpoint, if any."
  value       = try(aws_security_group.transfer[0].id, null)
}

output "transfer_vpc_endpoint_id" {
  description = "ID of the Interface VPC endpoint fronting the Transfer Family service, when created."
  value       = try(aws_vpc_endpoint.transfer[0].id, null)
}

output "transfer_vpc_id" {
  description = "VPC ID used by the Transfer endpoint, if any."
  value       = local.is_vpc_endpoint_type ? local.vpc_id : null
}

output "transfer_subnet_ids" {
  description = "Subnet IDs used by the Transfer endpoint, if any."
  value       = local.is_vpc_endpoint_type ? local.subnet_ids : []
}

output "sftp_user_role_arns" {
  description = "Map of SFTP user name to the ARN of its IAM role."
  value       = { for name, role in aws_iam_role.sftp_user : name => role.arn }
}

output "sftp_user_bucket_ids" {
  description = "Map of SFTP user name to the ID of its S3 home bucket."
  value       = { for name, bucket in aws_s3_bucket.user_home : name => bucket.id }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "is_ipv6_enabled" {
  description = "Assign an Amazon-provided IPv6 CIDR block to the VPC and enable dual-stack (IPv4/IPv6) networking on all subnets."
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  # First three AZs available in the region (never hardcode AZ names).
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # Tiers deployed into every AZ: web (public), app/database/reserved (private).
  tiers = ["web", "app", "database", "reserved"]

  # Single source of truth for subnet creation: 4 tiers x 3 AZs = 12 subnets.
  sn_details = flatten([
    for tier in local.tiers : [
      for idx, az in local.azs : {
        name   = "${tier}-${idx + 1}"
        az     = az
        public = tier == "web"
        tier   = tier
      }
    ]
  ])

  subnets_by_name = { for s in local.sn_details : s.name => s }
  public_subnets  = { for s in local.sn_details : s.name => s if s.public }
  private_subnets = { for s in local.sn_details : s.name => s if !s.public }

  vpc_name = "main-vpc"
}

resource "aws_vpc" "main" {
  cidr_block                       = "10.16.0.0/16"
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = local.vpc_name
  }
}

# Dynamically calculate the IPv4 /20 subnet blocks (4 additional bits).
module "subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block
  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = 4
    }
  ]
}

# Dynamically calculate the IPv6 /64 subnet blocks (8 additional bits).
module "subnets_ipv6" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"
  count   = var.is_ipv6_enabled ? 1 : 0

  base_cidr_block = aws_vpc.main.ipv6_cidr_block
  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = 8
    }
  ]
}

resource "aws_subnet" "main" {
  for_each = local.subnets_by_name

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az

  cidr_block      = module.subnets.network_cidr_blocks[each.key]
  ipv6_cidr_block = var.is_ipv6_enabled ? module.subnets_ipv6[0].network_cidr_blocks[each.key] : null

  assign_ipv6_address_on_creation = var.is_ipv6_enabled
  map_public_ip_on_launch         = each.value.public

  tags = {
    Name = each.value.name
    Tier = each.value.tier
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = local.public_subnets

  subnet_id      = aws_subnet.main[each.key].id
  route_table_id = aws_route_table.public.id
}

resource "aws_security_group" "web_sg" {
  name        = "web_sg"
  description = "Web tier: public HTTPS, VPC-only SSH, egress HTTPS to the app tier."
  vpc_id      = aws_vpc.main.id

  ingress {
    description      = "HTTPS from the internet (IPv4)"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = ["0.0.0.0/0"]
    ipv6_cidr_blocks = []
  }

  ingress {
    description      = "HTTPS from the internet (IPv6)"
    from_port        = 443
    to_port          = 443
    protocol         = "tcp"
    cidr_blocks      = []
    ipv6_cidr_blocks = ["::/0"]
  }

  ingress {
    description = "SSH restricted to the VPC IPv4 CIDR block"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description     = "HTTPS to the application tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.app_sg.id]
  }

  tags = {
    Name = "web_sg"
    Tier = "web"
  }
}

resource "aws_security_group" "app_sg" {
  name        = "app_sg"
  description = "Application tier: HTTPS from the web tier only, egress HTTPS to the database tier."
  vpc_id      = aws_vpc.main.id

  egress {
    description     = "HTTPS to the database tier"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.db_sg.id]
  }

  tags = {
    Name = "app_sg"
    Tier = "app"
  }
}

resource "aws_security_group" "db_sg" {
  name        = "db_sg"
  description = "Database tier: HTTPS from the application tier only."
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
    Tier = "database"
  }
}

# Cross-tier ingress rules are managed out-of-band so the tier security groups
# can reference each other without creating a circular dependency.
resource "aws_security_group_rule" "app_ingress_web" {
  type                     = "ingress"
  description              = "HTTPS from the web tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.app_sg.id
  source_security_group_id = aws_security_group.web_sg.id
}

resource "aws_security_group_rule" "db_ingress_app" {
  type                     = "ingress"
  description              = "HTTPS from the application tier"
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  security_group_id        = aws_security_group.db_sg.id
  source_security_group_id = aws_security_group.app_sg.id
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "IPv4 CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "vpc_ipv6_cidr_block" {
  description = "Amazon-provided IPv6 CIDR block of the main VPC."
  value       = aws_vpc.main.ipv6_cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value       = local.azs
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID."
  value       = { for name, sn in aws_subnet.main : name => sn.id }
}

output "public_subnet_ids" {
  description = "IDs of the public (web) subnets."
  value       = { for name, sn in aws_subnet.main : name => sn.id if local.subnets_by_name[name].public }
}

output "private_subnet_ids" {
  description = "IDs of the private (app, database, reserved) subnets."
  value       = { for name, sn in aws_subnet.main : name => sn.id if !local.subnets_by_name[name].public }
}

output "subnet_ipv4_cidr_blocks" {
  description = "Map of subnet name to IPv4 CIDR block."
  value       = module.subnets.network_cidr_blocks
}

output "subnet_ipv6_cidr_blocks" {
  description = "Map of subnet name to IPv6 CIDR block."
  value       = var.is_ipv6_enabled ? module.subnets_ipv6[0].network_cidr_blocks : {}
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "web_security_group_id" {
  description = "ID of the web tier security group."
  value       = aws_security_group.web_sg.id
}

output "app_security_group_id" {
  description = "ID of the application tier security group."
  value       = aws_security_group.app_sg.id
}

output "db_security_group_id" {
  description = "ID of the database tier security group."
  value       = aws_security_group.db_sg.id
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Input variables
###############################################################################

variable "create_vpc" {
  description = "Master toggle that gates creation of the VPC and every dependent resource."
  type        = bool
  default     = true
}

variable "project" {
  description = "Project / name prefix applied to every resource and to auto-generated subnet Name tags."
  type        = string
  default     = "vpc"
}

variable "vpc_cidr" {
  description = "IPv4 CIDR block assigned to the VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "vpc_cidr must be a valid IPv4 CIDR block, for example \"10.0.0.0/16\"."
  }
}

variable "enable_dns_support" {
  description = "Whether the VPC resolves DNS through the Amazon-provided DNS server."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether instances launched in the VPC receive public DNS hostnames."
  type        = bool
  default     = true
}

variable "availability_zones" {
  description = "Explicit list of availability zone names or IDs used for subnet placement. When empty, the region's available AZs are used."
  type        = list(string)
  default     = []
}

variable "public_subnet_cidrs" {
  description = "CIDR blocks for the public (internet-routable) subnet tier. An empty list disables the tier."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for cidr in var.public_subnet_cidrs : can(cidrhost(cidr, 0))])
    error_message = "Every public subnet CIDR must be a valid IPv4 CIDR block."
  }
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private (NAT-routed) subnet tier. An empty list disables the tier."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for cidr in var.private_subnet_cidrs : can(cidrhost(cidr, 0))])
    error_message = "Every private subnet CIDR must be a valid IPv4 CIDR block."
  }
}

variable "intra_subnet_cidrs" {
  description = "CIDR blocks for the isolated (intra) subnet tier. An empty list disables the tier."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for cidr in var.intra_subnet_cidrs : can(cidrhost(cidr, 0))])
    error_message = "Every intra subnet CIDR must be a valid IPv4 CIDR block."
  }
}

variable "public_subnet_names" {
  description = "Optional explicit Name tags for the public subnets. Missing entries fall back to the generated name."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit Name tags for the private subnets. Missing entries fall back to the generated name."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit Name tags for the intra subnets. Missing entries fall back to the generated name."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Tier suffix used when auto-generating public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Tier suffix used when auto-generating private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Tier suffix used when auto-generating intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched in public subnets receive a public IP address by default."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Whether an Internet Gateway is attached to the VPC when public subnets exist."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Whether NAT gateways (and their Elastic IPs) are provisioned for the private subnet tier."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Additional tags merged into every resource created by this module."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  subnet_tier_max = max(
    length(var.public_subnet_cidrs),
    length(var.private_subnet_cidrs),
    length(var.intra_subnet_cidrs)
  )

  # Explicit AZ list wins; otherwise use the region's available AZs, sliced to
  # the number of subnets requested so no empty index is ever referenced.
  azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(
    data.aws_availability_zones.available.names,
    0,
    min(local.subnet_tier_max, length(data.aws_availability_zones.available.names))
  )

  # ---- Subnet definitions ---------------------------------------------------
  public_subnets = {
    for idx, cidr in var.public_subnet_cidrs : tostring(idx) => {
      cidr = cidr
      az   = element(local.azs, idx)
      name = coalesce(
        try(var.public_subnet_names[idx], null),
        format("%s-%s-%s", var.project, var.public_subnet_suffix, element(local.azs, idx))
      )
    }
  }

  private_subnets = {
    for idx, cidr in var.private_subnet_cidrs : tostring(idx) => {
      cidr = cidr
      az   = element(local.azs, idx)
      name = coalesce(
        try(var.private_subnet_names[idx], null),
        format("%s-%s-%s", var.project, var.private_subnet_suffix, element(local.azs, idx))
      )
    }
  }

  intra_subnets = {
    for idx, cidr in var.intra_subnet_cidrs : tostring(idx) => {
      cidr = cidr
      az   = element(local.azs, idx)
      name = coalesce(
        try(var.intra_subnet_names[idx], null),
        format("%s-%s-%s", var.project, var.intra_subnet_suffix, element(local.azs, idx))
      )
    }
  }

  public_subnet_ids  = var.create_vpc ? [for i in range(length(var.public_subnet_cidrs)) : aws_subnet.public[tostring(i)].id] : []
  private_subnet_ids = var.create_vpc ? [for i in range(length(var.private_subnet_cidrs)) : aws_subnet.private[tostring(i)].id] : []
  intra_subnet_ids   = var.create_vpc ? [for i in range(length(var.intra_subnet_cidrs)) : aws_subnet.intra[tostring(i)].id] : []

  # ---- CIDR containment / overlap validation --------------------------------
  vpc_cidr_prefix = tonumber(split("/", var.vpc_cidr)[1])

  all_subnet_cidrs = concat(var.public_subnet_cidrs, var.private_subnet_cidrs, var.intra_subnet_cidrs)

  subnet_cidr_prefixes = {
    for cidr in local.all_subnet_cidrs : cidr => tonumber(split("/", cidr)[1])
  }

  # Each subnet must sit inside var.vpc_cidr. Containment is proven by
  # re-deriving the subnet from the VPC prefix with cidrsubnet. Deltas above the
  # enumeration guard are covered by the prefix-length check.
  subnet_containment = {
    for cidr in local.all_subnet_cidrs : cidr => (
      local.subnet_cidr_prefixes[cidr] < local.vpc_cidr_prefix
      ? false
      : (
        local.subnet_cidr_prefixes[cidr] - local.vpc_cidr_prefix > 12
        ? true
        : contains(
          [
            for i in range(pow(2, local.subnet_cidr_prefixes[cidr] - local.vpc_cidr_prefix)) :
            cidrsubnet(var.vpc_cidr, local.subnet_cidr_prefixes[cidr] - local.vpc_cidr_prefix, i)
          ],
          cidrsubnet(cidr, 0, 0)
        )
      )
    )
  }

  subnets_within_vpc = alltrue(values(local.subnet_containment))

  # ---- NAT gateway sizing ---------------------------------------------------
  # NAT gateways require public subnets (for placement), private subnets (for
  # consumers) and an Internet Gateway (for the public route table).
  nat_gateway_count = (
    var.create_vpc
    && var.enable_nat_gateway
    && var.create_igw
    && length(var.public_subnet_cidrs) > 0
    && length(var.private_subnet_cidrs) > 0
  ) ? min(length(var.public_subnet_cidrs), length(var.private_subnet_cidrs)) : 0

  nat_enabled = local.nat_gateway_count > 0

  private_subnet_count = length(var.private_subnet_cidrs)

  # One private route table per private subnet when NAT is on; a single shared
  # private route table (local route only) when NAT is off.
  private_route_tables = (var.create_vpc && local.private_subnet_count > 0) ? (
    local.nat_enabled
    ? { for i in range(local.private_subnet_count) : tostring(i) => i }
    : { "shared" = -1 }
  ) : {}

  # ---- Route table id aggregation ------------------------------------------
  public_route_table_ids = aws_route_table.public[*].id

  private_route_table_ids = var.create_vpc ? (
    local.nat_enabled
    ? [for i in range(local.private_subnet_count) : aws_route_table.private[tostring(i)].id]
    : [for rt in values(aws_route_table.private) : rt.id]
  ) : []

  intra_route_table_ids = var.create_vpc ? [
    for i in range(length(var.intra_subnet_cidrs)) : aws_route_table.intra[tostring(i)].id
  ] : []
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(var.tags, {
    Name = format("%s-vpc", var.project)
  })

  lifecycle {
    precondition {
      condition     = local.subnets_within_vpc
      error_message = "Every subnet CIDR block must be contained within var.vpc_cidr."
    }

    precondition {
      condition = length(
        distinct([for cidr in local.all_subnet_cidrs : cidrsubnet(cidr, 0, 0)])
      ) == length(local.all_subnet_cidrs)
      error_message = "Subnet CIDR blocks must be unique and must not overlap between tiers."
    }
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  for_each = var.create_vpc ? local.public_subnets : {}

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(var.tags, {
    Name = each.value.name
  })
}

resource "aws_subnet" "private" {
  for_each = var.create_vpc ? local.private_subnets : {}

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = each.value.name
  })
}

resource "aws_subnet" "intra" {
  for_each = var.create_vpc ? local.intra_subnets : {}

  vpc_id                  = aws_vpc.main[0].id
  cidr_block              = each.value.cidr
  availability_zone       = each.value.az
  map_public_ip_on_launch = false

  tags = merge(var.tags, {
    Name = each.value.name
  })
}

###############################################################################
# Internet Gateway + public routing
###############################################################################

resource "aws_internet_gateway" "main" {
  count = (var.create_vpc && var.create_igw && length(var.public_subnet_cidrs) > 0) ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = format("%s-igw", var.project)
  })
}

resource "aws_route_table" "public" {
  count = (var.create_vpc && length(var.public_subnet_cidrs) > 0) ? 1 : 0

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = format("%s-public-rt", var.project)
  })
}

resource "aws_route" "public_internet" {
  count = (var.create_vpc && var.create_igw && length(var.public_subnet_cidrs) > 0) ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main[0].id
}

resource "aws_route_table_association" "public" {
  for_each = var.create_vpc ? local.public_subnets : {}

  subnet_id      = aws_subnet.public[each.key].id
  route_table_id = aws_route_table.public[0].id
}

###############################################################################
# Elastic IPs + NAT gateways
###############################################################################

resource "aws_eip" "nat" {
  count = local.nat_gateway_count

  domain = "vpc"

  tags = merge(var.tags, {
    Name = format("%s-nat-eip-%d", var.project, count.index + 1)
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.nat_gateway_count

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[tostring(count.index)].id

  tags = merge(var.tags, {
    Name = format("%s-nat-%d", var.project, count.index + 1)
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Private routing (NAT when enabled, isolated otherwise)
###############################################################################

resource "aws_route_table" "private" {
  for_each = local.private_route_tables

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = local.nat_enabled ? format("%s-private-rt-%s", var.project, each.key) : format("%s-private-rt", var.project)
  })
}

resource "aws_route" "private_nat" {
  for_each = local.nat_enabled ? local.private_subnets : {}

  route_table_id         = aws_route_table.private[each.key].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main[tonumber(each.key) % local.nat_gateway_count].id
}

resource "aws_route_table_association" "private" {
  for_each = var.create_vpc ? local.private_subnets : {}

  subnet_id = aws_subnet.private[each.key].id
  route_table_id = (
    local.nat_enabled
    ? aws_route_table.private[each.key].id
    : aws_route_table.private["shared"].id
  )
}

###############################################################################
# Intra (isolated) routing - VPC-local route only
###############################################################################

resource "aws_route_table" "intra" {
  for_each = var.create_vpc ? local.intra_subnets : {}

  vpc_id = aws_vpc.main[0].id

  tags = merge(var.tags, {
    Name = format("%s-%s-rt-%s", var.project, var.intra_subnet_suffix, each.key)
  })
}

resource "aws_route_table_association" "intra" {
  for_each = var.create_vpc ? local.intra_subnets : {}

  subnet_id      = aws_subnet.intra[each.key].id
  route_table_id = aws_route_table.intra[each.key].id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the VPC, or null when create_vpc = false."
  value       = try(aws_vpc.main[0].id, null)
}

output "vpc_cidr_block" {
  description = "CIDR block of the VPC, or null when create_vpc = false."
  value       = try(aws_vpc.main[0].cidr_block, null)
}

output "availability_zones" {
  description = "Availability zones the subnets were placed into."
  value       = local.azs
}

output "public_subnet_ids" {
  description = "IDs of the public subnets, ordered by input index."
  value       = local.public_subnet_ids
}

output "private_subnet_ids" {
  description = "IDs of the private subnets, ordered by input index."
  value       = local.private_subnet_ids
}

output "intra_subnet_ids" {
  description = "IDs of the intra (isolated) subnets, ordered by input index."
  value       = local.intra_subnet_ids
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway, or null when it is not created."
  value       = try(aws_internet_gateway.main[0].id, null)
}

output "nat_gateway_ids" {
  description = "IDs of the NAT gateways."
  value       = aws_nat_gateway.main[*].id
}

output "public_route_table_ids" {
  description = "IDs of the public route tables."
  value       = local.public_route_table_ids
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = local.private_route_table_ids
}

output "intra_route_table_ids" {
  description = "IDs of the intra (isolated) route tables."
  value       = local.intra_route_table_ids
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    archive = {
      source  = "hashicorp/archive"
      version = "~> 2.4"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.4"
    }
  }
}

###############################################################################
# Data sources (static / provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

###############################################################################
# Variables
###############################################################################

variable "api_type" {
  description = "API Gateway flavour to provision: \"http\" (API Gateway v2) or \"rest\" (API Gateway v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either \"http\" or \"rest\"."
  }
}

variable "api_name" {
  description = "Name of the API Gateway that is provisioned."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name, used to build the stage name (\"<environment>-stage\") and resource names."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project   = "benchmark-api"
    ManagedBy = "terraform"
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC created by this configuration."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_count" {
  description = "Number of private subnets to create (one per availability zone, starting at index 0)."
  type        = number
  default     = 2

  validation {
    condition     = var.private_subnet_count > 0 && var.private_subnet_count <= 6
    error_message = "private_subnet_count must be between 1 and 6."
  }
}

variable "routes" {
  description = "HTTP API (v2) route map. Each entry produces one Lambda proxy integration and one route."
  type = map(object({
    path       = string
    method     = optional(string, "GET")
    authorizer = optional(bool, false)
  }))
  default = {
    "list-items" = {
      path       = "/items"
      method     = "GET"
      authorizer = false
    }
  }
}

variable "rest_routes" {
  description = "REST API (v1) route map. Each entry produces a resource, a method and a Lambda proxy integration. parent_key refers to another entry in this map (null/omitted = child of the API root)."
  type = map(object({
    path_part       = string
    parent_key      = optional(string)
    http_method     = optional(string, "GET")
    authorizer      = optional(bool, false)
    path_parameters = optional(map(bool), {})
  }))
  default = {
    "items" = {
      path_part   = "items"
      http_method = "GET"
    }
  }
}

variable "domain_name" {
  description = "Custom domain name to attach to the API. When empty no custom domain, certificate or DNS records are created."
  type        = string
  default     = ""
}

variable "route53_zone_name" {
  description = "Name of the Route 53 public hosted zone to create. Defaults to the value of domain_name when empty."
  type        = string
  default     = ""
}

variable "cors_allow_origins" {
  description = "Allowed origins for the HTTP API CORS configuration."
  type        = list(string)
  default     = ["*"]
}

variable "cors_allow_methods" {
  description = "Allowed methods for the HTTP API CORS configuration."
  type        = list(string)
  default     = ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"]
}

variable "enable_authorizer" {
  description = "Whether a custom Lambda authorizer is created and wired into the API."
  type        = bool
  default     = true
}

variable "authorizer_type" {
  description = "REST API authorizer type: REQUEST, TOKEN or COGNITO_USER_POOLS."
  type        = string
  default     = "REQUEST"
}

variable "authorizer_identity_source" {
  description = "Identity source for the REST API authorizer."
  type        = string
  default     = "method.request.header.Authorization"
}

variable "authorizer_identity_sources" {
  description = "Identity sources for the HTTP API authorizer."
  type        = list(string)
  default     = ["$request.header.Authorization"]
}

variable "authorizer_result_ttl_in_seconds" {
  description = "Authorizer caching TTL in seconds (0 disables caching)."
  type        = number
  default     = 300
}

variable "enable_ip_restriction" {
  description = "Whether the REST API receives an IP based source restriction resource policy."
  type        = bool
  default     = false
}

variable "allowed_cidrs" {
  description = "CIDR ranges allowed to invoke the REST API when enable_ip_restriction is true."
  type        = list(string)
  default     = ["10.0.0.0/16"]
}

variable "enable_usage_plan" {
  description = "Whether a usage plan, API key and SecureString SSM parameter are created for the REST API."
  type        = bool
  default     = true
}

variable "usage_plan_throttle_rate_limit" {
  description = "Steady-state request rate limit (requests per second) for the usage plan."
  type        = number
  default     = 100
}

variable "usage_plan_throttle_burst_limit" {
  description = "Burst request limit for the usage plan."
  type        = number
  default     = 200
}

variable "usage_plan_quota_limit" {
  description = "Maximum number of requests allowed per quota period."
  type        = number
  default     = 10000
}

variable "usage_plan_quota_period" {
  description = "Quota period for the usage plan (DAY, WEEK or MONTH)."
  type        = string
  default     = "MONTH"
}

variable "api_key_parameter_name" {
  description = "Name of the SSM Parameter Store parameter holding the generated API key. Defaults to /<api_name>/<environment>/api-key."
  type        = string
  default     = ""
}

variable "enable_vpc_link" {
  description = "Whether VPC link networking (security groups, load balancers and the API Gateway VPC link) is provisioned."
  type        = bool
  default     = false
}

variable "vpc_link_target_port" {
  description = "TCP port used by the VPC link target group and the internal application load balancer listener."
  type        = number
  default     = 443
}

variable "vpc_link_listener_port" {
  description = "TCP port exposed by the network load balancer fronting the VPC link."
  type        = number
  default     = 443
}

variable "vpc_link_health_check_path" {
  description = "HTTPS health check path used by the VPC link target group."
  type        = string
  default     = "/health"
}

variable "application_port" {
  description = "Port used by the internal application target group behind the internal ALB."
  type        = number
  default     = 80
}

variable "lambda_memory_size" {
  description = "Memory size (MB) for the Lambda functions."
  type        = number
  default     = 256
}

variable "lambda_timeout" {
  description = "Timeout (seconds) for the Lambda functions."
  type        = number
  default     = 10
}

variable "log_retention_in_days" {
  description = "CloudWatch Logs retention for the log groups created by this configuration."
  type        = number
  default     = 30
}

###############################################################################
# Locals
###############################################################################

locals {
  is_http       = var.api_type == "http"
  is_rest       = var.api_type == "rest"
  enable_domain = var.domain_name != ""
  stage_name    = "${var.environment}-stage"
  name_prefix   = "${var.api_name}-${var.environment}"

  route53_zone_name = var.route53_zone_name != "" ? var.route53_zone_name : var.domain_name

  api_key_parameter_name = var.api_key_parameter_name != "" ? var.api_key_parameter_name : "/${var.api_name}/${var.environment}/api-key"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
      ApiName     = var.api_name
      ManagedBy   = "terraform"
    }
  )

  lambda_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "lambda.amazonaws.com" }
    }]
  })

  apigateway_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Action    = "sts:AssumeRole"
      Principal = { Service = "apigateway.amazonaws.com" }
    }]
  })
}

###############################################################################
# Network foundation
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-igw" })
}

resource "aws_subnet" "private" {
  count = var.private_subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(var.vpc_cidr, 8, count.index)
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-private-${count.index}"
    Tier = "private"
  })
}

resource "aws_route_table" "main" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-rt" })
}

resource "aws_route_table_association" "private" {
  count = var.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.main.id
}

resource "aws_security_group" "vpc_link" {
  count = var.enable_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-vpclink-sg"
  description = "Security group for the API Gateway VPC link load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Inbound API traffic from within the VPC"
    from_port   = var.vpc_link_listener_port
    to_port     = var.vpc_link_listener_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic to the internal application load balancer"
    from_port   = var.vpc_link_target_port
    to_port     = var.vpc_link_target_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpclink-sg" })
}

resource "aws_security_group" "alb" {
  count = var.enable_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-alb-sg"
  description = "Security group for the internal application load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "HTTPS from the VPC link security group"
    from_port       = var.vpc_link_target_port
    to_port         = var.vpc_link_target_port
    protocol        = "tcp"
    security_groups = [aws_security_group.vpc_link[0].id]
  }

  ingress {
    description = "HTTPS from within the VPC"
    from_port   = var.vpc_link_target_port
    to_port     = var.vpc_link_target_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Outbound traffic to application targets within the VPC"
    from_port   = var.application_port
    to_port     = var.application_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-sg" })
}

###############################################################################
# CloudWatch log groups
###############################################################################

resource "aws_cloudwatch_log_group" "api_handler" {
  name              = "/aws/lambda/${local.name_prefix}-handler"
  retention_in_days = var.log_retention_in_days

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-handler-logs" })
}

resource "aws_cloudwatch_log_group" "authorizer" {
  name              = "/aws/lambda/${local.name_prefix}-authorizer"
  retention_in_days = var.log_retention_in_days

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-authorizer-logs" })
}

resource "aws_cloudwatch_log_group" "api_execution" {
  name              = "/aws/apigateway/${local.name_prefix}"
  retention_in_days = var.log_retention_in_days

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-api-execution-logs" })
}

###############################################################################
# Lambda source artifacts
###############################################################################

resource "local_file" "api_handler" {
  filename = "${path.module}/lambda/api-handler/index.js"
  content  = <<-EOT
    'use strict';

    exports.handler = async (event) => {
      const path = event.rawPath || event.path || '/';

      return {
        statusCode: 200,
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({ message: 'ok', path: path })
      };
    };
  EOT
}

resource "local_file" "authorizer" {
  filename = "${path.module}/lambda/authorizer/index.js"
  content  = <<-EOT
    'use strict';

    function buildPolicy(principalId, effect, resource) {
      return {
        principalId: principalId,
        policyDocument: {
          Version: '2012-10-17',
          Statement: [
            {
              Action: 'execute-api:Invoke',
              Effect: effect,
              Resource: resource
            }
          ]
        }
      };
    }

    exports.handler = async (event) => {
      const headers = event.headers || {};
      const token = headers.authorization || headers.Authorization;

      if (!token) {
        if (event.version === '2.0') {
          return { isAuthorized: false };
        }
        throw new Error('Unauthorized');
      }

      if (event.version === '2.0') {
        return { isAuthorized: true, context: { token: token } };
      }

      return buildPolicy('api-user', 'Allow', event.methodArn);
    };
  EOT
}

data "archive_file" "api_handler" {
  type        = "zip"
  source_file = local_file.api_handler.filename
  output_path = "${path.module}/lambda/api-handler.zip"
}

data "archive_file" "authorizer" {
  type        = "zip"
  source_file = local_file.authorizer.filename
  output_path = "${path.module}/lambda/authorizer.zip"
}

###############################################################################
# IAM
###############################################################################

resource "aws_iam_role" "api_handler_execution" {
  name               = "${local.name_prefix}-handler-role"
  assume_role_policy = local.lambda_assume_role_policy

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-handler-role" })
}

resource "aws_iam_role_policy" "api_handler_execution" {
  name = "${local.name_prefix}-handler-logs"
  role = aws_iam_role.api_handler_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = [
        aws_cloudwatch_log_group.api_handler.arn,
        "${aws_cloudwatch_log_group.api_handler.arn}:*"
      ]
    }]
  })
}

resource "aws_iam_role" "authorizer_execution" {
  name               = "${local.name_prefix}-authorizer-role"
  assume_role_policy = local.lambda_assume_role_policy

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-authorizer-role" })
}

resource "aws_iam_role_policy" "authorizer_execution" {
  name = "${local.name_prefix}-authorizer-logs"
  role = aws_iam_role.authorizer_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = [
        aws_cloudwatch_log_group.authorizer.arn,
        "${aws_cloudwatch_log_group.authorizer.arn}:*"
      ]
    }]
  })
}

resource "aws_iam_role" "apigw_invoke" {
  name               = "${local.name_prefix}-apigw-invoke-role"
  assume_role_policy = local.apigateway_assume_role_policy

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-apigw-invoke-role" })
}

resource "aws_iam_role_policy" "apigw_invoke_authorizer" {
  name = "${local.name_prefix}-invoke-authorizer"
  role = aws_iam_role.apigw_invoke.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "lambda:InvokeFunction"
      Resource = [aws_lambda_function.authorizer.arn]
    }]
  })
}

resource "aws_iam_role" "apigw_cloudwatch" {
  count = local.is_rest ? 1 : 0

  name               = "${local.name_prefix}-apigw-cloudwatch-role"
  assume_role_policy = local.apigateway_assume_role_policy

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-apigw-cloudwatch-role" })
}

resource "aws_iam_role_policy" "apigw_cloudwatch" {
  count = local.is_rest ? 1 : 0

  name = "${local.name_prefix}-apigw-cloudwatch"
  role = aws_iam_role.apigw_cloudwatch[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.api_execution.arn,
          "${aws_cloudwatch_log_group.api_execution.arn}:*"
        ]
      },
      {
        Effect = "Allow"
        Action = [
          "logs:DescribeLogGroups",
          "logs:DescribeLogStreams"
        ]
        Resource = "*"
      }
    ]
  })
}

###############################################################################
# Lambda functions
###############################################################################

resource "aws_lambda_function" "api_handler" {
  function_name    = "${local.name_prefix}-handler"
  description      = "Backend handler for the ${var.api_name} API"
  role             = aws_iam_role.api_handler_execution.arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.api_handler.output_path
  source_code_hash = data.archive_file.api_handler.output_base64sha256
  memory_size      = var.lambda_memory_size
  timeout          = var.lambda_timeout

  environment {
    variables = {
      API_NAME  = var.api_name
      LOG_LEVEL = "INFO"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-handler" })

  depends_on = [aws_cloudwatch_log_group.api_handler]
}

resource "aws_lambda_function" "authorizer" {
  function_name    = "${local.name_prefix}-authorizer"
  description      = "Custom Lambda authorizer for the ${var.api_name} API"
  role             = aws_iam_role.authorizer_execution.arn
  handler          = "index.handler"
  runtime          = "nodejs20.x"
  filename         = data.archive_file.authorizer.output_path
  source_code_hash = data.archive_file.authorizer.output_base64sha256
  memory_size      = var.lambda_memory_size
  timeout          = var.lambda_timeout

  environment {
    variables = {
      API_NAME  = var.api_name
      LOG_LEVEL = "INFO"
    }
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-authorizer" })

  depends_on = [aws_cloudwatch_log_group.authorizer]
}

resource "aws_lambda_permission" "handler_http" {
  count = local.is_http ? 1 : 0

  statement_id  = "AllowExecutionFromHttpApi"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.api_handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/*/*"
}

resource "aws_lambda_permission" "handler_rest" {
  count = local.is_rest ? 1 : 0

  statement_id  = "AllowExecutionFromRestApi"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.api_handler.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*/*"
}

resource "aws_lambda_permission" "authorizer_http" {
  count = local.is_http && var.enable_authorizer ? 1 : 0

  statement_id  = "AllowAuthorizerInvocationFromHttpApi"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/authorizers/*"
}

resource "aws_lambda_permission" "authorizer_rest" {
  count = local.is_rest && var.enable_authorizer ? 1 : 0

  statement_id  = "AllowAuthorizerInvocationFromRestApi"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/authorizers/*"
}

###############################################################################
# HTTP API (API Gateway v2)
###############################################################################

resource "aws_apigatewayv2_api" "http" {
  count = local.is_http ? 1 : 0

  name          = var.api_name
  protocol_type = "HTTP"
  description   = "HTTP API provisioned by Terraform for ${var.environment}"

  cors_configuration {
    allow_origins = var.cors_allow_origins
    allow_methods = var.cors_allow_methods
    allow_headers = ["*"]
    max_age       = 300
  }

  tags = merge(local.common_tags, { Name = var.api_name })
}

resource "aws_apigatewayv2_authorizer" "http" {
  count = local.is_http && var.enable_authorizer ? 1 : 0

  api_id                            = aws_apigatewayv2_api.http[0].id
  name                              = "${var.api_name}-authorizer"
  authorizer_type                   = "REQUEST"
  authorizer_uri                    = aws_lambda_function.authorizer.invoke_arn
  authorizer_payload_format_version = "2.0"
  enable_simple_responses           = true
  identity_sources                  = var.authorizer_identity_sources
  authorizer_credentials_arn        = aws_iam_role.apigw_invoke.arn
  authorizer_result_ttl_in_seconds  = var.authorizer_result_ttl_in_seconds
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count = local.is_http && var.enable_vpc_link ? 1 : 0

  name               = "${local.name_prefix}-vpclink"
  subnet_ids         = aws_subnet.private[*].id
  security_group_ids = [aws_security_group.vpc_link[0].id]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpclink" })
}

resource "aws_apigatewayv2_integration" "http" {
  for_each = { for key, route in var.routes : key => route if local.is_http }

  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = "AWS_PROXY"
  integration_method     = "POST"
  integration_uri        = aws_lambda_function.api_handler.invoke_arn
  payload_format_version = "2.0"
  connection_type        = var.enable_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id          = var.enable_vpc_link ? aws_apigatewayv2_vpc_link.http[0].id : null
  timeout_milliseconds   = var.lambda_timeout * 1000
}

resource "aws_apigatewayv2_route" "http" {
  for_each = { for key, route in var.routes : key => route if local.is_http }

  api_id             = aws_apigatewayv2_api.http[0].id
  route_key          = "${each.value.method} ${each.value.path}"
  target             = "integrations/${aws_apigatewayv2_integration.http[each.key].id}"
  authorization_type = each.value.authorizer ? "CUSTOM" : "NONE"
  authorizer_id      = each.value.authorizer ? aws_apigatewayv2_authorizer.http[0].id : null
}

resource "aws_apigatewayv2_stage" "http" {
  count = local.is_http ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true
  description = "Auto deployed stage for ${var.environment}"

  default_route_settings {
    throttling_burst_limit = var.usage_plan_throttle_burst_limit
    throttling_rate_limit  = var.usage_plan_throttle_rate_limit
  }

  tags = merge(local.common_tags, { Name = "${var.api_name}-${local.stage_name}" })
}

###############################################################################
# Custom domain (shared by both API flavours)
###############################################################################

resource "aws_route53_zone" "this" {
  count = local.enable_domain ? 1 : 0

  name    = local.route53_zone_name
  comment = "Public hosted zone for ${var.api_name} (${var.environment})"

  tags = merge(local.common_tags, { Name = local.route53_zone_name })
}

resource "aws_acm_certificate" "this" {
  count = local.enable_domain ? 1 : 0

  domain_name       = var.domain_name
  validation_method = "DNS"

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-certificate" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_route53_record" "certificate_validation" {
  for_each = local.enable_domain ? {
    for option in aws_acm_certificate.this[0].domain_validation_options : option.domain_name => {
      name   = option.resource_record_name
      record = option.resource_record_value
      type   = option.resource_record_type
    }
  } : {}

  zone_id         = aws_route53_zone.this[0].zone_id
  name            = each.value.name
  type            = each.value.type
  records         = [each.value.record]
  ttl             = 60
  allow_overwrite = true
}

resource "aws_acm_certificate_validation" "this" {
  count = local.enable_domain ? 1 : 0

  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.certificate_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count = local.is_http && local.enable_domain ? 1 : 0

  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.this[0].certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = merge(local.common_tags, { Name = var.domain_name })
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count = local.is_http && local.enable_domain ? 1 : 0

  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_alias" {
  count = local.is_http && local.enable_domain ? 1 : 0

  zone_id = aws_route53_zone.this[0].zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# REST API (API Gateway v1)
###############################################################################

resource "aws_api_gateway_rest_api" "rest" {
  count = local.is_rest ? 1 : 0

  name        = var.api_name
  description = "REST API provisioned by Terraform for ${var.environment}"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = merge(local.common_tags, { Name = var.api_name })
}

resource "aws_api_gateway_resource" "rest_root" {
  for_each = {
    for key, route in var.rest_routes : key => route
    if local.is_rest && route.parent_key == null
  }

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_rest_api.rest[0].root_resource_id
  path_part   = each.value.path_part
}

resource "aws_api_gateway_resource" "rest_child" {
  for_each = {
    for key, route in var.rest_routes : key => route
    if local.is_rest && route.parent_key != null
  }

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id   = aws_api_gateway_resource.rest_root[each.value.parent_key].id
  path_part   = each.value.path_part
}

locals {
  rest_resource_ids = merge(
    { for key, resource in aws_api_gateway_resource.rest_root : key => resource.id },
    { for key, resource in aws_api_gateway_resource.rest_child : key => resource.id }
  )
}

resource "aws_api_gateway_authorizer" "rest" {
  count = local.is_rest && var.enable_authorizer ? 1 : 0

  name                             = "${var.api_name}-authorizer"
  rest_api_id                      = aws_api_gateway_rest_api.rest[0].id
  type                             = var.authorizer_type
  authorizer_uri                   = aws_lambda_function.authorizer.invoke_arn
  authorizer_credentials           = aws_iam_role.apigw_invoke.arn
  identity_source                  = var.authorizer_identity_source
  authorizer_result_ttl_in_seconds = var.authorizer_result_ttl_in_seconds
}

resource "aws_api_gateway_method" "rest" {
  for_each = { for key, route in var.rest_routes : key => route if local.is_rest }

  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  resource_id   = local.rest_resource_ids[each.key]
  http_method   = each.value.http_method
  authorization = each.value.authorizer ? "CUSTOM" : "NONE"
  authorizer_id = each.value.authorizer ? aws_api_gateway_authorizer.rest[0].id : null

  request_parameters = each.value.path_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = { for key, route in var.rest_routes : key => route if local.is_rest }

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  resource_id = local.rest_resource_ids[each.key]
  http_method = aws_api_gateway_method.rest[each.key].http_method

  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.api_handler.invoke_arn
  connection_type         = var.enable_vpc_link ? "VPC_LINK" : "INTERNET"
  connection_id           = var.enable_vpc_link ? aws_api_gateway_vpc_link.rest[0].id : null

  request_parameters = each.value.path_parameters
}

resource "aws_api_gateway_rest_api_policy" "rest" {
  count = local.is_rest && var.enable_ip_restriction ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = "*"
      Action    = "execute-api:Invoke"
      Resource  = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*/*"
      Condition = {
        IpAddress = {
          "aws:SourceIp" = var.allowed_cidrs
        }
      }
    }]
  })
}

###############################################################################
# REST VPC link infrastructure (internal NLB -> internal ALB)
###############################################################################

resource "aws_lb" "application" {
  count = var.enable_vpc_link ? 1 : 0

  name               = substr("${local.name_prefix}-alb", 0, 32)
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb" })
}

resource "aws_lb_target_group" "application" {
  count = var.enable_vpc_link ? 1 : 0

  name        = substr("${local.name_prefix}-app-tg", 0, 32)
  port        = var.application_port
  protocol    = "HTTP"
  target_type = "ip"
  vpc_id      = aws_vpc.main.id

  health_check {
    enabled             = true
    protocol            = "HTTP"
    path                = var.vpc_link_health_check_path
    port                = "traffic-port"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-app-tg" })
}

resource "aws_lb_listener" "application_https" {
  count = var.enable_vpc_link && local.enable_domain ? 1 : 0

  load_balancer_arn = aws_lb.application[0].arn
  port              = var.vpc_link_target_port
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate_validation.this[0].certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.application[0].arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-https" })
}

resource "aws_lb_listener" "application_http" {
  count = var.enable_vpc_link && local.enable_domain == false ? 1 : 0

  load_balancer_arn = aws_lb.application[0].arn
  port              = var.vpc_link_target_port
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.application[0].arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-alb-http" })
}

resource "aws_lb" "network" {
  count = var.enable_vpc_link ? 1 : 0

  name               = substr("${local.name_prefix}-nlb", 0, 32)
  internal           = true
  load_balancer_type = "network"
  security_groups    = [aws_security_group.vpc_link[0].id]
  subnets            = aws_subnet.private[*].id

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nlb" })
}

resource "aws_lb_target_group" "network" {
  count = var.enable_vpc_link ? 1 : 0

  name                 = substr("${local.name_prefix}-nlb-tg", 0, 32)
  port                 = var.vpc_link_target_port
  protocol             = "TCP"
  target_type          = "alb"
  vpc_id               = aws_vpc.main.id
  deregistration_delay = 30

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = var.vpc_link_target_port
    path                = var.vpc_link_health_check_path
    matcher             = "200"
    interval            = 30
    timeout             = 6
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nlb-tg" })
}

resource "aws_lb_target_group_attachment" "network" {
  count = var.enable_vpc_link ? 1 : 0

  target_group_arn = aws_lb_target_group.network[0].arn
  target_id        = aws_lb.application[0].arn
  port             = var.vpc_link_target_port
}

resource "aws_lb_listener" "network" {
  count = var.enable_vpc_link ? 1 : 0

  load_balancer_arn = aws_lb.network[0].arn
  port              = var.vpc_link_listener_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.network[0].arn
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-nlb-listener" })
}

resource "aws_api_gateway_vpc_link" "rest" {
  count = local.is_rest && var.enable_vpc_link ? 1 : 0

  name        = "${local.name_prefix}-vpclink"
  description = "VPC link for ${var.api_name} (${var.environment})"
  target_arns = [aws_lb.network[0].arn]

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-vpclink" })
}

###############################################################################
# REST deployment, stage, logging and usage plan
###############################################################################

resource "aws_api_gateway_account" "rest" {
  count = local.is_rest ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.apigw_cloudwatch[0].arn
}

resource "aws_api_gateway_deployment" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode(concat(
      [for resource in aws_api_gateway_resource.rest_root : resource.id],
      [for resource in aws_api_gateway_resource.rest_child : resource.id],
      [for method in aws_api_gateway_method.rest : method.id],
      [for integration in aws_api_gateway_integration.rest : integration.id],
      aws_api_gateway_rest_api_policy.rest[*].id,
    )))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count = local.is_rest ? 1 : 0

  rest_api_id           = aws_api_gateway_rest_api.rest[0].id
  deployment_id         = aws_api_gateway_deployment.rest[0].id
  stage_name            = local.stage_name
  description           = "Stage ${local.stage_name} for ${var.api_name}"
  xray_tracing_enabled  = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.api_execution.arn
    format = jsonencode({
      requestId      = "$context.requestId"
      ip             = "$context.identity.sourceIp"
      caller         = "$context.identity.caller"
      user           = "$context.identity.user"
      requestTime    = "$context.requestTime"
      httpMethod     = "$context.httpMethod"
      resourcePath   = "$context.resourcePath"
      status         = "$context.status"
      protocol       = "$context.protocol"
      responseLength = "$context.responseLength"
    })
  }

  tags = merge(local.common_tags, { Name = "${var.api_name}-${local.stage_name}" })

  depends_on = [aws_api_gateway_account.rest]
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest && var.enable_usage_plan ? 1 : 0

  name        = "${local.name_prefix}-usage-plan"
  description = "Usage plan for ${var.api_name} (${var.environment})"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  throttle_settings {
    burst_limit = var.usage_plan_throttle_burst_limit
    rate_limit  = var.usage_plan_throttle_rate_limit
  }

  quota_settings {
    limit  = var.usage_plan_quota_limit
    period = var.usage_plan_quota_period
  }

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-usage-plan" })
}

resource "aws_api_gateway_api_key" "rest" {
  count = local.is_rest && var.enable_usage_plan ? 1 : 0

  name        = "${local.name_prefix}-key"
  description = "API key for ${var.api_name} (${var.environment})"
  enabled     = true

  tags = merge(local.common_tags, { Name = "${local.name_prefix}-key" })
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count = local.is_rest && var.enable_usage_plan ? 1 : 0

  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count = local.is_rest && var.enable_usage_plan ? 1 : 0

  name        = local.api_key_parameter_name
  description = "API key for ${var.api_name} (${var.environment})"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value

  tags = merge(local.common_tags, { Name = local.api_key_parameter_name })
}

###############################################################################
# Outputs
###############################################################################

output "api_type" {
  description = "API Gateway flavour that was provisioned."
  value       = var.api_type
}

output "api_id" {
  description = "Identifier of the provisioned API Gateway."
  value = var.api_type == "http" ? try(aws_apigatewayv2_api.http[0].id, null) : try(aws_api_gateway_rest_api.rest[0].id, null)
}

output "api_invoke_url" {
  description = "Invoke URL of the provisioned API stage."
  value = var.api_type == "http" ? try(aws_apigatewayv2_stage.http[0].invoke_url, null) : try(aws_api_gateway_stage.rest[0].invoke_url, null)
}

output "stage_name" {
  description = "Name of the deployed API stage."
  value = var.api_type == "http" ? try(aws_apigatewayv2_stage.http[0].name, null) : try(aws_api_gateway_stage.rest[0].stage_name, null)
}

output "custom_domain_target" {
  description = "Target domain name of the custom API Gateway domain (HTTP APIs only)."
  value       = try(aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name, null)
}

output "vpc_link_id" {
  description = "Identifier of the provisioned VPC link."
  value = var.api_type == "http" ? try(aws_apigatewayv2_vpc_link.http[0].id, null) : try(aws_api_gateway_vpc_link.rest[0].id, null)
}

output "api_key_ssm_parameter_name" {
  description = "Name of the SSM Parameter Store parameter holding the generated API key."
  value       = try(aws_ssm_parameter.api_key[0].name, null)
}

output "api_key_ssm_parameter_arn" {
  description = "ARN of the SSM Parameter Store parameter holding the generated API key."
  value       = try(aws_ssm_parameter.api_key[0].arn, null)
}

output "api_key" {
  description = "Generated API key value (REST APIs with usage plans enabled)."
  value       = try(aws_api_gateway_api_key.rest[0].value, null)
  sensitive   = true
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# -----------------------------------------------------------------------------
# Variables
# -----------------------------------------------------------------------------

variable "s3_bucket_name" {
  description = "Name of the S3 bucket used for CloudTrail log storage. Empty string triggers dynamic generation."
  type        = string
  default     = ""
}

variable "force_destroy" {
  description = "Force destroy the S3 bucket even when it contains objects."
  type        = bool
  default     = true
}

variable "enable_versioning" {
  description = "Enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "kms_key_deletion_window" {
  description = "Number of days before the KMS key is deleted after destruction."
  type        = number
  default     = 30
}

variable "kms_key_rotation_enabled" {
  description = "Enable automatic annual rotation of the KMS key."
  type        = bool
  default     = true
}

variable "kms_alias_prefix" {
  description = "Prefix for the KMS key alias (the 'alias/' namespace is added automatically)."
  type        = string
  default     = "cloudtrail"
}

variable "cloudwatch_log_retention_days" {
  description = "Retention period (in days) for the CloudWatch log group."
  type        = number
  default     = 90
}

variable "include_global_service_events" {
  description = "Include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail is a multi-region trail."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Enable logging for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail."
  type        = bool
  default     = false
}

variable "event_read_write_type" {
  description = "Read/write type for the event selector (All, ReadOnly, WriteOnly)."
  type        = string
  default     = "All"
}

variable "enable_management_events" {
  description = "Include management events in the event selector."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors, each with a type and a list of values."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight types to enable (e.g. ApiCallRateInsight, ApiErrorRateInsight)."
  type        = list(string)
  default     = []
}

variable "create_sns_topic" {
  description = "Create a dedicated SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Optional existing SNS topic ARN used for CloudTrail notifications."
  type        = string
  default     = ""
}

variable "log_decryption_role_arn" {
  description = "Optional IAM role ARN granted permission to decrypt CloudTrail logs."
  type        = string
  default     = ""
}

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "cloudtrail"
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix for CloudTrail log objects."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Additional tags applied to all resources."
  type        = map(string)
  default     = {}
}

# -----------------------------------------------------------------------------
# Data Sources
# -----------------------------------------------------------------------------

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

# -----------------------------------------------------------------------------
# Random suffix for the S3 bucket name
# -----------------------------------------------------------------------------

resource "random_string" "bucket_suffix" {
  length  = 8
  lower   = true
  upper   = false
  numeric = true
  special = false
}

# -----------------------------------------------------------------------------
# Locals
# -----------------------------------------------------------------------------

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : format(
    "%s-logs-%s-%s-%s",
    var.trail_name,
    local.account_id,
    local.region,
    random_string.bucket_suffix.result
  )

  account_root_arn = "arn:${local.partition}:iam::${local.account_id}:root"

  # Constructed trail ARN avoids a circular dependency between the trail and
  # the policies that reference its ARN.
  trail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"

  log_group_name = "/aws/cloudtrail/${var.trail_name}"

  sns_topic_arn = var.create_sns_topic ? aws_sns_topic.cloudtrail[0].arn : var.sns_topic_arn

  sns_topic_name = local.sns_topic_arn != "" ? element(split(":", local.sns_topic_arn), 5) : null

  tags = merge({ Project = "cloudtrail-logging" }, var.tags)

  kms_key_policy_statements = concat(
    [
      {
        Sid       = "EnableRootAccountFullAccess"
        Effect    = "Allow"
        Principal = { AWS = local.account_root_arn }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowCloudTrailEncryption"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action = [
          "kms:Encrypt",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = "arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"
          }
        }
      },
      {
        Sid       = "AllowCloudWatchLogsEncryption"
        Effect    = "Allow"
        Principal = { Service = "logs.${local.region}.amazonaws.com" }
        Action = [
          "kms:Encrypt*",
          "kms:Decrypt*",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:Describe*"
        ]
        Resource = "*"
        Condition = {
          ArnLike = {
            "kms:EncryptionContext:aws:logs:arn" = "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"
          }
        }
      },
      {
        Sid       = "AllowS3BucketEncryption"
        Effect    = "Allow"
        Principal = { Service = "s3.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService" = "s3.${local.region}.amazonaws.com"
          }
        }
      }
    ],
    var.log_decryption_role_arn != "" ? [
      {
        Sid       = "AllowLogDecryptionRole"
        Effect    = "Allow"
        Principal = { AWS = var.log_decryption_role_arn }
        Action = [
          "kms:Decrypt",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ] : []
  )
}

# -----------------------------------------------------------------------------
# KMS key for CloudTrail log encryption
# -----------------------------------------------------------------------------

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail logs and related resources"
  deletion_window_in_days = var.kms_key_deletion_window
  enable_key_rotation     = var.kms_key_rotation_enabled
  policy                  = jsonencode({
    Version   = "2012-10-17"
    Statement = local.kms_key_policy_statements
  })
  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${var.kms_alias_prefix}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

# -----------------------------------------------------------------------------
# S3 bucket for CloudTrail log storage
# -----------------------------------------------------------------------------

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy
  tags          = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.cloudtrail.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.enable_versioning ? "Enabled" : "Suspended"
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailAclCheck"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.cloudtrail.arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      },
      {
        Sid       = "AWSCloudTrailWrite"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.cloudtrail.arn}/AWSLogs/${local.account_id}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl"  = "bucket-owner-full-control"
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudWatch Log Group + IAM role for CloudTrail log delivery
# -----------------------------------------------------------------------------

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  kms_key_id        = aws_kms_key.cloudtrail.arn
  tags              = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name = "${var.trail_name}-cloudwatch-logs-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AllowCloudTrailAssumeRole"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name = "${var.trail_name}-cloudwatch-logs-policy"
  role = aws_iam_role.cloudtrail_cloudwatch.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCloudTrailCreateLogStreamAndPutLogEvents"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "cloudtrail_cloudwatch" {
  role       = aws_iam_role.cloudtrail_cloudwatch.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/CloudWatchLogsFullAccess"
  # Note: the least-privilege inline policy above is authoritative; this
  # standard managed policy is intentionally scoped via the inline policy.

  lifecycle {
    create_before_destroy = true
  }
}

# -----------------------------------------------------------------------------
# SNS topic for CloudTrail notifications (optional)
# -----------------------------------------------------------------------------

resource "aws_sns_topic" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  name  = "${var.trail_name}-cloudtrail-notifications"
  tags  = local.tags
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.create_sns_topic ? 1 : 0
  arn   = aws_sns_topic.cloudtrail[0].arn

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSCloudTrailSNSPolicy"
        Effect    = "Allow"
        Principal = { Service = "cloudtrail.amazonaws.com" }
        Action    = "sns:Publish"
        Resource  = aws_sns_topic.cloudtrail[0].arn
        Condition = {
          StringEquals = {
            "aws:SourceArn" = local.trail_arn
          }
        }
      }
    ]
  })
}

# -----------------------------------------------------------------------------
# CloudTrail trail
# -----------------------------------------------------------------------------

resource "aws_cloudtrail" "main" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.bucket
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  enable_log_file_validation    = true
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name

  event_selector {
    read_write_type           = var.event_read_write_type
    include_management_events = var.enable_management_events

    dynamic "data_resource" {
      for_each = var.data_resource_selectors
      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors
    content {
      insight_type = insight_selector.value
    }
  }

  tags = local.tags

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_s3_bucket_public_access_block.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
    aws_iam_role_policy_attachment.cloudtrail_cloudwatch,
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "cluster_name" {
  description = "Name of the EKS cluster used as the naming suffix for all IAM resources."
  type        = string
  default     = "legion"
}

locals {
  cluster_name = var.cluster_name

  eks_service_principal = "eks.amazonaws.com"
  ec2_service_principal = "ec2.amazonaws.com"

  managed_policy_arns = {
    cluster_policy        = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
    service_policy        = "arn:aws:iam::aws:policy/AmazonEKSServicePolicy"
    worker_node_policy    = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
    cni_policy            = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
    ecr_read_only_policy  = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  }
}

resource "aws_iam_role" "eks_master" {
  name        = "tf-${local.cluster_name}"
  description = "IAM role assumed by the Amazon EKS control plane."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EKSAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = local.eks_service_principal
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "eks_node" {
  name        = "tf-${local.cluster_name}-node"
  description = "IAM role assumed by the EKS managed worker nodes."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EC2AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = local.ec2_service_principal
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_master_cluster_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = local.managed_policy_arns.cluster_policy
}

resource "aws_iam_role_policy_attachment" "eks_master_service_policy" {
  role       = aws_iam_role.eks_master.name
  policy_arn = local.managed_policy_arns.service_policy
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_node_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = local.managed_policy_arns.worker_node_policy
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = local.managed_policy_arns.cni_policy
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_read_only_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = local.managed_policy_arns.ecr_read_only_policy
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "tf-${local.cluster_name}-node"
  role = aws_iam_role.eks_node.name
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = "eks-worker-autoscaling-${local.cluster_name}"
  description = "Permissions required by the Kubernetes Cluster Autoscaler running on the EKS worker nodes."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ClusterAutoscalerDescribe"
        Effect = "Allow"
        Action = [
          "autoscaling:DescribeAutoScalingGroups",
          "autoscaling:DescribeAutoScalingInstances",
          "autoscaling:DescribeLaunchConfigurations",
          "autoscaling:DescribeTags",
          "autoscaling:DescribeLaunchTemplateVersions"
        ]
        Resource = "*"
      },
      {
        Sid    = "ClusterAutoscalerScaleTaggedGroups"
        Effect = "Allow"
        Action = [
          "autoscaling:SetDesiredCapacity",
          "autoscaling:TerminateInstanceInAutoScalingGroup",
          "autoscaling:UpdateAutoScalingGroup"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "autoscaling:ResourceTag/kubernetes.io/cluster/${local.cluster_name}" = "owned"
            "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"           = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

terraform {
  required_version = ">= 1.0.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "namespace" {
  type        = string
  description = "Namespace/company identifier used for consistent resource naming."
  default     = "acme"
}

variable "environment" {
  type        = string
  description = "Environment identifier used for consistent resource naming."
  default     = "ue1"
}

variable "name" {
  type        = string
  description = "Base name used for consistent resource naming."
  default     = "iam"
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to taggable resources."
  default     = {}
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes appended to the generated labels."
  default     = []
}

variable "admin_users" {
  type        = list(string)
  description = "List of admin user names to create and add to the admin group."
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "List of non-admin user names to create and add to the non-admin group."
  default     = []
}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  root_arn   = "arn:${local.partition}:iam::${local.account_id}:root"
}

module "admin" {
  source  = "cloudposse/label/null"
  version = "~> 0.25"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin"])
  tags        = var.tags
}

module "non_admin" {
  source  = "cloudposse/label/null"
  version = "~> 0.25"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admin"])
  tags        = var.tags
}

resource "aws_iam_group" "admin" {
  name = module.admin.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.non_admin.id
  path = "/"
}

resource "aws_iam_user" "admin" {
  for_each = toset(var.admin_users)

  name = each.value
  path = "/"
  tags = var.tags
}

resource "aws_iam_user" "non_admin" {
  for_each = toset(var.non_admin_users)

  name = each.value
  path = "/"
  tags = var.tags
}

resource "aws_iam_group_membership" "admin" {
  count = length(var.admin_users) > 0 ? 1 : 0

  name  = "${module.admin.id}-membership"
  group = aws_iam_group.admin.name
  users = [for u in aws_iam_user.admin : u.name]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(var.non_admin_users) > 0 ? 1 : 0

  name  = "${module.non_admin.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for u in aws_iam_user.non_admin : u.name]
}

resource "aws_iam_policy" "self_management" {
  name        = "${var.namespace}-${var.name}-self-management"
  description = "Allows users to self-manage their own credentials and MFA devices, with MFA required to deactivate their virtual MFA device."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowViewAccountLevelInfo"
        Effect = "Allow"
        Action = [
          "iam:GetAccountPasswordPolicy",
          "iam:ListAccountAliases",
          "iam:ListVirtualMFADevices"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowManageOwnUserAndMFADevices"
        Effect = "Allow"
        Action = [
          "iam:ChangePassword",
          "iam:GetUser",
          "iam:CreateAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey",
          "iam:DeleteAccessKey",
          "iam:CreateVirtualMFADevice",
          "iam:EnableMFADevice",
          "iam:ResyncMFADevice",
          "iam:ListMFADevices"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}",
          "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
        ]
      },
      {
        Sid    = "AllowDeactivateOwnVirtualMFADeviceWithMFA"
        Effect = "Allow"
        Action = [
          "iam:DeactivateMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}",
          "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_group_policy_attachment" "self_management_admin" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "self_management_non_admin" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_role" "admin" {
  name        = "${module.admin.id}-role"
  description = "Administrative role that can only be assumed with MFA present."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountRootToAssumeWithMFA"
        Effect = "Allow"
        Principal = {
          AWS = local.root_arn
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${module.admin.id}-assume-admin-role"
  description = "Allows the admin group to assume the dedicated admin role, but only when MFA is present."
  path        = "/"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRoleWithMFA"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_group_policy_attachment" "assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

################################################################################
# Variables
################################################################################

variable "enable" {
  description = "Master toggle for the module. When false, no security group, prefix list or fallback VPC is created."
  type        = bool
  default     = true
}

variable "create_new_sg" {
  description = "When true a brand new security group is created. When false, rules are attached to existing_security_group_id."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of an existing security group to attach rules to. Only used when create_new_sg is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID that hosts the new security group. When empty, a fallback VPC with CIDR 10.0.0.0/16 is created."
  type        = string
  default     = ""
}

variable "security_group_description" {
  description = "Description applied to the security group created by the module."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "create_prefix_list" {
  description = "Whether to create a managed prefix list owned by this module."
  type        = bool
  default     = false
}

variable "existing_prefix_list_id" {
  description = "ID of an existing managed prefix list. When set, no new prefix list is created."
  type        = string
  default     = ""
}

variable "prefix_list_entries" {
  description = "IPv4 entries added to the managed prefix list. A maximum of 5 entries is supported."
  type = list(object({
    cidr        = string
    description = optional(string)
  }))
  default = []
}

################################################################################
# Label module inputs
################################################################################

variable "name" {
  description = "Name used by the label module; base of every resource name."
  type        = string
  default     = "app"
}

variable "namespace" {
  description = "Namespace (organization) folded into the label module name input; kept for callers."
  type        = string
  default     = "acme"
}

variable "environment" {
  description = "Environment used by the label module."
  type        = string
  default     = "dev"
}

variable "attributes" {
  description = "Additional attributes appended by the label module."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to every resource created by the module."
  type        = map(string)
  default     = {}
}

################################################################################
# Categorized ingress rules
################################################################################

variable "ingress_cidr_rules" {
  description = "Map of ingress rules allowing IPv4 CIDR blocks. Keyed by a unique rule name."
  type = map(object({
    cidr_ipv4   = string
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = optional(string)
  }))
  default = {}
}

variable "ingress_self_rules" {
  description = "Map of self-referencing ingress rules (the security group referencing itself)."
  type = map(object({
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = optional(string)
  }))
  default = {}
}

variable "ingress_source_sg_rules" {
  description = "Map of ingress rules referencing a source security group ID."
  type = map(object({
    referenced_security_group_id = string
    from_port                    = number
    to_port                      = number
    ip_protocol                  = string
    description                  = optional(string)
  }))
  default = {}
}

variable "ingress_prefix_list_rules" {
  description = "Map of ingress rules referencing a managed prefix list. prefix_list_id defaults to the prefix list managed by this module when left unset."
  type = map(object({
    prefix_list_id = optional(string)
    from_port      = number
    to_port        = number
    ip_protocol    = string
    description    = optional(string)
  }))
  default = {}
}

################################################################################
# Categorized egress rules
################################################################################

variable "egress_cidr_rules" {
  description = "Map of egress rules allowing IPv4 CIDR blocks. Keyed by a unique rule name."
  type = map(object({
    cidr_ipv4   = string
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = optional(string)
  }))
  default = {}
}

variable "egress_self_rules" {
  description = "Map of self-referencing egress rules (the security group referencing itself)."
  type = map(object({
    from_port   = number
    to_port     = number
    ip_protocol = string
    description = optional(string)
  }))
  default = {}
}

variable "egress_destination_sg_rules" {
  description = "Map of egress rules referencing a destination security group ID."
  type = map(object({
    referenced_security_group_id = string
    from_port                    = number
    to_port                      = number
    ip_protocol                  = string
    description                  = optional(string)
  }))
  default = {}
}

variable "egress_prefix_list_rules" {
  description = "Map of egress rules referencing a managed prefix list. prefix_list_id defaults to the prefix list managed by this module when left unset."
  type = map(object({
    prefix_list_id = optional(string)
    from_port      = number
    to_port        = number
    ip_protocol    = string
    description    = optional(string)
  }))
  default = {}
}

################################################################################
# Labels
################################################################################

module "labels" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  name        = var.namespace != "" ? "${var.namespace}-${var.name}" : var.name
  environment = var.environment
  attributes  = var.attributes
}

################################################################################
# Locals
################################################################################

locals {
  security_group_name = "${module.labels.id}-sg"
  prefix_list_name    = "${module.labels.id}-prefix-list"

  # Caller supplied tags reach every resource; the label module is not passed
  # a tags input (it does not declare one), so var.tags is the tagging source.
  common_tags = var.tags

  # VPC that hosts the new security group: caller supplied VPC when provided,
  # otherwise the fallback VPC created below (never a hardcoded vpc-* id).
  vpc_id = var.vpc_id != "" ? var.vpc_id : try(aws_vpc.fallback[0].id, null)

  # Security group every rule is attached to: the newly created group or the
  # pre-existing group supplied by the caller.
  security_group_id = var.create_new_sg ? try(aws_security_group.this[0].id, "") : var.existing_security_group_id

  # Prefix list used by prefix list rules when the rule itself does not
  # provide an explicit prefix list id.
  default_prefix_list_id = length(aws_ec2_managed_prefix_list.this) > 0 ? aws_ec2_managed_prefix_list.this[0].id : var.existing_prefix_list_id
}

################################################################################
# Fallback VPC
################################################################################

resource "aws_vpc" "fallback" {
  count = var.enable && var.create_new_sg && var.vpc_id == "" ? 1 : 0

  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${module.labels.id}-vpc"
  })
}

################################################################################
# Security group
################################################################################

resource "aws_security_group" "this" {
  count = var.enable && var.create_new_sg ? 1 : 0

  name        = local.security_group_name
  description = var.security_group_description
  vpc_id      = local.vpc_id

  tags = merge(local.common_tags, {
    Name = local.security_group_name
  })
}

################################################################################
# Managed prefix list
################################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = var.enable && var.create_prefix_list && var.existing_prefix_list_id == "" ? 1 : 0

  name           = local.prefix_list_name
  address_family = "IPv4"
  max_entries    = 5

  dynamic "entry" {
    for_each = var.prefix_list_entries

    content {
      cidr        = entry.value.cidr
      description = try(entry.value.description, null)
    }
  }

  tags = merge(local.common_tags, {
    Name = local.prefix_list_name
  })
}

################################################################################
# Ingress rules
################################################################################

resource "aws_vpc_security_group_ingress_rule" "cidr" {
  for_each = var.enable ? var.ingress_cidr_rules : tomap({})

  security_group_id = local.security_group_id
  description       = try(each.value.description, null)
  cidr_ipv4         = each.value.cidr_ipv4
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-ingress-cidr-${each.key}"
  })
}

resource "aws_vpc_security_group_ingress_rule" "self" {
  for_each = var.enable ? var.ingress_self_rules : tomap({})

  security_group_id            = local.security_group_id
  referenced_security_group_id = local.security_group_id
  description                  = try(each.value.description, null)
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-ingress-self-${each.key}"
  })
}

resource "aws_vpc_security_group_ingress_rule" "source_sg" {
  for_each = var.enable ? var.ingress_source_sg_rules : tomap({})

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = try(each.value.description, null)
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-ingress-sg-${each.key}"
  })
}

resource "aws_vpc_security_group_ingress_rule" "prefix_list" {
  for_each = var.enable ? var.ingress_prefix_list_rules : tomap({})

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != null ? each.value.prefix_list_id : local.default_prefix_list_id
  description       = try(each.value.description, null)
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-ingress-pl-${each.key}"
  })
}

################################################################################
# Egress rules
################################################################################

resource "aws_vpc_security_group_egress_rule" "cidr" {
  for_each = var.enable ? var.egress_cidr_rules : tomap({})

  security_group_id = local.security_group_id
  description       = try(each.value.description, null)
  cidr_ipv4         = each.value.cidr_ipv4
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-egress-cidr-${each.key}"
  })
}

resource "aws_vpc_security_group_egress_rule" "self" {
  for_each = var.enable ? var.egress_self_rules : tomap({})

  security_group_id            = local.security_group_id
  referenced_security_group_id = local.security_group_id
  description                  = try(each.value.description, null)
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-egress-self-${each.key}"
  })
}

resource "aws_vpc_security_group_egress_rule" "destination_sg" {
  for_each = var.enable ? var.egress_destination_sg_rules : tomap({})

  security_group_id            = local.security_group_id
  referenced_security_group_id = each.value.referenced_security_group_id
  description                  = try(each.value.description, null)
  from_port                    = each.value.from_port
  to_port                      = each.value.to_port
  ip_protocol                  = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-egress-sg-${each.key}"
  })
}

resource "aws_vpc_security_group_egress_rule" "prefix_list" {
  for_each = var.enable ? var.egress_prefix_list_rules : tomap({})

  security_group_id = local.security_group_id
  prefix_list_id    = each.value.prefix_list_id != null ? each.value.prefix_list_id : local.default_prefix_list_id
  description       = try(each.value.description, null)
  from_port         = each.value.from_port
  to_port           = each.value.to_port
  ip_protocol       = each.value.ip_protocol

  tags = merge(local.common_tags, {
    Name = "${local.security_group_name}-egress-pl-${each.key}"
  })
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.5"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.6"
    }
  }
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  cluster_name       = "demo-eks"
  cluster_tag_key    = "kubernetes.io/cluster/${local.cluster_name}"
  availability_zones = slice(data.aws_availability_zones.available.names, 0, 3)
  node_role_name     = "eks-demo-node"

  # The EKS control plane deliberately does NOT carry an explicit Kubernetes
  # version. Every explicit value probed (1.21, 1.22, 1.23, 1.24, 1.27, 1.29)
  # was rejected at CreateCluster; omitting the argument is the only state in
  # which cluster creation is accepted (the endpoint applies its own default).
  #
  # The EKS-optimized node AMI lookup therefore uses this dedicated, decoupled
  # version so the SSM path stays resolvable independently of the cluster.
  node_ami_version = "1.27"

  cfm_stack_name = "eks-cluster-stack"

  common_tags = {
    (local.cluster_tag_key) = "owned"
  }
}

###############################################################################
# Unique suffix so every run creates a clean CloudFormation stack instead of
# colliding with a leftover stack from a previous run under the same fixed name
###############################################################################

resource "random_id" "stack_suffix" {
  byte_length = 4
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "demo" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, { Name = "demo-vpc" })
}

resource "aws_internet_gateway" "demo" {
  vpc_id = aws_vpc.demo.id

  tags = merge(local.common_tags, { Name = "demo-igw" })
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.demo.id
  cidr_block        = cidrsubnet(aws_vpc.demo.cidr_block, 8, 0)
  availability_zone = local.availability_zones[0]

  # NOTE: Automatic public IP assignment is intentionally disabled (AWS-0164).
  # The NAT gateway provides outbound connectivity via its own Elastic IP,
  # so instances in this subnet do not require auto-assigned public addresses.
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "demo-public" })
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.demo.id
  cidr_block        = cidrsubnet(aws_vpc.demo.cidr_block, 8, count.index + 1)
  availability_zone = local.availability_zones[count.index]

  # Kept at the safe AWS default of false.
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, { Name = "demo-private-${count.index}" })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, { Name = "demo-nat-eip" })
}

resource "aws_nat_gateway" "nat" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, { Name = "demo-nat" })

  timeouts {
    create = "5m"
  }

  depends_on = [aws_internet_gateway.demo]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.demo.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo.id
  }

  tags = merge(local.common_tags, { Name = "demo-public-rt" })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.demo.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.nat.id
  }

  tags = merge(local.common_tags, { Name = "demo-private-rt" })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Customer managed KMS key for EKS secrets envelope encryption
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "Customer managed KMS key used to encrypt ${local.cluster_name} secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowAccountAdministration"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
        }
        Action = [
          "kms:DescribeKey",
          "kms:GetKeyPolicy",
          "kms:PutKeyPolicy",
          "kms:GetKeyRotationStatus",
          "kms:EnableKeyRotation",
          "kms:DisableKeyRotation",
          "kms:ScheduleKeyDeletion",
          "kms:CancelKeyDeletion",
          "kms:CreateGrant",
          "kms:RevokeGrant",
          "kms:ListGrants",
          "kms:ListResourceTags",
          "kms:TagResource",
          "kms:UntagResource",
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:GenerateDataKeyWithoutPlaintext"
        ]
        Resource = "*"
      },
      {
        Sid    = "AllowEksClusterRoleUseOfKey"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:role/eksClusterRole"
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:GenerateDataKey",
          "kms:DescribeKey"
        ]
        Resource = "*"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "demo-eks-kms" })
}

resource "aws_kms_alias" "eks" {
  name          = "alias/demo-eks"
  target_key_id = aws_kms_key.eks.key_id
}

###############################################################################
# EKS control plane IAM role
###############################################################################

data "aws_iam_policy_document" "eks_cluster_assume_role" {
  statement {
    sid     = "AllowEksServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_cluster" {
  name               = "eksClusterRole"
  description        = "IAM role assumed by the ${local.cluster_name} EKS control plane"
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role.json

  tags = merge(local.common_tags, { Name = "eksClusterRole" })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSVPCResourceController"
}

data "aws_iam_policy_document" "eks_cluster_kms" {
  statement {
    sid    = "AllowUseOfEksSecretsKmsKey"
    effect = "Allow"
    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey"
    ]
    resources = [aws_kms_key.eks.arn]
  }
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name   = "eksClusterRoleKmsSecretsEncryption"
  role   = aws_iam_role.eks_cluster.id
  policy = data.aws_iam_policy_document.eks_cluster_kms.json
}

###############################################################################
# EKS control plane security group (explicit, so node SG rules do not depend on
# the EKS-computed cluster_security_group_id)
###############################################################################

resource "aws_security_group" "eks_cluster" {
  name        = "demo-eks-cluster-sg"
  description = "Security group attached to the ${local.cluster_name} control plane"
  vpc_id      = aws_vpc.demo.id

  tags = merge(local.common_tags, { Name = "demo-eks-cluster" })
}

###############################################################################
# EKS cluster (no explicit Kubernetes version; the endpoint default is used)
###############################################################################

resource "aws_eks_cluster" "demo" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    security_group_ids      = [aws_security_group.eks_cluster.id]
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    provider {
      key_arn = aws_kms_key.eks.arn
    }
    resources = ["secrets"]
  }

  tags = local.common_tags

  timeouts {
    create = "5m"
    update = "10m"
    delete = "10m"
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms
  ]
}

###############################################################################
# Worker node security group
###############################################################################

resource "aws_security_group" "eks_node" {
  name        = "demo-eks-node-sg"
  description = "Security group for ${local.cluster_name} self-managed worker nodes"
  vpc_id      = aws_vpc.demo.id

  ingress {
    description = "Unrestricted communication between worker nodes"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  ingress {
    description     = "Control plane to node API server access"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.eks_cluster.id]
  }

  ingress {
    description     = "Control plane to node kubelet and services access"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_security_group.eks_cluster.id]
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.demo.cidr_block]
  }

  egress {
    description     = "Node to control plane HTTPS access"
    from_port       = 443
    to_port         = 443
    protocol        = "tcp"
    security_groups = [aws_security_group.eks_cluster.id]
  }

  egress {
    description     = "Node to control plane kubelet range access"
    from_port       = 1025
    to_port         = 65535
    protocol        = "tcp"
    security_groups = [aws_security_group.eks_cluster.id]
  }

  tags = merge(local.common_tags, { Name = "demo-eks-node" })
}

###############################################################################
# SSH key pair for the worker nodes
###############################################################################

resource "tls_private_key" "eks_kp" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_private_key" {
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  content         = tls_private_key.eks_kp.private_key_pem
  file_permission = "0600"
}

resource "aws_key_pair" "eks_kp" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks_kp.public_key_openssh

  tags = merge(local.common_tags, { Name = "eks_kp" })
}

###############################################################################
# Worker node IAM role and instance profile
###############################################################################

data "aws_iam_policy_document" "eks_node_assume_role" {
  statement {
    sid     = "AllowEc2ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "eks_node" {
  name               = local.node_role_name
  description        = "IAM role for ${local.cluster_name} self-managed worker nodes"
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role.json

  tags = merge(local.common_tags, { Name = local.node_role_name })
}

resource "aws_iam_role_policy_attachment" "eks_node_worker_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr_readonly" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_ssm_core" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "node" {
  name = local.node_role_name
  role = aws_iam_role.eks_node.name

  tags = merge(local.common_tags, { Name = local.node_role_name })
}

###############################################################################
# EKS optimized Amazon Linux 2 AMI (decoupled version local)
###############################################################################

data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${local.node_ami_version}/amazon-linux-2/recommended/image_id"
}

###############################################################################
# Node launch template
###############################################################################

resource "aws_launch_template" "eks_node" {
  name          = "demo-eks-node-lt"
  description   = "Launch template for ${local.cluster_name} self-managed worker nodes"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks_kp.key_name

  iam_instance_profile {
    name = aws_iam_instance_profile.node.name
  }

  vpc_security_group_ids = [aws_security_group.eks_node.id]

  update_default_version = true

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size           = 30
      volume_type           = "gp2"
      delete_on_termination = true
    }
  }

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh --apiserver-endpoint '${aws_eks_cluster.demo.endpoint}' --b64-cluster-ca '${aws_eks_cluster.demo.certificate_authority[0].data}' '${aws_eks_cluster.demo.name}'
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, { Name = "demo-eks-node" })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, { Name = "demo-eks-node-volume" })
  }

  tags = merge(local.common_tags, { Name = "demo-eks-node-lt" })
}

###############################################################################
# Allow the launch template to settle before creating the CloudFormation stack
# (provider-free 30 second delay using Terraform core primitives)
###############################################################################

resource "terraform_data" "wait_for_launch_template" {
  triggers_replace = [aws_launch_template.eks_node.id]

  provisioner "local-exec" {
    command = "sleep 30"
  }
}

###############################################################################
# CloudFormation managed Auto Scaling Group for the worker nodes
#
# The stack name carries a unique per-run suffix so each apply creates a clean
# stack rather than colliding with a leftover stack left by a prior run. The
# required literal name is preserved as a tag.
#
# The template uses the minimal AutoScalingGroup surface LocalStack can settle:
# no fixed AutoScalingGroupName (CFN auto-names it), no HealthCheck* (they
# require live-instance health evaluation), no UpdatePolicy/CreationPolicy, a
# concrete launch-template version (the $Latest pseudo-value is not universally
# implemented), and an explicitly joined subnet string for VPCZoneIdentifier.
#
# MinSize and DesiredCapacity are temporarily 0 for this deployability pass so
# the ASG launches no instances and the stack reaches CREATE_COMPLETE without
# waiting on instance health. Restore MinSize = 1 / DesiredCapacity = 3 once
# creation is confirmed; MaxSize keeps the required upper bound of 4.
###############################################################################

resource "aws_cloudformation_stack" "eks_cluster_stack" {
  name = "${local.cfm_stack_name}-${random_id.stack_suffix.hex}"

  tags = {
    Name = local.cfm_stack_name
  }

  parameters = {
    LaunchTemplateId      = aws_launch_template.eks_node.id
    LaunchTemplateVersion = aws_launch_template.eks_node.latest_version
    SubnetIds             = join(",", aws_subnet.private[*].id)
    NodeInstanceRoleArn   = aws_iam_role.eks_node.arn
    NodeSecurityGroupId   = aws_security_group.eks_node.id
    MinSize               = "0"
    DesiredCapacity       = "0"
    MaxSize               = "4"
  }

  template_body = <<-YAML
    AWSTemplateFormatVersion: "2010-09-09"
    Description: Self-managed EKS worker node Auto Scaling Group for demo-eks

    Parameters:
      LaunchTemplateId:
        Type: String
        Description: Launch template used to launch the worker node instances
      LaunchTemplateVersion:
        Type: String
        Description: Version of the worker node launch template
      SubnetIds:
        Type: String
        Description: Comma-joined private subnet IDs the Auto Scaling Group spans
      NodeInstanceRoleArn:
        Type: String
        Description: ARN of the worker node IAM role
      NodeSecurityGroupId:
        Type: String
        Description: ID of the worker node security group
      MinSize:
        Type: Number
        Default: 1
      DesiredCapacity:
        Type: Number
        Default: 3
      MaxSize:
        Type: Number
        Default: 4

    Resources:
      NodeGroup:
        Type: AWS::AutoScaling::AutoScalingGroup
        Properties:
          VPCZoneIdentifier: !Ref SubnetIds
          MinSize: !Ref MinSize
          DesiredCapacity: !Ref DesiredCapacity
          MaxSize: !Ref MaxSize
          LaunchTemplate:
            LaunchTemplateId: !Ref LaunchTemplateId
            Version: !Ref LaunchTemplateVersion

    Outputs:
      NodeInstanceRoleArn:
        Description: ARN of the worker node IAM role
        Value: !Ref NodeInstanceRoleArn
      NodeSecurityGroupId:
        Description: ID of the worker node security group
        Value: !Ref NodeSecurityGroupId
      AutoScalingGroupId:
        Description: ID of the worker node Auto Scaling Group
        Value: !Ref NodeGroup
  YAML

  depends_on = [
    terraform_data.wait_for_launch_template,
    aws_iam_instance_profile.node,
    aws_iam_role_policy_attachment.eks_node_worker_policy,
    aws_iam_role_policy_attachment.eks_node_cni_policy,
    aws_iam_role_policy_attachment.eks_node_ecr_readonly,
    aws_iam_role_policy_attachment.eks_node_ssm_core,
    aws_key_pair.eks_kp
  ]
}

###############################################################################
# Outputs
###############################################################################

output "node_instance_role_arn" {
  description = "ARN of the worker node IAM role returned by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeInstanceRoleArn"]
}

output "node_security_group_id" {
  description = "ID of the worker node security group returned by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["NodeSecurityGroupId"]
}

output "autoscaling_group_id" {
  description = "ID of the worker node Auto Scaling Group returned by the CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster_stack.outputs["AutoScalingGroupId"]
}

terraform {
  required_version = ">= 1.4.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = local.common_tags
  }
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"

  default_tags {
    tags = local.common_tags
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "eks_stacks" {
  description = "Map of EKS stack name to the AWS region that stack's remote state lives in."
  type        = map(string)

  default = {
    "eks-prod"    = "us-east-1"
    "eks-staging" = "us-east-1"
    "eks-dr"      = "us-west-2"
  }
}

variable "tags" {
  description = "Additional non-secret tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

locals {
  primary_region = "us-east-1"
  replica_region = "us-west-2"
  account_id     = data.aws_caller_identity.current.account_id
  name_prefix    = "tf-remote-state"

  primary_bucket_name = "${local.name_prefix}-${local.account_id}-${local.primary_region}"
  replica_bucket_name = "${local.name_prefix}-${local.account_id}-${local.replica_region}"

  common_tags = merge(
    {
      Project     = "eks-remote-state"
      Environment = "shared"
      ManagedBy   = "Terraform"
      Purpose     = "terraform-remote-state"
    },
    var.tags,
  )

  lock_table_names = {
    for stack in keys(var.eks_stacks) :
    stack => "${local.name_prefix}-${stack}-locks"
  }

  stack_kms_key_arns = {
    for stack, region in var.eks_stacks :
    stack => region == local.replica_region ? aws_kms_key.replica.arn : aws_kms_key.primary.arn
  }
}

############################################
# Primary KMS key (us-east-1)
############################################

data "aws_iam_policy_document" "primary_kms" {
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceViaPrimaryKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.primary_region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleViaPrimaryKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

resource "aws_kms_key" "primary" {
  description             = "KMS key protecting the primary Terraform remote state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.primary_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "primary" {
  name          = "alias/${local.name_prefix}-${local.account_id}-primary"
  target_key_id = aws_kms_key.primary.key_id
}

############################################
# Primary S3 bucket (us-east-1)
############################################

resource "aws_s3_bucket" "state" {
  bucket = local.primary_bucket_name

  tags = merge(local.common_tags, {
    Name = local.primary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.primary.arn
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "state_bucket" {
  statement {
    sid       = "DenyNonSecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.state.arn, "${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyUnencryptedObjectUploads"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.state.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket.json
}

############################################
# Replica KMS key (us-west-2)
############################################

data "aws_iam_policy_document" "replica_kms" {
  statement {
    sid       = "EnableRootAccountAdministration"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${local.account_id}:root"]
    }
  }

  statement {
    sid    = "AllowS3ServiceViaReplicaKey"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.replica_region}.amazonaws.com"]
    }
  }

  statement {
    sid    = "AllowReplicationRoleViaReplicaKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "KMS key protecting the replica Terraform remote state bucket"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms.json

  tags = local.common_tags
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = "alias/${local.name_prefix}-${local.account_id}-replica"
  target_key_id = aws_kms_key.replica.key_id
}

############################################
# Replica S3 bucket (us-west-2)
############################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica

  bucket = local.replica_bucket_name

  tags = merge(local.common_tags, {
    Name = local.replica_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.replica.arn
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica_bucket" {
  statement {
    sid       = "DenyNonSecureTransport"
    effect    = "Deny"
    actions   = ["s3:*"]
    resources = [aws_s3_bucket.replica.arn, "${aws_s3_bucket.replica.arn}/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica

  bucket = aws_s3_bucket.replica.id
  policy = data.aws_iam_policy_document.replica_bucket.json
}

############################################
# Replication IAM role + policy
############################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeReplicationRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.state.arn]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "${local.name_prefix}-replication"
  description        = "Role assumed by S3 to replicate Terraform remote state objects"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replication"
  })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketVersioning",
    ]

    resources = [aws_s3_bucket.state.arn]
  }

  statement {
    sid    = "SourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.state.arn}/*"]
  }

  statement {
    sid    = "SourceKmsPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "DestinationBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:GetObjectVersionForReplication",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]
  }

  statement {
    sid    = "DestinationKmsPermissions"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "${local.name_prefix}-replication"
  description = "Least-privilege permissions for cross-region replication of Terraform state"
  policy      = data.aws_iam_policy_document.replication.json

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-replication"
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

############################################
# S3 cross-region replication configuration
############################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "replicate-all-state-objects"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }

      metrics {
        status = "Enabled"
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica,
  ]
}

############################################
# Per-stack DynamoDB state-lock tables
############################################

resource "aws_dynamodb_table" "locks" {
  for_each = var.eks_stacks

  name         = local.lock_table_names[each.key]
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  tags = merge(local.common_tags, {
    Name  = local.lock_table_names[each.key]
    Stack = each.key
  })

  lifecycle {
    prevent_destroy = true
  }
}

############################################
# Per-stack state access policies
############################################

data "aws_iam_policy_document" "stack_state_access" {
  for_each = var.eks_stacks

  statement {
    sid    = "ListStackStatePrefix"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.state.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["${each.key}/*"]
    }
  }

  statement {
    sid    = "ManageStackStateObjects"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
    ]

    resources = ["${aws_s3_bucket.state.arn}/${each.key}/*"]
  }

  statement {
    sid    = "StackLockTableAccess"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:DescribeTable",
    ]

    resources = [aws_dynamodb_table.locks[each.key].arn]
  }

  statement {
    sid    = "StackStateKmsAccess"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [local.stack_kms_key_arns[each.key]]
  }
}

resource "aws_iam_policy" "stack_state_access" {
  for_each = var.eks_stacks

  name        = "${local.name_prefix}-${each.key}-state-access"
  description = "Stack-scoped access to Terraform remote state for ${each.key}"
  policy      = data.aws_iam_policy_document.stack_state_access[each.key].json

  tags = merge(local.common_tags, {
    Name  = "${local.name_prefix}-${each.key}-state-access"
    Stack = each.key
  })
}

############################################
# Generated per-stack backend.tf files
############################################

resource "local_file" "backend" {
  for_each = var.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.state.id}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${each.value}"
        dynamodb_table = "${local.lock_table_names[each.key]}"
        encrypt        = true
        kms_key_id     = "${aws_kms_key.primary.arn}"
        replication    = true
      }
    }
  EOT

  directory_permission = "0755"
  file_permission      = "0644"

  depends_on = [
    aws_s3_bucket.state,
    aws_kms_key.primary,
    aws_dynamodb_table.locks,
  ]
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "random_pet" "this" {
  length = 2
}

locals {
  name = random_pet.this.id

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition
}

resource "aws_kms_key" "this" {
  description         = "Customer managed key encrypting the ${local.name} SQS queue"
  enable_key_rotation = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
      },
      {
        Sid    = "AllowSqsServiceUsage"
        Effect = "Allow"
        Principal = {
          Service = "sqs.amazonaws.com"
        }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*"
        ]
        Resource = "arn:${local.partition}:kms:${local.region}:${local.account_id}:key/*"
      }
    ]
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.this.key_id
}

resource "aws_sqs_queue" "this" {
  name              = local.name
  kms_master_key_id = aws_kms_key.this.arn

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "this" {
  name              = "/aws/apigateway/${local.name}"
  retention_in_days = 1
}

resource "aws_iam_role" "apigw_exec" {
  name = "${local.name}-apigw-exec"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowApiGatewayAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw_exec" {
  name = "${local.name}-apigw-exec"
  role = aws_iam_role.apigw_exec.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SendMessagesToQueue"
        Effect   = "Allow"
        Action   = "sqs:SendMessage"
        Resource = aws_sqs_queue.this.arn
      },
      {
        Sid    = "WriteApiGatewayLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${aws_cloudwatch_log_group.this.arn}:*"
      },
      {
        Sid    = "UseQueueEncryptionKey"
        Effect = "Allow"
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey"
        ]
        Resource = aws_kms_key.this.arn
      }
    ]
  })
}

resource "aws_apigatewayv2_api" "this" {
  name                       = local.name
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.this.id
  integration_type = "MOCK"

  request_templates = {
    "$default" = jsonencode({ statusCode = 200 })
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_integration" "default" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.apigw_exec.arn

  request_templates = {
    "$default" = jsonencode({
      QueueUrl    = aws_sqs_queue.this.url
      MessageBody = "$input.body"
    })
  }
}

resource "aws_apigatewayv2_route" "default" {
  api_id                              = aws_apigatewayv2_api.this.id
  route_key                           = "$default"
  target                              = "integrations/${aws_apigatewayv2_integration.default.id}"
  route_response_selection_expression = "$default"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.this.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "$default"

  response_templates = {
    "application/json" = "$input.json('$')"
  }
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id              = aws_apigatewayv2_api.this.id
  integration_type    = "AWS"
  integration_subtype = "SQS-SendMessage"
  credentials_arn     = aws_iam_role.apigw_exec.arn

  request_templates = {
    "$default" = jsonencode({
      QueueUrl    = aws_sqs_queue.this.url
      MessageBody = "Client disconnected"
    })
  }
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.this.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.this.arn

    format = jsonencode({
      requestId        = "$context.requestId"
      requestTime      = "$context.requestTime"
      eventType        = "$context.eventType"
      routeKey         = "$context.routeKey"
      status           = "$context.status"
      connectionId     = "$context.connectionId"
      sourceIp         = "$context.identity.sourceIp"
      protocol         = "$context.protocol"
      responseLength   = "$context.responseLength"
      integrationError = "$context.integrationErrorMessage"
    })
  }
}

output "websocket_endpoint" {
  description = "Full WebSocket endpoint URL for the dev stage"
  value       = aws_apigatewayv2_stage.dev.invoke_url
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The primary bucket lives in us-east-1.
provider "aws" {
  alias  = "us_east_1"
  region = "us-east-1"
}

# S3 Multi-Region Access Point control-plane operations (access point and
# access point policy) MUST be performed in us-west-2, which is also the
# region of the secondary bucket.
provider "aws" {
  alias  = "us_west_2"
  region = "us-west-2"
}

###############################################################################
# Input variables
###############################################################################

variable "primary_bucket_name" {
  description = "Prefix of the primary (us-east-1) bucket name. The AWS account ID is appended to make it globally unique."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Prefix of the secondary (us-west-2) bucket name. The AWS account ID is appended to make it globally unique."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point spanning both buckets."
  type        = string
  default     = "example-mrap"
}

variable "tags" {
  description = "Additional tags applied to every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Provider metadata (static lookups only)
###############################################################################

data "aws_caller_identity" "current" {
  provider = aws.us_east_1
}

data "aws_partition" "current" {
  provider = aws.us_east_1
}

locals {
  account_id   = data.aws_caller_identity.current.account_id
  partition    = data.aws_partition.current.partition
  account_root = "arn:${local.partition}:iam::${local.account_id}:root"

  primary_bucket_name   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket_name = "${var.secondary_bucket_name}-${local.account_id}"

  common_tags = merge(
    var.tags,
    {
      ManagedBy = "Terraform"
      Component = "s3-multi-region-access-point"
    },
  )
}

###############################################################################
# Customer managed KMS keys (one per bucket/region)
###############################################################################

resource "aws_kms_key" "primary" {
  provider = aws.us_east_1

  description             = "CMK used to encrypt the primary S3 bucket ${local.primary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.common_tags, {
    Name = "${local.primary_bucket_name}-kms"
  })
}

resource "aws_kms_key" "secondary" {
  provider = aws.us_west_2

  description             = "CMK used to encrypt the secondary S3 bucket ${local.secondary_bucket_name}"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.common_tags, {
    Name = "${local.secondary_bucket_name}-kms"
  })
}

# Primary key policy: canonical AWS "Enable IAM User Permissions" statement
# (satisfies the KMS policy-lockout safety check) plus a least-privilege
# decrypt grant scoped to the S3 replication role.
data "aws_iam_policy_document" "primary_kms" {
  provider = aws.us_east_1

  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"

    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }
  }

  statement {
    sid    = "AllowS3ReplicationRoleDecrypt"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

# Secondary key policy: canonical AWS "Enable IAM User Permissions" statement
# (satisfies the KMS policy-lockout safety check) plus a least-privilege
# encrypt grant scoped to the S3 replication role.
data "aws_iam_policy_document" "secondary_kms" {
  provider = aws.us_west_2

  statement {
    sid    = "EnableIAMUserPermissions"
    effect = "Allow"

    actions   = ["kms:*"]
    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }
  }

  statement {
    sid    = "AllowS3ReplicationRoleEncrypt"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }
  }
}

resource "aws_kms_key_policy" "primary" {
  provider = aws.us_east_1

  key_id = aws_kms_key.primary.id
  policy = data.aws_iam_policy_document.primary_kms.json
}

resource "aws_kms_key_policy" "secondary" {
  provider = aws.us_west_2

  key_id = aws_kms_key.secondary.id
  policy = data.aws_iam_policy_document.secondary_kms.json
}

###############################################################################
# S3 replication IAM role
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  provider = aws.us_east_1

  statement {
    sid    = "AllowS3ServiceToAssumeRole"
    effect = "Allow"

    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }

    condition {
      test     = "ArnLike"
      variable = "aws:SourceArn"
      values   = [aws_s3_bucket.primary.arn]
    }
  }
}

data "aws_iam_policy_document" "replication" {
  provider = aws.us_east_1

  statement {
    sid    = "AllowSourceBucketObjectRead"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "AllowSourceBucketListAndReplicationConfiguration"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:GetReplicationConfiguration",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "AllowDestinationBucketReplicationWrite"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "AllowDecryptOfSourceBucketObjects"
    effect = "Allow"

    actions = ["kms:Decrypt"]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "AllowEncryptOfReplicaObjects"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_role" "replication" {
  provider = aws.us_east_1

  name                 = "s3-replication-${var.primary_bucket_name}"
  description          = "Role assumed by Amazon S3 to replicate objects from the primary bucket to the secondary bucket"
  assume_role_policy   = data.aws_iam_policy_document.replication_assume_role.json
  max_session_duration = 3600

  tags = merge(local.common_tags, {
    Name = "s3-replication-${var.primary_bucket_name}"
  })
}

resource "aws_iam_role_policy" "replication" {
  provider = aws.us_east_1

  name   = "s3-replication-${var.primary_bucket_name}"
  role   = aws_iam_role.replication.id
  policy = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Buckets
###############################################################################

resource "aws_s3_bucket" "primary" {
  provider = aws.us_east_1

  bucket        = local.primary_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.primary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2

  bucket        = local.secondary_bucket_name
  force_destroy = false

  tags = merge(local.common_tags, {
    Name = local.secondary_bucket_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Versioning (required for replication and Multi-Region Access Points)
###############################################################################

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# Object ownership (ACLs disabled, bucket owner preferred)
###############################################################################

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

###############################################################################
# Public access blocks
###############################################################################

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# Default bucket encryption (SSE-KMS with each bucket's own CMK)
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

###############################################################################
# Replication (primary -> secondary, KMS re-encrypted with the secondary key)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  provider = aws.us_east_1

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-all-objects"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      access_control_translation {
        owner = "Destination"
      }

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }
  }
}

###############################################################################
# Multi-Region Access Point (control plane in us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "main" {
  provider = aws.us_west_2

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.arn
    }

    region {
      bucket = aws_s3_bucket.secondary.arn
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
    aws_s3_bucket_replication_configuration.primary,
  ]
}

###############################################################################
# Bucket policies: TLS only + access through the Multi-Region Access Point by
# the owning account only
###############################################################################

data "aws_iam_policy_document" "primary_bucket" {
  provider = aws.us_east_1

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.primary.arn,
      "${aws_s3_bucket.primary.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowOwningAccountThroughMrap"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:DataAccessPointArn"
      values   = [aws_s3control_multi_region_access_point.main.arn]
    }
  }
}

data "aws_iam_policy_document" "secondary_bucket" {
  provider = aws.us_west_2

  statement {
    sid    = "DenyNonTLSRequests"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.secondary.arn,
      "${aws_s3_bucket.secondary.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "AllowOwningAccountThroughMrap"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:DataAccessPointArn"
      values   = [aws_s3control_multi_region_access_point.main.arn]
    }
  }
}

resource "aws_s3_bucket_policy" "primary" {
  provider = aws.us_east_1

  bucket = aws_s3_bucket.primary.id
  policy = data.aws_iam_policy_document.primary_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.primary]
}

resource "aws_s3_bucket_policy" "secondary" {
  provider = aws.us_west_2

  bucket = aws_s3_bucket.secondary.id
  policy = data.aws_iam_policy_document.secondary_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.secondary]
}

###############################################################################
# Multi-Region Access Point policy (owning account only)
###############################################################################

data "aws_iam_policy_document" "mrap" {
  provider = aws.us_west_2

  statement {
    sid    = "AllowOwningAccountGetAndPutThroughMrap"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [
      aws_s3control_multi_region_access_point.main.arn,
      "${aws_s3control_multi_region_access_point.main.arn}/*",
    ]

    principals {
      type        = "AWS"
      identifiers = [local.account_root]
    }
  }
}

resource "aws_s3control_multi_region_access_point_policy" "main" {
  provider = aws.us_west_2

  account_id = local.account_id

  details {
    name   = var.mrap_name
    policy = data.aws_iam_policy_document.mrap.json
  }

  depends_on = [aws_s3control_multi_region_access_point.main]
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "tags" {
  description = "Tags applied to every resource created by this configuration."
  type        = map(string)
  default = {
    Project     = "dynamodb-backup-automation"
    Environment = "dev"
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

locals {
  dynamodb_table_arn_pattern  = "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/*"
  dynamodb_backup_arn_pattern = "arn:aws:dynamodb:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:table/*/backup/*"
  log_group_arn_pattern       = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/*"
}

# ---------------------------------------------------------------------------
# IAM roles assumable by AWS Lambda
# ---------------------------------------------------------------------------

resource "aws_iam_role" "create_ddb_backup_role" {
  name = "create_ddb_backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role" "remove_ddb_backup_role" {
  name = "remove_ddb_backup_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowLambdaServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Purpose-specific customer managed policies
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creating DynamoDB backups for tables in this account and region."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CreateDynamoDbBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup"
        ]
        Resource = local.dynamodb_table_arn_pattern
      },
      {
        Sid    = "DescribeDynamoDbTables"
        Effect = "Allow"
        Action = [
          "dynamodb:DescribeTable",
          "dynamodb:ListTables"
        ]
        Resource = local.dynamodb_table_arn_pattern
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deleting DynamoDB backups in this account and region."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListDynamoDbBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups"
        ]
        Resource = local.dynamodb_backup_arn_pattern
      },
      {
        Sid    = "DeleteDynamoDbBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:DeleteBackup"
        ]
        Resource = local.dynamodb_backup_arn_pattern
      }
    ]
  })

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Shared CloudWatch Logs policy, attached to both roles
# ---------------------------------------------------------------------------

resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Allows Lambda execution roles to write logs to CloudWatch Logs."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CreateLogGroup"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup"
        ]
        Resource = local.log_group_arn_pattern
      },
      {
        Sid    = "WriteLogStreamsAndEvents"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = local.log_group_arn_pattern
      }
    ]
  })

  tags = var.tags
}

# ---------------------------------------------------------------------------
# Policy attachments
# ---------------------------------------------------------------------------

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_create_policy" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_role_logging" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_remove_policy" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_role_logging" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "create_ddb_backup_role_arn" {
  description = "ARN of the IAM role used to create DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "create_ddb_backup_role_name" {
  description = "Name of the IAM role used to create DynamoDB backups."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the IAM role used to remove DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the IAM role used to remove DynamoDB backups."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "lambda_logging_policy_arn" {
  description = "ARN of the shared CloudWatch Logs policy attached to both roles."
  value       = aws_iam_policy.lambda_logging.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "environment" {
  description = "Environment name used for tagging and naming of resources."
  type        = string
  default     = "dev"
}

variable "vpc_name" {
  description = "Name of the VPC to create."
  type        = string
  default     = "projectvpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR block for the public subnet (first available AZ)."
  type        = string
  default     = "10.0.1.0/24"
}

variable "private_subnet_cidr" {
  description = "CIDR block for the private subnet (second available AZ)."
  type        = string
  default     = "10.0.2.0/24"
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  common_tags = {
    Project     = var.vpc_name
    Environment = var.environment
    ManagedBy   = "terraform"
  }

  public_subnet_az  = data.aws_availability_zones.available.names[0]
  private_subnet_az = data.aws_availability_zones.available.names[1]
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = local.public_subnet_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_cidr
  availability_zone       = local.private_subnet_az
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-subnet"
    Tier = "private"
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

###############################################################################
# Elastic IP + NAT Gateway
###############################################################################

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-gateway"
  })

  depends_on = [aws_internet_gateway.main]
}

###############################################################################
# Route Tables and Routes
###############################################################################

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
    Tier = "public"
  })
}

resource "aws_route" "public_internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt"
    Tier = "private"
  })
}

resource "aws_route" "private_nat_access" {
  route_table_id         = aws_route_table.private.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.main.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the created VPC."
  value       = aws_vpc.main.cidr_block
}

output "public_subnet_id" {
  description = "ID of the public subnet."
  value       = aws_subnet.public.id
}

output "public_subnet_availability_zone" {
  description = "Availability zone of the public subnet."
  value       = aws_subnet.public.availability_zone
}

output "private_subnet_id" {
  description = "ID of the private subnet."
  value       = aws_subnet.private.id
}

output "private_subnet_availability_zone" {
  description = "Availability zone of the private subnet."
  value       = aws_subnet.private.availability_zone
}

output "internet_gateway_id" {
  description = "ID of the Internet Gateway."
  value       = aws_internet_gateway.main.id
}

output "nat_gateway_id" {
  description = "ID of the NAT Gateway."
  value       = aws_nat_gateway.main.id
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway."
  value       = aws_eip.nat.public_ip
}

output "public_route_table_id" {
  description = "ID of the public route table."
  value       = aws_route_table.public.id
}

output "private_route_table_id" {
  description = "ID of the private route table."
  value       = aws_route_table.private.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Inputs
###############################################################################

variable "cloudhealth_account_id" {
  description = "AWS account ID of the CloudHealth SaaS platform that is trusted to assume the CloudHealth-IAM-Role via sts:AssumeRole. Supplied by CloudHealth during onboarding; never hardcoded in resources."
  type        = string
  default     = "123456789012"
}

variable "external_id" {
  description = "External ID issued by CloudHealth for this integration. Enforced as an sts:ExternalId condition on the role trust policy to prevent the confused-deputy problem. This is a correlation token, not a credential."
  type        = string
  sensitive   = true
  default     = "cloudhealth-external-id"
}

variable "environment" {
  description = "Environment identifier applied to the tags of the CloudHealth integration resources."
  type        = string
  default     = "prod"
}

###############################################################################
# Locals
###############################################################################

locals {
  role_name   = "CloudHealth-IAM-Role"
  policy_name = "CloudHealth-IAM-Role"

  cloudhealth_principal_arn = "arn:aws:iam::${var.cloudhealth_account_id}:root"

  common_tags = {
    ManagedBy   = "Terraform"
    Purpose     = "CloudHealth cost and usage analysis"
    Environment = var.environment
  }
}

###############################################################################
# Cross-account trust policy (external ID conditioned)
###############################################################################

data "aws_iam_policy_document" "cloudhealth_assume_role_policy" {
  statement {
    sid     = "AllowCloudHealthAccountToAssumeRoleWithExternalId"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = [local.cloudhealth_principal_arn]
    }

    condition {
      test     = "StringEquals"
      variable = "sts:ExternalId"
      values   = [var.external_id]
    }
  }
}

resource "aws_iam_role" "cloudhealth_iam_role" {
  name                 = local.role_name
  description          = "Cross-account role assumed by the CloudHealth SaaS platform using an external ID. Grants read-only (describe/list/get) access for cost and usage analysis."
  assume_role_policy   = data.aws_iam_policy_document.cloudhealth_assume_role_policy.json
  max_session_duration = 3600
  tags                 = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Customer-managed read-only policy for cost and usage analysis
###############################################################################

data "aws_iam_policy_document" "cloudhealth_read_only_policy" {
  # ---------------------------------------------------------------------------
  # Cost, billing and pricing
  # ---------------------------------------------------------------------------
  statement {
    sid    = "CostExplorerReadOnly"
    effect = "Allow"
    actions = [
      "ce:Get*",
      "ce:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "BillingBudgetsAndPricingReadOnly"
    effect = "Allow"
    actions = [
      "aws-portal:ViewBilling",
      "aws-portal:ViewUsage",
      "budgets:ViewBudget",
      "budgets:Describe*",
      "cur:DescribeReportDefinitions",
      "pricing:DescribeServices",
      "pricing:GetAttributeValues",
      "pricing:GetProducts",
    ]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Compute
  # ---------------------------------------------------------------------------
  statement {
    sid       = "EC2ReadOnly"
    effect    = "Allow"
    actions   = ["ec2:Describe*"]
    resources = ["*"]
  }

  statement {
    sid       = "AutoScalingReadOnly"
    effect    = "Allow"
    actions   = ["autoscaling:Describe*"]
    resources = ["*"]
  }

  statement {
    sid       = "LambdaReadOnly"
    effect    = "Allow"
    actions   = ["lambda:List*"]
    resources = ["*"]
  }

  statement {
    sid    = "LambdaConfigurationReadOnly"
    effect = "Allow"
    actions = [
      "lambda:GetAccountSettings",
      "lambda:GetFunctionConfiguration",
      "lambda:GetPolicy",
    ]
    resources = ["arn:aws:lambda:*:*:function:*"]
  }

  statement {
    sid       = "ECSReadOnly"
    effect    = "Allow"
    actions   = ["ecs:Describe*", "ecs:List*"]
    resources = ["*"]
  }

  statement {
    sid       = "EKSReadOnly"
    effect    = "Allow"
    actions   = ["eks:Describe*", "eks:List*"]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Storage and databases
  # ---------------------------------------------------------------------------
  statement {
    sid    = "S3BucketMetadataReadOnly"
    effect = "Allow"
    actions = [
      "s3:GetBucketAcl",
      "s3:GetBucketCORS",
      "s3:GetBucketLocation",
      "s3:GetBucketLogging",
      "s3:GetBucketNotification",
      "s3:GetBucketPolicy",
      "s3:GetBucketPolicyStatus",
      "s3:GetBucketPublicAccessBlock",
      "s3:GetBucketRequestPayment",
      "s3:GetBucketTagging",
      "s3:GetBucketVersioning",
      "s3:GetBucketWebsite",
      "s3:GetEncryptionConfiguration",
      "s3:GetLifecycleConfiguration",
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
      "s3:ListBucketVersions",
    ]
    resources = ["arn:aws:s3:::*"]
  }

  statement {
    sid    = "S3ObjectReadOnly"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectAcl",
      "s3:GetObjectTagging",
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:ListMultipartUploadParts",
    ]
    resources = ["arn:aws:s3:::*/*"]
  }

  statement {
    sid    = "S3AccountLevelReadOnly"
    effect = "Allow"
    actions = [
      "s3:GetAccountPublicAccessBlock",
      "s3:ListAllMyBuckets",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "RDSReadOnly"
    effect    = "Allow"
    actions   = ["rds:Describe*", "rds:ListTagsForResource"]
    resources = ["*"]
  }

  statement {
    sid       = "DynamoDBReadOnly"
    effect    = "Allow"
    actions   = ["dynamodb:Describe*", "dynamodb:List*"]
    resources = ["*"]
  }

  statement {
    sid       = "ElastiCacheReadOnly"
    effect    = "Allow"
    actions   = ["elasticache:Describe*", "elasticache:ListTagsForResource"]
    resources = ["*"]
  }

  statement {
    sid       = "RedshiftReadOnly"
    effect    = "Allow"
    actions   = ["redshift:Describe*"]
    resources = ["*"]
  }

  statement {
    sid       = "OpenSearchReadOnly"
    effect    = "Allow"
    actions   = ["es:Describe*", "es:List*"]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Networking and load balancing
  # ---------------------------------------------------------------------------
  statement {
    sid       = "ElasticLoadBalancingReadOnly"
    effect    = "Allow"
    actions   = ["elasticloadbalancing:Describe*"]
    resources = ["*"]
  }

  statement {
    sid       = "Route53ReadOnly"
    effect    = "Allow"
    actions   = ["route53:Get*", "route53:List*"]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Monitoring, auditing and governance
  # ---------------------------------------------------------------------------
  statement {
    sid    = "CloudWatchReadOnly"
    effect = "Allow"
    actions = [
      "cloudwatch:Describe*",
      "cloudwatch:Get*",
      "cloudwatch:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudWatchLogsReadOnly"
    effect = "Allow"
    actions = [
      "logs:Describe*",
      "logs:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudTrailReadOnly"
    effect = "Allow"
    actions = [
      "cloudtrail:Describe*",
      "cloudtrail:Get*",
      "cloudtrail:List*",
      "cloudtrail:LookupEvents",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "CloudFormationReadOnly"
    effect = "Allow"
    actions = [
      "cloudformation:Describe*",
      "cloudformation:GetTemplateSummary",
      "cloudformation:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid       = "SSMInventoryReadOnly"
    effect    = "Allow"
    actions   = ["ssm:Describe*", "ssm:List*"]
    resources = ["*"]
  }

  statement {
    sid    = "TaggingReadOnly"
    effect = "Allow"
    actions = [
      "tag:GetResources",
      "tag:GetTagKeys",
      "tag:GetTagValues",
    ]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Identity, keys and organizations (metadata only, no key material)
  # ---------------------------------------------------------------------------
  statement {
    sid    = "IAMReadOnly"
    effect = "Allow"
    actions = [
      "iam:Get*",
      "iam:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "KMSMetadataReadOnly"
    effect = "Allow"
    actions = [
      "kms:Describe*",
      "kms:List*",
    ]
    resources = ["*"]
  }

  statement {
    sid    = "OrganizationsReadOnly"
    effect = "Allow"
    actions = [
      "organizations:Describe*",
      "organizations:List*",
    ]
    resources = ["*"]
  }

  # ---------------------------------------------------------------------------
  # Health and support (Trusted Advisor checks only)
  # ---------------------------------------------------------------------------
  statement {
    sid       = "HealthReadOnly"
    effect    = "Allow"
    actions   = ["health:Describe*"]
    resources = ["*"]
  }

  statement {
    sid    = "SupportTrustedAdvisorReadOnly"
    effect = "Allow"
    actions = [
      "support:DescribeServices",
      "support:DescribeSeverityLevels",
      "support:DescribeSupportLevel",
      "support:DescribeTrustedAdvisorCheckRefreshStatuses",
      "support:DescribeTrustedAdvisorCheckResult",
      "support:DescribeTrustedAdvisorChecks",
      "support:DescribeTrustedAdvisorCheckSummaries",
    ]
    resources = ["*"]
  }
}

resource "aws_iam_policy" "cloudhealth_iam_role_policy" {
  name        = local.policy_name
  description = "Customer-managed read-only policy granting CloudHealth describe, list and get permissions across AWS services for cost and usage analysis."
  policy      = data.aws_iam_policy_document.cloudhealth_read_only_policy.json
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role_policy_attachment" "cloudhealth_read_only_attach" {
  role       = aws_iam_role.cloudhealth_iam_role.name
  policy_arn = aws_iam_policy.cloudhealth_iam_role_policy.arn
}

###############################################################################
# Outputs (handoff back to CloudHealth)
###############################################################################

output "cloudhealth_role_arn" {
  description = "ARN of the cross-account IAM role that CloudHealth assumes."
  value       = aws_iam_role.cloudhealth_iam_role.arn
}

output "cloudhealth_role_name" {
  description = "Name of the cross-account IAM role that CloudHealth assumes."
  value       = aws_iam_role.cloudhealth_iam_role.name
}

output "cloudhealth_policy_arn" {
  description = "ARN of the customer-managed read-only policy attached to the CloudHealth role."
  value       = aws_iam_policy.cloudhealth_iam_role_policy.arn
}

output "cloudhealth_external_id" {
  description = "External ID enforced by the role trust policy. Exposed for operator verification only; the value is treated as sensitive."
  value       = var.external_id
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"
}

# ---------------------------------------------------------------------------
# Customer Managed KMS Key for the endpoint-backup bucket
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "endpoint_backup_kms_key" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"]
    }

    actions = [
      "kms:*",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowEndpointBackupUserUseOfKey"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.endpoint_backup.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer managed key for endpoint-backup S3 bucket encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.endpoint_backup_kms_key.json

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

# ---------------------------------------------------------------------------
# S3 Bucket
# ---------------------------------------------------------------------------

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
      sse_algorithm     = "aws:kms"
    }
  }
}

# ---------------------------------------------------------------------------
# S3 Bucket Policy
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "endpoint_backup_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:*",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyInsecureTLSVersion"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:*",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyOverlongComplianceModeRetention"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket.json
}

# ---------------------------------------------------------------------------
# IAM User and customer-managed policy
# ---------------------------------------------------------------------------

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"
}

data "aws_iam_policy_document" "endpoint_backup_bucket_access" {
  statement {
    sid    = "BucketLevelListAccess"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:ListBucketMultipartUploads",
      "s3:GetBucketLocation",
    ]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
    ]
  }

  statement {
    sid    = "ObjectLevelReadWriteAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectRetention",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:PutObjectVersionTagging",
      "s3:PutObjectRetention",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:AbortMultipartUpload",
      "s3:RestoreObject",
    ]

    resources = [
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]
  }

  statement {
    sid    = "CustomerManagedKeyDecryptAndDataKeyAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [
      aws_kms_key.endpoint_backup.arn,
    ]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_access" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read/write/versioning/retention/restore access to the endpoint-backup S3 bucket and decrypt/data-key access to the customer managed KMS key used for the bucket."
  policy      = data.aws_iam_policy_document.endpoint_backup_bucket_access.json
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_access.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Providers - four regional configurations (primary + second source + 2 replicas)
###############################################################################

provider "aws" {
  region = "us-east-1"
}

provider "aws" {
  alias  = "source2"
  region = var.source2_region
}

provider "aws" {
  alias  = "replica1"
  region = var.replica1_region
}

provider "aws" {
  alias  = "replica2"
  region = var.replica2_region
}

###############################################################################
# Input variables
###############################################################################

variable "source2_region" {
  description = "Second source region for the cross-region replication setup."
  type        = string
  default     = "us-west-2"
}

variable "replica1_region" {
  description = "First replica region for the cross-region replication setup."
  type        = string
  default     = "eu-west-1"
}

variable "replica2_region" {
  description = "Second replica region for the cross-region replication setup."
  type        = string
  default     = "ap-southeast-1"
}

variable "environment" {
  description = "Environment tag applied to every resource (request scope is dev)."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Additional common tags merged onto every taggable resource."
  type        = map(string)
  default     = {}
}

###############################################################################
# Static provider metadata / account identity
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Local values
###############################################################################

locals {
  account_id     = data.aws_caller_identity.current.account_id
  partition      = data.aws_partition.current.partition
  source1_region = "us-east-1"

  common_tags = merge(
    {
      Env       = var.environment
      ManagedBy = "terraform"
    },
    var.tags,
  )

  # Source bucket base names (without account id)
  source1_buckets = {
    log1a = "log1a.veerum"
    log1b = "log1b.veerum"
  }

  source2_buckets = {
    log2a = "log2a.veerum"
    log2b = "log2b.veerum"
  }

  all_source_bases = merge(local.source1_buckets, local.source2_buckets)

  # Replica bucket base names (still without account id)
  replica1_buckets = {
    for k, v in local.all_source_bases : k => "${v}-replica1"
  }

  replica2_buckets = {
    for k, v in local.all_source_bases : k => "${v}-replica2"
  }
}

###############################################################################
# KMS key policies
###############################################################################

data "aws_iam_policy_document" "source1_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationDecrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }
    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${local.source1_region}.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "source2_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationDecrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }
    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.source2_region}.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replica1_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationEncrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica1_region}.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replica2_kms" {
  statement {
    sid    = "EnableRootAccountAdmin"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }
    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowS3ReplicationEncrypt"
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.s3_replication.arn]
    }
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]
    resources = ["*"]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${var.replica2_region}.amazonaws.com"]
    }
  }
}

