###############################################################################

resource "aws_kms_key" "source1" {
  description             = "Source CMK 1 for S3 log replication (${local.source1_region})"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.source1_kms.json

  tags = merge(local.common_tags, { Name = "sourcekey1" })

  lifecycle {
