###############################################################################
# IAM role assumed by S3 for cross-region replication
###############################################################################

resource "aws_iam_role" "s3_replication" {
  name = "s3-crr-log-replication-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = merge(local.common_tags, { Name = "s3-crr-log-replication-role" })
}

###############################################################################
# Least-privilege customer-managed replication policy
###############################################################################

data "aws_iam_policy_document" "s3_replication" {
  statement {
    sid = "AllowSourceBucketRead"
    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:ListBucketMultipartUploads",
    ]
    resources = [
      aws_s3_bucket.source1["log1a"].arn,
      aws_s3_bucket.source1["log1b"].arn,
      aws_s3_bucket.source2["log2a"].arn,
      aws_s3_bucket.source2["log2b"].arn,
    ]
  }

  statement {
    sid = "AllowSourceObjectRead"
    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]
    resources = [
      "${aws_s3_bucket.source1["log1a"].arn}/*",
      "${aws_s3_bucket.source1["log1b"].arn}/*",
      "${aws_s3_bucket.source2["log2a"].arn}/*",
      "${aws_s3_bucket.source2["log2b"].arn}/*",
    ]
  }

  statement {
    sid = "AllowReplicaObjectWrite"
    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]
    resources = [
      "${aws_s3_bucket.replica1["log1a"].arn}/*",
      "${aws_s3_bucket.replica1["log1b"].arn}/*",
      "${aws_s3_bucket.replica1["log2a"].arn}/*",
      "${aws_s3_bucket.replica1["log2b"].arn}/*",
      "${aws_s3_bucket.replica2["log1a"].arn}/*",
      "${aws_s3_bucket.replica2["log1b"].arn}/*",
      "${aws_s3_bucket.replica2["log2a"].arn}/*",
      "${aws_s3_bucket.replica2["log2b"].arn}/*",
    ]
  }

  statement {
    sid     = "AllowDecryptSourceKeys"
    actions = ["kms:Decrypt", "kms:DescribeKey"]
    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values = [
        "s3.${local.source1_region}.amazonaws.com",
        "s3.${var.source2_region}.amazonaws.com",
      ]
    }
  }

  statement {
    sid = "AllowEncryptReplicaKeys"
    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]
    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values = [
        "s3.${var.replica1_region}.amazonaws.com",
        "s3.${var.replica2_region}.amazonaws.com",
      ]
    }
  }
}

resource "aws_iam_policy" "s3_replication" {
  name        = "s3-crr-log-replication-policy"
  description = "Least-privilege policy allowing S3 to replicate Env=dev log buckets across regions."
  policy      = data.aws_iam_policy_document.s3_replication.json

  tags = merge(local.common_tags, { Name = "s3-crr-log-replication-policy" })
}

resource "aws_iam_role_policy_attachment" "s3_replication" {
  role       = aws_iam_role.s3_replication.name
  policy_arn = aws_iam_policy.s3_replication.arn
}

