###############################################################################
# Bucket policies - enforce TLS-only and KMS-encrypted uploads
###############################################################################

data "aws_iam_policy_document" "source1_policy" {
  for_each = local.source1_buckets

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions = ["s3:*"]
    resources = [
      aws_s3_bucket.source1[each.key].arn,
      "${aws_s3_bucket.source1[each.key].arn}/*",
    ]
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyUnencryptedObjectUploads"
    effect = "Deny"
    principals {
      type        = "*"
      identifiers = ["*"]
    }
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.source1[each.key].arn}/*"]
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption"
      values   = ["aws:kms"]
    }
  }
}

data "aws_iam_policy_document" "source2_policy" {
  for_each = local.source2_buckets

  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"
    principals {
