###############################################################################
# Replication - primary source region buckets (2 rules each)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source1" {
  for_each = local.source1_buckets

  bucket = aws_s3_bucket.source1[each.key].id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "replicate-to-replica1-${var.replica1_region}"
    status   = "Enabled"
    priority = 10

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "replicate-to-replica2-${var.replica2_region}"
    status   = "Enabled"
    priority = 20

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source1,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.s3_replication,
  ]
}

###############################################################################
# Replication - second source region buckets (2 rules each)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "source2" {
  for_each = local.source2_buckets
  provider = aws.source2

  bucket = aws_s3_bucket.source2[each.key].id
  role   = aws_iam_role.s3_replication.arn

  rule {
    id       = "replicate-to-replica1-${var.replica1_region}"
    status   = "Enabled"
    priority = 10

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica1[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica1.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  rule {
    id       = "replicate-to-replica2-${var.replica2_region}"
    status   = "Enabled"
    priority = 20

    filter {}

    destination {
      bucket        = aws_s3_bucket.replica2[each.key].arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica2.arn
      }
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    delete_marker_replication {
      status = "Enabled"
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.source2,
    aws_s3_bucket_versioning.replica1,
    aws_s3_bucket_versioning.replica2,
    aws_iam_role_policy_attachment.s3_replication,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "source1_bucket_names" {
  description = "Primary source region bucket names."
  value       = { for k, v in aws_s3_bucket.source1 : k => v.bucket }
}

output "source2_bucket_names" {
  description = "Second source region bucket names."
  value       = { for k, v in aws_s3_bucket.source2 : k => v.bucket }
}

output "replica1_bucket_names" {
  description = "First replica region bucket names."
  value       = { for k, v in aws_s3_bucket.replica1 : k => v.bucket }
}

output "replica2_bucket_names" {
  description = "Second replica region bucket names."
  value       = { for k, v in aws_s3_bucket.replica2 : k => v.bucket }
}

output "kms_key_aliases" {
  description = "Regional CMK aliases used for encryption."
  value = {
    source1  = aws_kms_alias.source1.name
    source2  = aws_kms_alias.source2.name
    replica1 = aws_kms_alias.replica1.name
    replica2 = aws_kms_alias.replica2.name
  }
}

output "replication_role_arn" {
  description = "ARN of the IAM role S3 assumes for cross-region replication."
  value       = aws_iam_role.s3_replication.arn
}
